INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C1','soc',6,2,'u1',1,'세계의 다양한 지형과 지형 경관 — 세계에는 산지·하천·해안·사막 등 다양한 지형이 있고, 같은 갈래의 지형도 저마다 독특한 경관 특징이 있으며(피오르·아치 바위·화산·위가 평평한 산 등), 지형 경관은 그곳 사람들의 생활 모습에 영향을 줌 · 조사는 인터넷 조사 → 정리 → 소개 자료 → 발표',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C2','soc',6,2,'u1',2,'산지 지형과 생활 모습 — 산지는 해발 고도가 높고 대체로 경사가 급하지만 고원처럼 넓고 평평한 곳, 정상이 움푹 파이거나 물이 고인 화산도 있으며, 사람들은 계단식 농사·가축 기르기·광업·관광(스키장·휴양림·화산 관광)으로 산지를 이용함',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C3','soc',6,2,'u1',3,'하천 지형과 생활 모습 — 하천을 따라 계곡·넓은 평야·거대한 폭포가 나타나고, 사람들은 어업·평야의 큰 규모 농사·수력 발전·폭포 관광·물건을 나르고 사고파는 수상 시장으로 하천을 이용함(강이 나른 흙이 쌓여 평야)',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C4','soc',6,2,'u1',4,'해안 지형과 생활 모습 — 바다와 육지가 만나는 해안에는 갯벌·모래사장·절벽·돌기둥이 나타나고, 사람들은 어업·양식업을 하며 배가 드나들기 좋은 곳에 항구, 경관이 아름다운 곳에 관광지, 갯벌이 넓은 곳에 염전을 둠 · 관광은 일자리·소득과 쓰레기·오염을 함께 늘림',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C5','soc',6,2,'u1',6,'기후의 뜻과 세계의 기후 분포 — 기후는 한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태(날씨와 다름)이고, 위도뿐 아니라 위치·지형·해발 고도에 따라 달라지며, 기온과 강수량을 기준으로 열대·건조·온대·냉대·한대·고산 기후로 나눔 — 적도에서 극으로 열대→건조→온대→냉대→한대, 적도를 기준으로 남북이 비슷(냉대는 주로 북반구), 매우 높은 산지는 고산, 우리나라는 온대·냉대',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C6','soc',6,2,'u1',7,'열대 기후와 생활 모습 — 적도 주변 저위도, 일 년 내내 기온이 높고 기온 변화가 거의 없음, 비가 많아 열대 우림이 되거나 건기·우기가 번갈아 초원이 펼쳐짐 · 화전 농업(카사바·얌·옥수수), 천연고무·카카오·바나나·커피 대규모 재배, 생태 관광, 바람이 통하는 큰 창·바닥을 띄운 고상 가옥·얇은 옷',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C7','soc',6,2,'u1',7,'건조 기후와 생활 모습 — 저위도·중위도의 강수량이 적은 곳, 낮과 밤의 기온 차이가 큼, 사막 또는 약간의 비로 초원 · 햇볕과 모래바람을 막는 온몸을 감싸는 옷, 벽이 두껍고 창이 작은 흙벽돌 집, 오아시스 주변 농사, 초원의 유목 생활과 이동식 가옥',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C8','soc',6,2,'u1',8,'온대 기후·냉대 기후와 생활 모습 — 온대는 중위도, 사계절이 비교적 뚜렷, 서부 유럽(여름 서늘·겨울 따뜻·비 고름 — 밀·낙농업)·지중해 주변(여름 덥고 건조·겨울 비 — 올리브·포도)·우리나라(여름 덥고 비·겨울 춥고 건조 — 벼농사) · 냉대는 북반구 중·고위도, 겨울이 여름보다 길고 몹시 추우며 눈이 많음, 여름에 밀·옥수수·감자, 침엽수림으로 목재·펄프 생산',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C9','soc',6,2,'u1',9,'한대 기후·고산 기후와 생활 모습 — 한대는 남극·북극 주변 고위도, 겨울이 길고 기온이 매우 낮아 눈과 얼음에 덮인 곳이 많음, 사냥한 생선·고기, 이끼 자라는 곳의 순록 유목, 지하자원 개발·극지 연구, 오로라·빙하 관광 · 고산은 해발 고도가 높은 곳, 적도 주변 일부는 일 년 내내 서늘해 사람이 많이 모여 삶, 감자·옥수수, 알파카·라마, 챙 넓은 둥근 모자·여러 겹 옷과 망토로 낮과 밤의 기온 차이에 적응 · 추운 기후로 가는 길은 둘(고위도·고산)',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u1-C10','soc',6,2,'u1',10,'기후에 적응·극복하는 생활 조사와 자연환경을 고려한 상품 계획 — 사람들은 기후에 적응하고 이를 극복하며 살아가고 같은 기후에서도 생활 모습은 여러 가지임 · 조사: 주제 정하기 → 인터넷 조사 → 디지털 영상 지도에 표시 → 공유 · 상품 계획: 나라 정하기 → 지형과 기후 조사 → 아이디어 이야기 → 판매 계획 → 글과 그림, 자연환경의 특징을 상품 기능에 담고 실현 가능성도 생각',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X01','soc',6,'u1',ARRAY['SO6-2-u1-C1']::text[],'세계의 지형은 모두 비슷하거나, 같은 갈래(산지 등)의 지형은 경관 특징도 하나뿐이라고 여긴다','같은 산지라도 — 화산? 위가 평평? 거대한 바위?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X02','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'지형 경관이나 기후는 그곳 사람들의 생활 모습과 관계가 없다고 여긴다','「그래서 그곳 사람들은 무엇을 하며 살까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X03','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C2','SO6-2-u1-C3','SO6-2-u1-C4']::text[],'지형의 갈래(산지·하천·해안·사막)를 헷갈린다(피오르를 하천으로, 수상 시장을 해안으로 등)','바다와 육지가 만나나? 강을 따라가나? 높이 솟았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X04','soc',6,'u1',ARRAY['SO6-2-u1-C2']::text[],'산지는 모두 경사가 급해 사람이 살 수 없다고 여기거나, 고원·화산 같은 산지의 여러 모습을 모른다','고원은 넓고 평평 — 가축을 길러요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X05','soc',6,'u1',ARRAY['SO6-2-u1-C3']::text[],'하천 지역의 생활(평야 농사·어업·수력 발전·폭포 관광·수상 시장)을 다른 지형의 생활과 헷갈린다','물이 흐르며 무엇을 주나? 흙·물고기·힘·길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X06','soc',6,'u1',ARRAY['SO6-2-u1-C4']::text[],'해안의 이용을 자리와 맞지 않게 짝짓는다(배가 드나들기 좋은 곳에 염전, 갯벌에 항구 등)','배 → 항구 · 넓은 갯벌 → 염전 · 아름다운 경관 → 관광지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X07','soc',6,'u1',ARRAY['SO6-2-u1-C4','SO6-2-u1-C10']::text[],'관광이나 개발의 한쪽 영향(좋은 점만 또는 나쁜 점만)만 본다','늘어나는 것 둘 — 일자리·소득과 쓰레기·오염') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X08','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후를 하루나 며칠의 날씨와 같은 것으로 여긴다','여러 해에 걸쳐 되풀이되는 평균 상태') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X09','soc',6,'u1',ARRAY['SO6-2-u1-C5','SO6-2-u1-C9']::text[],'기후가 위도만으로 정해진다고 여겨 위치·지형·해발 고도의 영향을 놓친다(적도 주변은 어디나 덥다)','적도 주변이라도 산 위로 오르면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X10','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후 구분의 기준(기온과 강수량)이나 적도에서 극으로 가는 기후의 차례를 헷갈린다','열대 → 건조 → 온대 → 냉대 → 한대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X11','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'열대 기후와 건조 기후의 특징을 헷갈린다(열대는 일교차가 크다, 건조는 비가 많다 등)','열대 — 늘 덥고 비 많음 · 건조 — 비 적고 낮밤 차이 큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X12','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'기후에 맞춘 집·옷·농업을 다른 기후의 것과 바꾸어 짝짓는다(사막에 고상 가옥, 열대에 두꺼운 벽 등)','그 기후에서 막을 것과 들일 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X13','soc',6,'u1',ARRAY['SO6-2-u1-C8']::text[],'온대 기후와 냉대 기후, 또는 온대 안의 서부 유럽·지중해·우리나라의 특징과 농업을 헷갈린다','겨울이 여름보다 길고 몹시 추우면 냉대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X14','soc',6,'u1',ARRAY['SO6-2-u1-C9']::text[],'한대 기후와 고산 기후를 헷갈리거나, 고산 기후는 극지방에만 있다고 여긴다','고위도로 멀리 → 한대 · 높이 오르면 → 고산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X15','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7','SO6-2-u1-C8','SO6-2-u1-C10']::text[],'한 곳의 생활 모습을 그 기후 전체의 모습으로 여기거나, 같은 기후 지역은 생활이 모두 같다고 여긴다','같은 온대에도 밀·올리브·벼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X16','soc',6,'u1',ARRAY['SO6-2-u1-C10']::text[],'상품을 구상할 때 그곳의 지형·기후를 고려하지 않거나 한 상품이 어디서나 똑같이 쓰인다고 여긴다','그곳 사람들의 불편은 자연환경의 어떤 특징에서 오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u1-X17','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'조사·계획의 차례를 헷갈리거나 출처를 확인하지 않고 자료를 쓴다','정하고 → 조사하고 → 정리하고 → 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#1','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'mc','auto','세계의 지형에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"세계의 지형에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"세계에는 산지·하천·해안·사막 등 다양한 지형이 있다","correct":true},{"t":"세계에는 산지만 있다","mis":"SO6-2-u1-X01"},{"t":"세계의 지형은 어디나 같은 모습이다","mis":"SO6-2-u1-X01"},{"t":"세계에는 바다와 사막만 있다","mis":"SO6-2-u1-X01"}],"explanation":["세계에는 여러 갈래의 지형이 있어요.","산지·하천·해안·사막이 대표적이에요.","지형마다 경관의 특징이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#2','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'mc','auto','「피오르」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"「피오르」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"빙하가 깎아 만든 유(U) 자 모양 골짜기에 바닷물이 들어와 생긴 해안","correct":true},{"t":"용암이 흘러 굳어서 생긴 화산","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진 땅","mis":"SO6-2-u1-X03"},{"t":"강물이 높은 곳에서 떨어지는 곳","mis":"SO6-2-u1-X03"}],"explanation":["피오르는 빙하가 만든 골짜기예요.","그 골짜기에 바닷물이 들어왔어요.","그래서 가파른 산 사이로 좁고 긴 바다가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#3','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'ox','auto','지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줘요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"ox","stem":"지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줘요.","answer":"O","reason_options":[{"t":"지형에 따라 농사·일·여행처럼 사람들이 살아가는 방법이 달라지기 때문에","correct":true},{"t":"지형은 자연이고 생활은 사람의 일이라 서로 관계가 없기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["경관이 아름다운 곳은 여행지가 되기도 해요.","지형에 따라 할 수 있는 일이 달라요.","그래서 지형 경관은 생활 모습에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#4','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'sa','auto','세계의 대표적인 지형 네 가지는 산지·하천·해안 그리고 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"sa","stem":"세계의 대표적인 지형 네 가지는 산지·하천·해안 그리고 무엇인가요? 두 글자로 쓰세요.","answer":["사막"],"explanation":["지형은 크게 네 갈래로 나누어 살펴보았어요.","산지·하천·해안·사막이에요.","사하라는 대표적인 사막이에요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#5','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'match','auto','지형과 그 지형이 드는 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"match","stem":"지형과 그 지형이 드는 갈래를 알맞게 이으세요.","pairs":[{"l":"송네 피오르","r":"해안"},{"l":"황허강","r":"하천"},{"l":"사하라","r":"사막"},{"l":"마우나로아","r":"산지"}],"mis":"SO6-2-u1-X03","explanation":["피오르는 바다와 육지가 만나는 해안이에요.","황허강은 하천, 사하라는 사막이에요.","마우나로아는 화산이라 산지예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#6','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','일곱 곳 가운데 산지에 드는 세 곳이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"일곱 곳 가운데 산지에 드는 세 곳이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 산지라도 화산·거대한 바위·위가 평평한 산처럼 서로 다른 특징이 나타나기 때문에","correct":true},{"t":"산지는 한 가지 모습만 있는 지형이기 때문에","mis":"SO6-2-u1-X01"},{"t":"세 곳이 모두 바닷가에 있기 때문에","mis":"SO6-2-u1-X03"},{"t":"세 곳이 같은 나라에 있기 때문에","mis":"SO6-2-u1-X01"}],"explanation":["마우나로아는 용암이 흐르는 화산이에요.","울루루는 하나의 거대한 암석, 호라이마산은 위가 평평해요.","같은 갈래 안에서도 특징이 갈려요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#7','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','엘 아르코의 경관 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"엘 아르코의 경관 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다 위에 아치 모양의 바위가 솟아 있다","correct":true},{"t":"누런 강물이 굽이쳐 흐른다","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진다","mis":"SO6-2-u1-X03"},{"t":"용암이 흐르는 화산이다","mis":"SO6-2-u1-X03"}],"explanation":["엘 아르코는 바닷가에 있어요.","아치 모양의 바위가 바다 위로 솟아 있어요.","해안 지형의 경관이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#8','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','세계의 지형 경관과 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"세계의 지형 경관과 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인터넷으로 조사하기 → 조사 내용 정리하기 → 소개 자료 만들기 → 발표하기","correct":true},{"t":"발표하기 → 인터넷으로 조사하기 → 소개 자료 만들기 → 정리하기","mis":"SO6-2-u1-X17"},{"t":"소개 자료 만들기 → 발표하기 → 조사하기 → 정리하기","mis":"SO6-2-u1-X17"},{"t":"정리하기 → 발표하기 → 조사하기 → 소개 자료 만들기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 조사해요.","조사한 것을 정리해 소개 자료로 만들어요.","그다음 친구들 앞에서 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#9','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'ox','auto','울루루와 호라이마산은 둘 다 산지이므로 경관 특징도 똑같아요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"ox","stem":"울루루와 호라이마산은 둘 다 산지이므로 경관 특징도 똑같아요.","answer":"X","reason_options":[{"t":"울루루는 하나의 거대한 암석이고 호라이마산은 위가 평평해 같은 산지라도 특징이 다르기 때문에","correct":true},{"t":"산지에 드는 곳은 모두 모습이 같기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["같은 갈래에 든다고 모습이 같은 것은 아니에요.","울루루 — 평지에 솟은 거대한 암석이에요.","호라이마산 — 솟았지만 위가 평평해요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_basic#10','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',3,'error','auto','세계의 지형 경관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"세계의 지형 경관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「바닷가에 있는지만 보면 일곱 곳을 모두 다 가를 수 있어.」","correct":true,"mis_target":"SO6-2-u1-X01"},{"t":"로운 — 「위쪽이 평평한지 물으면 호라이마산을 다른 산지와 가를 수 있어.」","mis":"SO6-2-u1-X01"},{"t":"서윤 — 「용암이 흐르는지 물으면 마우나로아를 가를 수 있어.」","mis":"SO6-2-u1-X01"}],"explanation":["바닷가에 있는 곳은 피오르와 엘 아르코 둘뿐이에요.","그 물음으로는 나머지 다섯 곳이 갈리지 않아요.","특징을 하나씩 물어야 저마다 다른 경관이 보여요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#1','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',2,'sa','auto','빙하가 깎아 만든 골짜기에 바닷물이 들어와 생긴, 가파른 산 사이의 좁고 긴 해안 지형을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"sa","stem":"빙하가 깎아 만든 골짜기에 바닷물이 들어와 생긴, 가파른 산 사이의 좁고 긴 해안 지형을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["피오르"],"explanation":["노르웨이의 송네 피오르가 대표적이에요.","빙하가 유(U) 자 골짜기를 깎았어요.","그 골짜기에 바닷물이 들어왔어요."],"mis":"SO6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#2','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',2,'mc','auto','「바닷가에 있나요?」라는 물음으로 일곱 곳을 가를 때 「예」에 드는 곳을 바르게 모은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「바닷가에 있나요?」라는 물음으로 일곱 곳을 가를 때 「예」에 드는 곳을 바르게 모은 것은 어느 것인가요?","options":[{"t":"송네 피오르 · 엘 아르코","correct":true},{"t":"송네 피오르 · 황허강","mis":"SO6-2-u1-X03"},{"t":"마우나로아 · 울루루","mis":"SO6-2-u1-X03"},{"t":"사하라 사막 · 호라이마산","mis":"SO6-2-u1-X03"}],"explanation":["바다와 육지가 만나는 곳은 해안이에요.","송네 피오르와 엘 아르코가 해안 지형이에요.","황허강은 강, 나머지는 산지와 사막이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#3','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'mc','auto','같은 산지에 든 마우나로아·울루루·호라이마산을 서로 가를 수 있는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"같은 산지에 든 마우나로아·울루루·호라이마산을 서로 가를 수 있는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「용암이 흐르는 화산인가요?」","correct":true},{"t":"「바닷가에 있나요?」","mis":"SO6-2-u1-X01"},{"t":"「지구에 있나요?」","mis":"SO6-2-u1-X01"},{"t":"「이름이 있나요?」","mis":"SO6-2-u1-X01"}],"explanation":["세 곳은 모두 바닷가가 아닌 산지예요.","그래서 바닷가 물음으로는 갈리지 않아요.","화산인지 물으면 마우나로아가 갈라져요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#4','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C2',3,'ox','auto','경관이 아름다운 지형은 여행지가 되어 그곳 사람들의 일과 생활이 달라지기도 해요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"ox","stem":"경관이 아름다운 지형은 여행지가 되어 그곳 사람들의 일과 생활이 달라지기도 해요.","answer":"O","reason_options":[{"t":"여행객이 찾아오면 안내·숙소·가게 같은 일이 생겨 생활 모습이 바뀌기 때문에","correct":true},{"t":"여행지는 그곳 사람들의 생활과 상관없이 정해지기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["지형 경관은 생활에 영향을 줘요.","아름다운 경관은 관광으로 이어져요.","관광은 그곳 사람들의 일을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#5','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'mc','auto','황허강이 누런 색을 띠는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"황허강이 누런 색을 띠는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"강물에 황토가 섞여 흐르기 때문에","correct":true},{"t":"강 위에 모래 언덕이 있기 때문에","mis":"SO6-2-u1-X03"},{"t":"강물이 용암에서 나오기 때문에","mis":"SO6-2-u1-X03"},{"t":"강이 바다 한가운데 있기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["황허강은 중국의 큰 강이에요.","황토가 섞인 물이 굽이쳐 흘러요.","그래서 강물이 누렇게 보여요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#6','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'error','auto','세계의 지형 경관 소개 자료를 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"세계의 지형 경관 소개 자료를 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하준 — 「누가 올렸는지 몰라도 사진이 멋지면 그대로 써.」","correct":true,"mis_target":"SO6-2-u1-X17"},{"t":"예나 — 「조사한 내용을 정리표에 담고 그걸로 소개 자료를 만들자.」","mis":"SO6-2-u1-X17"},{"t":"도현 — 「자료를 찾은 곳을 소개 자료 끝에 적어 두자.」","mis":"SO6-2-u1-X17"}],"explanation":["조사 자료는 믿을 만한 곳에서 찾아요.","찾은 곳(출처)을 적어 두어요.","예나와 도현은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#7','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'match','auto','지형과 그 경관 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"match","stem":"지형과 그 경관 특징을 알맞게 이으세요.","pairs":[{"l":"호라이마산","r":"우뚝 솟았지만 위쪽이 평평하다"},{"l":"울루루","r":"하나의 거대한 암석이 평지에 솟아 있다"},{"l":"마우나로아","r":"용암이 흐르는 화산이다"},{"l":"사하라","r":"모래 언덕이 끝없이 펼쳐진다"}],"mis":"SO6-2-u1-X01","explanation":["같은 산지라도 특징이 달라요.","호라이마산·울루루·마우나로아는 모두 산지예요.","사하라는 사막이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#8','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'mc','auto','일곱 곳을 산지·하천·해안·사막으로 나눈 뒤 「한 칸에 여럿이 모인 자리」가 생겼어요. 이 자리를 더 가를 수 있는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"mc","stem":"일곱 곳을 산지·하천·해안·사막으로 나눈 뒤 「한 칸에 여럿이 모인 자리」가 생겼어요. 이 자리를 더 가를 수 있는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 칸에 모인 곳들이 서로 다르게 답할 특징 물음을 댄다","correct":true},{"t":"모두에게 같은 답이 나오는 물음을 계속 댄다","mis":"SO6-2-u1-X01"},{"t":"칸 이름을 더 길게 바꾼다","mis":"SO6-2-u1-X03"},{"t":"한 칸에 모인 곳은 모두 같은 지형이니 그대로 둔다","mis":"SO6-2-u1-X01"}],"explanation":["답이 같은 물음으로는 갈리지 않아요.","「화산인가요?」, 「위가 평평한가요?」처럼 서로 다르게 답할 물음이 필요해요.","그러면 같은 갈래 안의 다른 특징이 드러나요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#9','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','송네 피오르와 사하라 사막의 경관 특징을 한 가지씩 쓰고, 두 지형 경관이 그곳 사람들의 생활 모습에 어떤 영향을 줄지 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"송네 피오르와 사하라 사막의 경관 특징을 한 가지씩 쓰고, 두 지형 경관이 그곳 사람들의 생활 모습에 어떤 영향을 줄지 짐작해 쓰세요.","answer_guide":{"answer":"예: 송네 피오르는 가파른 산 사이로 좁고 긴 바다가 들어와 있고, 사하라 사막은 모래 언덕이 끝없이 펼쳐져 있다. 송네 피오르는 경관이 아름다워 배를 타고 구경하는 관광이 발달할 것 같고, 사하라 사막은 물이 적어 사람들이 물을 찾아 옮겨 다니거나 오아시스 주변에 모여 살 것 같다.","scoring_points":["두 지형의 경관 특징을 한 가지씩 바르게 썼는가","경관이 생활에 영향을 준다는 점을 썼는가","지형마다 알맞은 생활 모습을 짐작했는가"]},"explanation":["지형마다 경관 특징이 달라요.","경관은 생활에 영향을 줘요.","근거를 들어 짐작해요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L01_challenge#10','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','세계의 지형 경관 하나를 골라 조사해 소개 자료를 만든다고 할 때, 조사하는 차례를 쓰고 소개 자료에 꼭 넣을 내용을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"세계의 지형 경관 하나를 골라 조사해 소개 자료를 만든다고 할 때, 조사하는 차례를 쓰고 소개 자료에 꼭 넣을 내용을 두 가지 쓰세요.","answer_guide":{"answer":"예: 인터넷으로 조사하기 → 조사 내용 정리하기 → 소개 자료 만들기 → 발표하기의 차례로 한다. 소개 자료에는 그 지형의 경관 특징과 그곳 사람들의 생활 모습을 꼭 넣고, 자료를 찾은 곳도 적는다.","scoring_points":["조사 차례를 바르게 썼는가","경관 특징과 생활 모습을 넣었는가","자료를 찾은 곳(출처)을 생각했는가"]},"explanation":["조사 → 정리 → 소개 자료 → 발표예요.","경관과 생활을 함께 담아요.","출처도 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#1','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'mc','auto','산지 지형의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지형의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"해발 고도가 높고 대체로 경사가 급하다","correct":true},{"t":"바다와 육지가 만나는 곳이다","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진다","mis":"SO6-2-u1-X03"},{"t":"강물이 흙을 날라 넓은 평야가 생긴다","mis":"SO6-2-u1-X03"}],"explanation":["산지는 높이 솟은 땅이에요.","대체로 경사가 급해요.","바다와 만나는 곳은 해안, 흙이 쌓인 평야는 하천 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#2','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'sa','auto','바다 표면으로부터 잰 육지의 높이를 무엇이라고 하나요? 「해발 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"sa","stem":"바다 표면으로부터 잰 육지의 높이를 무엇이라고 하나요? 「해발 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["고도"],"explanation":["산지는 해발 고도가 높아요.","해발 고도는 바다 표면을 기준으로 재요.","고산 기후를 배울 때도 쓰여요."],"mis":"SO6-2-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#3','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'ox','auto','산지에는 경사가 급한 곳만 있어요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"ox","stem":"산지에는 경사가 급한 곳만 있어요.","answer":"X","reason_options":[{"t":"고원처럼 비교적 넓고 평평한 곳도 있고, 정상이 움푹 파인 화산도 있기 때문에","correct":true},{"t":"산지는 모두 뾰족한 봉우리로만 되어 있기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["산지는 대체로 경사가 급해요.","하지만 고원처럼 넓고 평평한 곳도 있어요.","화산은 정상이 움푹 파이거나 물이 고이기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#4','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'mc','auto','세계의 유명한 산지 지형이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"세계의 유명한 산지 지형이 아닌 것은 어느 것인가요?","options":[{"t":"나일강","correct":true},{"t":"히말라야산맥","mis":"SO6-2-u1-X03"},{"t":"알프스산맥","mis":"SO6-2-u1-X03"},{"t":"파미르고원","mis":"SO6-2-u1-X03"}],"explanation":["히말라야·알프스는 큰 산맥이에요.","파미르고원도 산지예요.","나일강은 하천 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#5','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'match','auto','산지와 그곳 사람들의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"match","stem":"산지와 그곳 사람들의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"파미르고원(타지키스탄)","r":"평탄한 땅의 풀로 양을 기른다"},{"l":"알프스산맥(스위스)","r":"아름다운 경관으로 관광지가 발달했다"},{"l":"추키카마타(칠레)","r":"구리를 캐는 광업이 발달했다"},{"l":"아이슬란드","r":"화산 분출을 보는 곳을 관광지로 쓴다"}],"mis":"SO6-2-u1-X02","explanation":["산지의 모습에 따라 생활이 달라요.","평탄한 고원은 가축, 아름다운 경관은 관광이에요.","지하자원이 많으면 광업이 발달해요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#6','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','산지의 경사가 가파른 곳에서 농사짓는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"산지의 경사가 가파른 곳에서 농사짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"산비탈을 계단처럼 깎아 계단식 농사를 짓는다","correct":true},{"t":"대형 농기계로 넓은 평야를 한꺼번에 간다","mis":"SO6-2-u1-X05"},{"t":"갯벌에 바닷물을 가두어 소금을 만든다","mis":"SO6-2-u1-X06"},{"t":"비행기로 씨를 뿌려 넓은 밭을 가꾼다","mis":"SO6-2-u1-X05"}],"explanation":["가파른 땅은 그대로 농사짓기 어려워요.","비탈을 계단처럼 만들면 평평한 땅이 생겨요.","사람들은 지형을 이용해 살아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#7','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','칠레 추키카마타에서 광업이 발달한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X05','SO6-2-u1-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"칠레 추키카마타에서 광업이 발달한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"땅속에 구리가 많이 묻혀 있기 때문에","correct":true},{"t":"경치가 아름다워 관광객이 많기 때문에","mis":"SO6-2-u1-X02"},{"t":"넓은 평야가 펼쳐져 있기 때문에","mis":"SO6-2-u1-X05"},{"t":"바다와 가까워 항구가 있기 때문에","mis":"SO6-2-u1-X06"}],"explanation":["지하자원이 풍부한 산지에서는 광업이 발달해요.","추키카마타는 구리 매장량이 많아요.","산지의 이용은 그 땅이 가진 것에 따라 달라요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#8','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'ox','auto','산지의 아름다운 지형 경관은 스키장이나 휴양림 같은 관광지로 이용되기도 해요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"ox","stem":"산지의 아름다운 지형 경관은 스키장이나 휴양림 같은 관광지로 이용되기도 해요.","answer":"O","reason_options":[{"t":"사람들이 아름다운 경관을 즐기러 찾아와 관광이 발달하기 때문에","correct":true},{"t":"산지에는 사람이 찾아가지 않기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["알프스산맥은 관광지로 유명해요.","스키장·휴양림도 산지를 이용한 곳이에요.","화산도 관광지가 되기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#9','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','칠레 파리나코타 화산 지역 사람들의 생활 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"칠레 파리나코타 화산 지역 사람들의 생활 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"화산을 보러 온 관광객에게 여행을 안내하거나 물건을 판다","correct":true},{"t":"배 위에서 물건을 사고판다","mis":"SO6-2-u1-X05"},{"t":"갯벌에서 소금을 만든다","mis":"SO6-2-u1-X06"},{"t":"넓은 평야에서 비행기로 농사짓는다","mis":"SO6-2-u1-X05"}],"explanation":["화산은 많은 사람이 보러 오는 경관이에요.","그곳 사람들은 관광과 관련된 일을 해요.","수상 시장은 하천, 염전은 해안의 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_basic#10','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',3,'error','auto','산지 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X02']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"error","stem":"산지 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「산지는 높고 험하니 사람이 살지 않고 아무 일도 하지 않아.」","correct":true,"mis_target":"SO6-2-u1-X04"},{"t":"수빈 — 「평탄한 고원에서는 가축을 기르기도 해.」","mis":"SO6-2-u1-X04"},{"t":"지후 — 「지하자원이 많은 산지에서는 광업이 발달하기도 해.」","mis":"SO6-2-u1-X02"}],"explanation":["산지에서도 사람들은 지형을 이용해 살아가요.","농사·가축·광업·관광을 해요.","수빈과 지후는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#1','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',2,'sa','auto','산지 가운데 높은 곳에 비교적 넓고 평평하게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"sa","stem":"산지 가운데 높은 곳에 비교적 넓고 평평하게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["고원"],"explanation":["파미르고원·아비시니아고원이 있어요.","높지만 넓고 평평해요.","그래서 가축을 기르기도 해요."],"mis":"SO6-2-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#2','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',2,'mc','auto','파미르고원 사람들이 양을 기르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"파미르고원 사람들이 양을 기르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"땅이 비교적 평탄하고 풀이 잘 자라기 때문에","correct":true},{"t":"땅속에 구리가 많기 때문에","mis":"SO6-2-u1-X02"},{"t":"화산이 분출하기 때문에","mis":"SO6-2-u1-X04"},{"t":"바다와 가까워 물고기가 많기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["고원은 높지만 평평한 곳이 있어요.","풀이 잘 자라면 가축의 먹이가 돼요.","그래서 양을 길러요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#3','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'mc','auto','「경사가 가파른 산지」와 「평탄한 산지」의 생활 모습을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「경사가 가파른 산지」와 「평탄한 산지」의 생활 모습을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"가파른 산지 — 계단식 농사 / 평탄한 산지 — 가축 기르기","correct":true},{"t":"가파른 산지 — 가축 기르기 / 평탄한 산지 — 계단식 농사","mis":"SO6-2-u1-X04"},{"t":"가파른 산지 — 수상 시장 / 평탄한 산지 — 염전","mis":"SO6-2-u1-X03"},{"t":"둘 다 — 사람이 살지 않음","mis":"SO6-2-u1-X04"}],"explanation":["경사에 따라 땅을 쓰는 방법이 달라요.","가파르면 계단처럼 깎아 농사지어요.","평탄하면 풀을 먹여 가축을 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#4','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'error','auto','산지와 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"error","stem":"산지와 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?","options":[{"t":"서아 — 「아이슬란드 — 구리를 캐는 광업」","correct":true,"mis_target":"SO6-2-u1-X02"},{"t":"민준 — 「스위스 알프스산맥 — 관광지」","mis":"SO6-2-u1-X02"},{"t":"하은 — 「타지키스탄 파미르고원 — 양 기르기」","mis":"SO6-2-u1-X02"}],"explanation":["아이슬란드는 화산 분출을 보는 관광지로 알려져 있어요.","구리 광업은 칠레 추키카마타예요.","민준과 하은은 바르게 짝지었어요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#5','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C1',3,'ox','auto','같은 산지라도 그 모습에 따라 사람들의 생활이 서로 달라요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"ox","stem":"같은 산지라도 그 모습에 따라 사람들의 생활이 서로 달라요.","answer":"O","reason_options":[{"t":"평탄한 고원·가파른 비탈·자원이 많은 산·화산마다 이용하는 방법이 다르기 때문에","correct":true},{"t":"산지는 모두 같은 모습이라 생활도 같기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["산지의 모습을 바꾸면 생활도 달라져요.","고원 — 가축, 비탈 — 계단식 농사예요.","자원 — 광업, 경관 — 관광이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#6','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'mc','auto','화산의 경관 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"mc","stem":"화산의 경관 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"정상이 움푹 파이거나 물이 고여 있는 모습을 볼 수 있다","correct":true},{"t":"바닷물이 골짜기 안까지 들어와 있다","mis":"SO6-2-u1-X03"},{"t":"황토가 섞인 강물이 흐른다","mis":"SO6-2-u1-X03"},{"t":"넓은 갯벌이 펼쳐져 있다","mis":"SO6-2-u1-X03"}],"explanation":["화산도 산지 지형이에요.","정상이 움푹 파이거나 물이 고이기도 해요.","용암이 흐르는 모습을 볼 수 있는 곳도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#7','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',3,'match','auto','산지를 이용하는 방법과 그 방법이 나타나는 산지의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"match","stem":"산지를 이용하는 방법과 그 방법이 나타나는 산지의 모습을 알맞게 이으세요.","pairs":[{"l":"계단식 농사","r":"경사가 가파른 곳"},{"l":"가축 기르기","r":"비교적 평탄하고 풀이 자라는 곳"},{"l":"광업","r":"지하자원이 풍부한 곳"},{"l":"스키장·휴양림","r":"경관이 아름다운 곳"}],"mis":"SO6-2-u1-X02","explanation":["산지의 모습이 생활을 정해요.","가파름·평탄함·자원·경관을 보아요.","사람들은 지형을 이용해 살아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#8','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'mc','auto','산지 사람들의 생활을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"mc","stem":"산지 사람들의 생활을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"산지 사람들은 지형을 이용해 농사를 짓고 가축을 기르며, 지하자원을 캐고 아름다운 경관을 관광지로 이용한다","correct":true},{"t":"산지 사람들은 모두 양만 기르며 살아간다","mis":"SO6-2-u1-X15"},{"t":"산지는 높아서 사람이 살지 않고 관광객만 잠깐 온다","mis":"SO6-2-u1-X04"},{"t":"산지 사람들은 배 위에서 물건을 사고팔며 살아간다","mis":"SO6-2-u1-X03"}],"explanation":["산지의 생활은 한 가지가 아니에요.","농사·가축·광업·관광이 모두 있어요.","한 곳의 모습을 산지 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#9','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'essay','teacher','내가 산지에 사는 사람이라면 그 산지의 모습에 따라 어떻게 살아갈지 두 가지 경우로 나누어 쓰세요. (예: 경사가 가파른 곳, 지하자원이 많은 곳)','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"내가 산지에 사는 사람이라면 그 산지의 모습에 따라 어떻게 살아갈지 두 가지 경우로 나누어 쓰세요. (예: 경사가 가파른 곳, 지하자원이 많은 곳)","answer_guide":{"answer":"예: 경사가 가파른 산지에 산다면 산비탈을 계단처럼 깎아 계단식 농사를 짓겠다. 지하자원이 많은 산지에 산다면 광산에서 자원을 캐는 일을 하거나, 경관이 아름다운 곳이라면 관광객에게 길을 안내하는 일을 하겠다.","scoring_points":["산지의 모습을 두 가지로 나누었는가","모습마다 알맞은 생활을 썼는가","지형을 이용해 살아간다는 점이 드러나는가"]},"explanation":["산지의 모습을 먼저 정해요.","그 모습에 맞는 생활을 떠올려요.","지형을 이용하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L02_challenge#10','soc',6,2,'u1','L02','g6_2_soc_u1_L02_challenge','lesson_challenge','SO6-2-u1-C2',4,'essay','teacher','알프스산맥과 추키카마타의 생활 모습이 서로 다른 까닭을 두 산지의 특징을 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"알프스산맥과 추키카마타의 생활 모습이 서로 다른 까닭을 두 산지의 특징을 들어 쓰세요.","answer_guide":{"answer":"예: 알프스산맥은 아름다운 지형 경관이 있어 이를 이용한 관광지가 발달했고, 추키카마타는 땅속에 구리가 많이 묻혀 있어 광업이 발달했다. 같은 산지라도 그 땅이 가진 특징이 달라 사람들이 이용하는 방법도 달라진 것이다.","scoring_points":["알프스산맥의 특징과 생활을 썼는가","추키카마타의 특징과 생활을 썼는가","특징이 달라 생활이 다르다는 까닭을 썼는가"]},"explanation":["알프스 — 경관 → 관광이에요.","추키카마타 — 구리 → 광업이에요.","특징이 생활을 바꿔요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#1','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'mc','auto','하천을 따라 나타나는 지형 경관으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"하천을 따라 나타나는 지형 경관으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"모래 언덕이 끝없는 사막","correct":true},{"t":"계곡","mis":"SO6-2-u1-X03"},{"t":"넓은 평야","mis":"SO6-2-u1-X03"},{"t":"거대한 폭포","mis":"SO6-2-u1-X03"}],"explanation":["하천을 따라 계곡과 평야가 나타나요.","거대한 폭포 같은 웅장한 경관도 있어요.","모래 언덕은 사막의 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#2','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'mc','auto','세계의 유명한 하천 지형이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"세계의 유명한 하천 지형이 아닌 것은 어느 것인가요?","options":[{"t":"히말라야산맥","correct":true},{"t":"나일강","mis":"SO6-2-u1-X03"},{"t":"아마존강","mis":"SO6-2-u1-X03"},{"t":"빅토리아 폭포","mis":"SO6-2-u1-X03"}],"explanation":["나일강·아마존강은 큰 강이에요.","빅토리아 폭포도 하천 지형이에요.","히말라야산맥은 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#3','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'sa','auto','강을 따라 배 위에서 물건을 사고파는 시장을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"sa","stem":"강을 따라 배 위에서 물건을 사고파는 시장을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["수상 시장","수상시장"],"explanation":["타이 짜오프라야강에 있어요.","사람들이 배 위에서 물건을 사고팔아요.","하천을 따라 시장이 생기기도 해요."],"mis":"SO6-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#4','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',1,'ox','auto','노르웨이는 흐르는 물의 힘을 이용해 전기를 많이 만들어요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"ox","stem":"노르웨이는 흐르는 물의 힘을 이용해 전기를 많이 만들어요.","answer":"O","reason_options":[{"t":"풍부한 하천의 물로 수력 발전을 하기 때문에","correct":true},{"t":"노르웨이에는 하천이 없기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["노르웨이는 전기의 대부분을 수력 발전으로 만들어요.","물이 흐르는 힘으로 전기를 만들어요.","하천은 에너지도 줘요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#5','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'match','auto','하천과 그곳 사람들의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"match","stem":"하천과 그곳 사람들의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"콩고강","r":"독특한 도구로 물고기를 잡는다"},{"l":"일리노이강 주변","r":"대형 농기계로 큰 규모의 농사를 짓는다"},{"l":"이구아수 폭포","r":"웅장한 경관을 보러 관광객이 온다"},{"l":"짜오프라야강","r":"배 위에서 물건을 사고판다"}],"mis":"SO6-2-u1-X05","explanation":["하천은 여러 가지를 줘요.","물고기·평야·경관·물길이에요.","그래서 생활도 여러 가지예요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#6','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','하천 주변에 넓은 평야가 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"하천 주변에 넓은 평야가 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"강물이 실어 나른 흙이 강가에 쌓이기 때문에","correct":true},{"t":"바닷물이 골짜기로 들어오기 때문에","mis":"SO6-2-u1-X03"},{"t":"용암이 흘러 굳기 때문에","mis":"SO6-2-u1-X03"},{"t":"빙하가 산을 깎기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["강물은 흙을 실어 날라요.","흙이 강가에 쌓여 넓은 평야가 생겨요.","평야에서는 큰 규모로 농사를 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#7','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','이구아수 폭포가 있는 나라를 바르게 고른 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"이구아수 폭포가 있는 나라를 바르게 고른 것은 어느 것인가요?","options":[{"t":"브라질과 아르헨티나","correct":true},{"t":"타이와 중국","mis":"SO6-2-u1-X03"},{"t":"노르웨이와 스위스","mis":"SO6-2-u1-X03"},{"t":"칠레와 멕시코","mis":"SO6-2-u1-X03"}],"explanation":["이구아수 폭포는 남아메리카에 있어요.","브라질과 아르헨티나 사이에 있어요.","웅장한 경관으로 관광객이 많이 와요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#8','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'mc','auto','일리노이강 주변 사람들이 비행기까지 이용해 농사를 짓는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X06','SO6-2-u1-X05']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"일리노이강 주변 사람들이 비행기까지 이용해 농사를 짓는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"강 주변에 넓은 평야가 펼쳐져 큰 규모로 농사를 짓기 때문에","correct":true},{"t":"산비탈이 가팔라 계단식 농사를 짓기 때문에","mis":"SO6-2-u1-X04"},{"t":"갯벌이 넓어 소금을 만들기 때문에","mis":"SO6-2-u1-X06"},{"t":"사막이라 물을 찾아 옮겨 다니기 때문에","mis":"SO6-2-u1-X05"}],"explanation":["넓은 평야는 큰 규모의 농사에 알맞아요.","그래서 대형 농기계와 비행기를 써요.","하천이 만든 평야를 이용하는 생활이에요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#9','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',2,'ox','auto','하천은 물건을 옮기는 길이 되기도 해요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"ox","stem":"하천은 물건을 옮기는 길이 되기도 해요.","answer":"O","reason_options":[{"t":"배로 물건을 실어 나르고 하천을 따라 시장이 생기기도 하기 때문에","correct":true},{"t":"하천에서는 배가 다닐 수 없기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["강은 물길이 돼요.","배로 물건을 옮겨요.","짜오프라야강에는 수상 시장도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_basic#10','soc',6,2,'u1','L03','g6_2_soc_u1_L03_basic','lesson_basic','SO6-2-u1-C3',3,'error','auto','하천 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"하천 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「하천에서는 물고기만 잡을 수 있고 다른 일은 할 수 없어.」","correct":true,"mis_target":"SO6-2-u1-X15"},{"t":"채원 — 「풍부한 물로 전기를 만들기도 해.」","mis":"SO6-2-u1-X05"},{"t":"지민 — 「아름다운 폭포는 관광지가 되기도 해.」","mis":"SO6-2-u1-X05"}],"explanation":["하천의 생활은 어업만이 아니에요.","농사·수력 발전·관광·시장도 있어요.","채원과 지민은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#1','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',2,'sa','auto','흐르는 물의 힘으로 전기를 만드는 방법을 무엇이라고 하나요? 「○○ 발전」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"sa","stem":"흐르는 물의 힘으로 전기를 만드는 방법을 무엇이라고 하나요? 「○○ 발전」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["수력"],"explanation":["물이 흐르는 힘을 써요.","노르웨이는 전기의 대부분을 이렇게 만들어요.","하천 지역의 생활 모습이에요."],"mis":"SO6-2-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#2','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',2,'mc','auto','짜오프라야강의 수상 시장이 하천 지형에 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"짜오프라야강의 수상 시장이 하천 지형에 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"강이 물건을 나르는 길이 되어 배로 오가며 사고팔 수 있기 때문에","correct":true},{"t":"강물이 짜서 소금을 만들기 좋기 때문에","mis":"SO6-2-u1-X06"},{"t":"강 주변이 가팔라 계단식 농사를 짓기 때문에","mis":"SO6-2-u1-X04"},{"t":"강 위에 모래 언덕이 있기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["하천은 물건을 옮기는 길이에요.","배를 타고 물건을 싣고 와 사고팔아요.","그래서 강을 따라 시장이 생겨요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#3','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'mc','auto','하천 다섯 곳 가운데 하천의 「경관」을 이용한 생활을 고른 것은 어느 것인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"하천 다섯 곳 가운데 하천의 「경관」을 이용한 생활을 고른 것은 어느 것인가요?","options":[{"t":"이구아수 폭포를 보러 관광객이 찾아온다","correct":true},{"t":"콩고강에서 물고기를 잡는다","mis":"SO6-2-u1-X05"},{"t":"노르웨이에서 수력 발전을 한다","mis":"SO6-2-u1-X05"},{"t":"일리노이강 주변 평야에서 농사짓는다","mis":"SO6-2-u1-X05"}],"explanation":["경관을 이용한 생활은 관광이에요.","이구아수 폭포의 웅장한 경관이 관광객을 불러요.","나머지는 물고기·물·평야를 이용한 생활이에요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#4','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'error','auto','하천과 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"하천과 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?","options":[{"t":"도윤 — 「짜오프라야강 — 대형 농기계로 평야 농사」","correct":true,"mis_target":"SO6-2-u1-X05"},{"t":"나린 — 「콩고강 — 독특한 도구로 물고기 잡기」","mis":"SO6-2-u1-X05"},{"t":"현서 — 「노르웨이 — 수력 발전」","mis":"SO6-2-u1-X05"}],"explanation":["짜오프라야강은 수상 시장으로 알려졌어요.","대형 농기계 농사는 일리노이강 주변이에요.","나린과 현서는 바르게 짝지었어요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#5','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'ox','auto','강물이 실어 나른 흙이 쌓인 평야와, 강을 따라 하류에 닿는 배는 모두 하천이 만든 생활의 바탕이에요.',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"ox","stem":"강물이 실어 나른 흙이 쌓인 평야와, 강을 따라 하류에 닿는 배는 모두 하천이 만든 생활의 바탕이에요.","answer":"O","reason_options":[{"t":"흙은 농사지을 평야를, 물길은 물건을 나르는 길과 시장을 만들어 주기 때문에","correct":true},{"t":"평야와 배는 하천과 관계가 없기 때문에","mis":"SO6-2-u1-X05"}],"mis":"SO6-2-u1-X05","explanation":["하천은 흙을 날라 평야를 만들어요.","하천은 배가 다니는 길이에요.","둘 다 사람들의 생활로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#6','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'mc','auto','하천 지형의 생활 모습을 정리한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"mc","stem":"하천 지형의 생활 모습을 정리한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"갯벌을 이용해 염전을 만든다","correct":true},{"t":"평야에서 농사를 짓는다","mis":"SO6-2-u1-X05"},{"t":"어업을 한다","mis":"SO6-2-u1-X05"},{"t":"수력 발전으로 전기를 만든다","mis":"SO6-2-u1-X05"}],"explanation":["평야 농사·어업·수력 발전은 하천의 생활이에요.","관광과 수상 시장도 있어요.","갯벌의 염전은 해안의 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#7','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',3,'match','auto','하천이 주는 것과 그것을 이용한 생활을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"match","stem":"하천이 주는 것과 그것을 이용한 생활을 알맞게 이으세요.","pairs":[{"l":"물고기","r":"어업"},{"l":"넓은 평야","r":"큰 규모의 농사"},{"l":"흐르는 물의 힘","r":"수력 발전"},{"l":"웅장한 폭포","r":"관광"}],"mis":"SO6-2-u1-X05","explanation":["하천은 여러 가지를 줘요.","주는 것에 따라 생활이 달라져요.","물길은 시장으로도 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#8','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'mc','auto','하천 지역 사람들이 하천을 이용하는 방법을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X02','SO6-2-u1-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"mc","stem":"하천 지역 사람들이 하천을 이용하는 방법을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"어업을 하고, 평야에서 큰 규모로 농사짓고, 물로 전기를 만들며, 경관은 관광지로, 물길은 물건을 옮기고 사고파는 데 쓴다","correct":true},{"t":"하천 사람들은 모두 수상 시장에서만 일한다","mis":"SO6-2-u1-X15"},{"t":"하천은 홍수가 나므로 사람들이 아무것도 이용하지 않는다","mis":"SO6-2-u1-X02"},{"t":"하천에서는 소금을 만들고 항구를 짓는 일만 한다","mis":"SO6-2-u1-X06"}],"explanation":["하천의 생활은 한 가지가 아니에요.","어업·농사·발전·관광·시장이 있어요.","한 곳의 모습을 하천 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#9','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'essay','teacher','하천이 주는 것 두 가지를 들고, 그것을 이용한 생활 모습을 세계의 예와 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"essay","stem":"하천이 주는 것 두 가지를 들고, 그것을 이용한 생활 모습을 세계의 예와 함께 쓰세요.","answer_guide":{"answer":"예: 하천은 넓은 평야를 만들어 주어 미국 일리노이강 주변에서는 대형 농기계와 비행기로 큰 규모의 농사를 짓는다. 또 흐르는 물의 힘을 주어 노르웨이는 전기의 대부분을 수력 발전으로 만든다.","scoring_points":["하천이 주는 것을 두 가지 들었는가","그것을 이용한 생활을 썼는가","세계의 알맞은 예를 들었는가"]},"explanation":["하천이 주는 것부터 생각해요.","평야·물고기·물의 힘·경관·물길이 있어요.","세계의 예와 이어요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L03_challenge#10','soc',6,2,'u1','L03','g6_2_soc_u1_L03_challenge','lesson_challenge','SO6-2-u1-C3',4,'essay','teacher','이구아수 폭포와 짜오프라야강은 둘 다 하천인데 생활 모습이 서로 달라요. 두 곳의 생활 모습을 쓰고 그렇게 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"essay","stem":"이구아수 폭포와 짜오프라야강은 둘 다 하천인데 생활 모습이 서로 달라요. 두 곳의 생활 모습을 쓰고 그렇게 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 이구아수 폭포에는 웅장한 폭포 경관을 보려고 관광객이 많이 찾아오고, 짜오프라야강에서는 배 위에서 물건을 사고파는 수상 시장이 열린다. 이구아수 폭포는 경관이 특징이고 짜오프라야강은 배가 다니는 물길이 특징이라, 이용하는 방법이 달라졌다.","scoring_points":["두 곳의 생활 모습을 바르게 썼는가","두 곳의 하천 특징을 견주었는가","특징이 달라 생활이 다르다는 까닭을 썼는가"]},"explanation":["같은 하천도 특징이 달라요.","경관 → 관광, 물길 → 시장이에요.","특징이 생활을 바꿔요."],"asset":{"type":"passage","lines":["㉠ 콩고강(콩고 민주 공화국) — 사람들이 독특한 도구로 물고기를 잡는다","㉡ 일리노이강(미국) 주변 — 넓은 평야에서 대형 농기계와 비행기로 농사짓는다","㉢ 노르웨이 — 전기의 대부분을 흐르는 물의 힘으로 만든다","㉣ 이구아수 폭포(브라질·아르헨티나) — 웅장한 폭포를 보러 관광객이 온다","㉤ 짜오프라야강(타이) — 배 위에서 물건을 사고판다"],"title":"하천 다섯 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#1','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'mc','auto','해안의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다와 육지가 만나는 곳","correct":true},{"t":"강물이 높은 곳에서 떨어지는 곳","mis":"SO6-2-u1-X03"},{"t":"해발 고도가 높고 경사가 급한 곳","mis":"SO6-2-u1-X03"},{"t":"비가 거의 오지 않아 모래가 펼쳐진 곳","mis":"SO6-2-u1-X03"}],"explanation":["해안은 바다와 육지가 만나는 곳이에요.","여러 모습의 해안 지형이 나타나요.","폭포는 하천, 높은 땅은 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#2','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'mc','auto','해안에서 볼 수 있는 지형 경관이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안에서 볼 수 있는 지형 경관이 아닌 것은 어느 것인가요?","options":[{"t":"용암이 흐르는 화산 꼭대기","correct":true},{"t":"갯벌","mis":"SO6-2-u1-X03"},{"t":"모래사장","mis":"SO6-2-u1-X03"},{"t":"거대한 절벽과 돌기둥","mis":"SO6-2-u1-X03"}],"explanation":["해안에는 갯벌과 모래사장이 있어요.","거대한 절벽과 돌기둥도 볼 수 있어요.","화산 꼭대기는 산지의 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#3','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'sa','auto','물고기나 조개 등을 사람이 길러 거두는 일을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"sa","stem":"물고기나 조개 등을 사람이 길러 거두는 일을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["양식업"],"explanation":["해안 주민들은 어업과 양식업을 해요.","양식업은 물고기·조개를 기르는 일이에요.","바다에서 잡는 일은 어업이에요."],"mis":"SO6-2-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#4','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',1,'ox','auto','배가 드나들기에 유리한 해안에는 염전이 발달해요.',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"ox","stem":"배가 드나들기에 유리한 해안에는 염전이 발달해요.","answer":"X","reason_options":[{"t":"배가 드나들기 유리한 해안에는 항구가 발달하고, 염전은 갯벌이 넓은 해안에 발달하기 때문에","correct":true},{"t":"배가 드나들면 소금을 실어 나르기 좋기 때문에","mis":"SO6-2-u1-X06"}],"mis":"SO6-2-u1-X06","explanation":["배가 드나들기 좋은 해안 → 항구예요.","갯벌이 넓은 해안 → 염전이에요.","자리마다 맞는 이용이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#5','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'match','auto','해안과 그곳 사람들의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"match","stem":"해안과 그곳 사람들의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"스리랑카","r":"장대에 앉아 물고기를 잡는다"},{"l":"멕시코 해변","r":"모래사장에 관광객이 찾아온다"},{"l":"네덜란드","r":"항구에 여러 나라의 배가 오간다"},{"l":"프랑스 게랑드","r":"갯벌로 질 좋은 소금을 만든다"}],"mis":"SO6-2-u1-X06","explanation":["해안의 모습에 따라 생활이 달라요.","어업·관광·항구·염전이에요.","자리마다 맞는 이용이 있어요."],"asset":{"type":"passage","lines":["㉠ 스리랑카 — 배 없이 바다에 세운 장대에 앉아 물고기를 잡는다","㉡ 멕시코 해변 — 아름다운 모래사장에 관광객이 많이 찾아온다","㉢ 네덜란드 — 해안의 항구에 세계 여러 나라의 배가 오간다","㉣ 프랑스 게랑드 — 넓은 갯벌을 이용해 질 좋은 소금을 만든다"],"title":"해안 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#6','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','갯벌이 넓게 펼쳐진 해안에서 발달하기 쉬운 것은 어느 것인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"갯벌이 넓게 펼쳐진 해안에서 발달하기 쉬운 것은 어느 것인가요?","options":[{"t":"염전","correct":true},{"t":"스키장","mis":"SO6-2-u1-X04"},{"t":"수력 발전소","mis":"SO6-2-u1-X05"},{"t":"계단식 논","mis":"SO6-2-u1-X04"}],"explanation":["넓은 갯벌은 바닷물을 가두기 좋아요.","바닷물을 말려 소금을 만드는 염전이 생겨요.","프랑스 게랑드가 예예요."],"asset":{"type":"passage","lines":["㉠ 스리랑카 — 배 없이 바다에 세운 장대에 앉아 물고기를 잡는다","㉡ 멕시코 해변 — 아름다운 모래사장에 관광객이 많이 찾아온다","㉢ 네덜란드 — 해안의 항구에 세계 여러 나라의 배가 오간다","㉣ 프랑스 게랑드 — 넓은 갯벌을 이용해 질 좋은 소금을 만든다"],"title":"해안 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#7','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','세계의 유명한 해안 지형으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"세계의 유명한 해안 지형으로 알맞은 것은 어느 것인가요?","options":[{"t":"펀디만 갯벌","correct":true},{"t":"파미르고원","mis":"SO6-2-u1-X03"},{"t":"아마존강","mis":"SO6-2-u1-X03"},{"t":"사하라 사막","mis":"SO6-2-u1-X03"}],"explanation":["펀디만 갯벌과 마케나 모래사장은 해안 지형이에요.","파미르고원은 산지예요.","아마존강은 하천, 사하라는 사막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#8','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'mc','auto','경관이 아름다운 해안에 생기기 쉬운 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X05','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"경관이 아름다운 해안에 생기기 쉬운 것은 어느 것인가요?","options":[{"t":"관광지","correct":true},{"t":"구리 광산","mis":"SO6-2-u1-X02"},{"t":"넓은 밀밭","mis":"SO6-2-u1-X05"},{"t":"수상 시장","mis":"SO6-2-u1-X03"}],"explanation":["아름다운 경관은 사람들을 불러요.","멕시코 해변의 모래사장에 관광객이 많이 와요.","그래서 관광지가 생겨요."],"asset":{"type":"passage","lines":["㉠ 스리랑카 — 배 없이 바다에 세운 장대에 앉아 물고기를 잡는다","㉡ 멕시코 해변 — 아름다운 모래사장에 관광객이 많이 찾아온다","㉢ 네덜란드 — 해안의 항구에 세계 여러 나라의 배가 오간다","㉣ 프랑스 게랑드 — 넓은 갯벌을 이용해 질 좋은 소금을 만든다"],"title":"해안 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#9','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',2,'ox','auto','해안에 관광객이 늘면 그곳에는 좋은 점만 생겨요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"해안에 관광객이 늘면 그곳에는 좋은 점만 생겨요.","answer":"X","reason_options":[{"t":"일자리와 소득이 늘지만 쓰레기와 오염도 함께 늘기 때문에","correct":true},{"t":"관광객은 언제나 깨끗하게 다니기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광은 일자리와 소득을 늘려요.","하지만 쓰레기와 바다 오염도 늘어요.","좋은 점과 걱정을 함께 봐요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_basic#10','soc',6,2,'u1','L04','g6_2_soc_u1_L04_basic','lesson_basic','SO6-2-u1-C4',3,'error','auto','해안 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"해안 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「넓은 갯벌에는 큰 배가 드나드는 항구를 지어.」","correct":true,"mis_target":"SO6-2-u1-X06"},{"t":"준호 — 「해안 주민들은 어업이나 양식업을 하며 살아가.」","mis":"SO6-2-u1-X06"},{"t":"예린 — 「경관이 아름다운 해안은 관광지가 돼.」","mis":"SO6-2-u1-X06"}],"explanation":["넓은 갯벌에는 염전이 발달해요.","항구는 배가 드나들기 유리한 해안에 생겨요.","준호와 예린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#1','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',2,'sa','auto','갯벌에 바닷물을 가두어 햇볕과 바람에 말려 소금을 만드는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"sa","stem":"갯벌에 바닷물을 가두어 햇볕과 바람에 말려 소금을 만드는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["염전"],"explanation":["갯벌이 넓은 해안에 발달해요.","바닷물을 말려 소금을 얻어요.","프랑스 게랑드가 유명해요."],"mis":"SO6-2-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#2','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',2,'mc','auto','네덜란드의 해안에 세계 여러 나라의 배가 오가는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"네덜란드의 해안에 세계 여러 나라의 배가 오가는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"배가 드나들기에 유리한 해안에 항구가 발달했기 때문에","correct":true},{"t":"갯벌이 넓어 염전이 많기 때문에","mis":"SO6-2-u1-X06"},{"t":"모래사장이 아름다워 관광객이 많기 때문에","mis":"SO6-2-u1-X06"},{"t":"산지가 많아 광업이 발달했기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["배가 드나들기 좋은 해안에는 항구가 생겨요.","네덜란드의 항구에는 여러 나라의 배가 오가요.","해안은 바다와 육지를 잇는 길목이에요."],"asset":{"type":"passage","lines":["㉠ 스리랑카 — 배 없이 바다에 세운 장대에 앉아 물고기를 잡는다","㉡ 멕시코 해변 — 아름다운 모래사장에 관광객이 많이 찾아온다","㉢ 네덜란드 — 해안의 항구에 세계 여러 나라의 배가 오간다","㉣ 프랑스 게랑드 — 넓은 갯벌을 이용해 질 좋은 소금을 만든다"],"title":"해안 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#3','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'mc','auto','관광이 늘어난 섬의 이야기에서 함께 늘어난 두 가지를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"관광이 늘어난 섬의 이야기에서 함께 늘어난 두 가지를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"일자리와 소득 · 쓰레기와 오염","correct":true},{"t":"일자리와 소득만","mis":"SO6-2-u1-X07"},{"t":"쓰레기와 오염만","mis":"SO6-2-u1-X07"},{"t":"산지와 하천","mis":"SO6-2-u1-X03"}],"explanation":["숙소와 식당에 일자리가 생겨 벌이가 늘었어요.","바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌어요.","관광에는 두 가지 영향이 함께 있어요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#4','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'error','auto','해안과 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"해안과 생활 모습을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?","options":[{"t":"하람 — 「프랑스 게랑드 — 여러 나라의 배가 오가는 항구」","correct":true,"mis_target":"SO6-2-u1-X06"},{"t":"윤서 — 「스리랑카 — 장대에 앉아 하는 고기잡이」","mis":"SO6-2-u1-X06"},{"t":"지호 — 「멕시코 해변 — 모래사장 관광」","mis":"SO6-2-u1-X06"}],"explanation":["게랑드는 갯벌로 소금을 만드는 곳이에요.","항구는 네덜란드의 예예요.","윤서와 지호는 바르게 짝지었어요."],"asset":{"type":"passage","lines":["㉠ 스리랑카 — 배 없이 바다에 세운 장대에 앉아 물고기를 잡는다","㉡ 멕시코 해변 — 아름다운 모래사장에 관광객이 많이 찾아온다","㉢ 네덜란드 — 해안의 항구에 세계 여러 나라의 배가 오간다","㉣ 프랑스 게랑드 — 넓은 갯벌을 이용해 질 좋은 소금을 만든다"],"title":"해안 네 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#5','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'ox','auto','섬을 한동안 쉬게 하자 쓰레기와 오염이 줄었지만 일자리와 소득도 함께 줄었어요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"ox","stem":"섬을 한동안 쉬게 하자 쓰레기와 오염이 줄었지만 일자리와 소득도 함께 줄었어요.","answer":"O","reason_options":[{"t":"관광객이 줄면 관광으로 생긴 좋은 점과 걱정이 함께 줄어들기 때문에","correct":true},{"t":"섬을 쉬게 하면 좋은 점만 남기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광의 영향은 함께 움직여요.","관광객이 줄면 오염도 일자리도 줄어요.","그래서 두 쪽을 함께 생각해 정해요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#6','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'mc','auto','해안의 자리와 그곳에 알맞은 이용을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"해안의 자리와 그곳에 알맞은 이용을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"배가 드나들기 좋은 곳 — 항구 / 갯벌이 넓은 곳 — 염전 / 경관이 아름다운 곳 — 관광지","correct":true},{"t":"배가 드나들기 좋은 곳 — 염전 / 갯벌이 넓은 곳 — 항구 / 경관이 아름다운 곳 — 관광지","mis":"SO6-2-u1-X06"},{"t":"배가 드나들기 좋은 곳 — 관광지 / 갯벌이 넓은 곳 — 스키장 / 경관이 아름다운 곳 — 광산","mis":"SO6-2-u1-X06"},{"t":"어느 곳이나 — 항구만","mis":"SO6-2-u1-X15"}],"explanation":["해안의 모습에 따라 이용이 달라요.","배 → 항구, 갯벌 → 염전이에요.","아름다운 경관 → 관광지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#7','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',3,'match','auto','해안 지형 경관과 그 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"match","stem":"해안 지형 경관과 그 모습을 알맞게 이으세요.","pairs":[{"l":"갯벌","r":"물이 빠지면 드러나는 넓고 질척한 땅"},{"l":"모래사장","r":"모래가 넓게 깔린 바닷가"},{"l":"돌기둥","r":"바닷가에 우뚝 선 기둥 모양의 바위"}],"mis":"SO6-2-u1-X03","explanation":["해안에는 여러 지형 경관이 있어요.","갯벌·모래사장·절벽·돌기둥이에요.","모습에 따라 이용도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#8','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'mc','auto','관광이 늘어난 섬 사람들이 할 수 있는 결정으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"mc","stem":"관광이 늘어난 섬 사람들이 할 수 있는 결정으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"관광으로 생긴 일자리와 오염을 함께 따져, 쓰레기를 줄이는 규칙을 정하고 관광객 수를 알맞게 조절한다","correct":true},{"t":"일자리가 늘었으니 오염은 생각하지 않는다","mis":"SO6-2-u1-X07"},{"t":"오염이 생겼으니 관광을 영원히 금지한다","mis":"SO6-2-u1-X07"},{"t":"관광은 해안과 관계가 없으니 그대로 둔다","mis":"SO6-2-u1-X02"}],"explanation":["관광에는 좋은 점과 걱정이 함께 있어요.","한쪽만 보면 다른 쪽 문제가 커져요.","둘을 함께 따져 결정해요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#9','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','해안 사람들이 해안을 이용하는 방법을 세 가지 쓰고, 각각 어떤 해안에서 발달하는지 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"해안 사람들이 해안을 이용하는 방법을 세 가지 쓰고, 각각 어떤 해안에서 발달하는지 함께 쓰세요.","answer_guide":{"answer":"예: 배가 드나들기에 유리한 해안에서는 항구를 만들어 배가 오가게 한다. 갯벌이 넓게 펼쳐진 해안에서는 염전을 만들어 소금을 얻는다. 경관이 아름다운 해안은 관광지로 이용한다. 이 밖에 어업과 양식업도 한다.","scoring_points":["해안 이용 방법을 세 가지 썼는가","각각 발달하는 해안의 모습을 바르게 짝지었는가","해안의 모습이 생활을 정한다는 점이 드러나는가"]},"explanation":["해안의 모습을 먼저 봐요.","배·갯벌·경관을 떠올려요.","항구·염전·관광지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L04_challenge#10','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','어느 해안 마을에 관광객이 많이 찾아오게 되었어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 마을이 할 수 있는 일을 한 가지 제안하세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"어느 해안 마을에 관광객이 많이 찾아오게 되었어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 마을이 할 수 있는 일을 한 가지 제안하세요.","answer_guide":{"answer":"예: 긍정적인 영향 — 숙소·식당·안내 일자리가 생겨 마을 사람들의 소득이 늘어난다. 부정적인 영향 — 바닷가에 쓰레기가 쌓이고 바닷물이 오염된다. 제안 — 관광객에게 쓰레기를 되가져가게 하고, 해마다 일정한 기간은 바닷가를 쉬게 한다.","scoring_points":["긍정적인 영향을 썼는가","부정적인 영향을 썼는가","두 영향을 함께 고려한 제안을 했는가"]},"explanation":["관광은 두 가지 영향을 함께 줘요.","한쪽만 보지 않아요.","둘을 따져 방법을 찾아요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#1','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','기후의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"기후의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태","correct":true},{"t":"하루 동안 잠깐 나타나는 날씨","mis":"SO6-2-u1-X08"},{"t":"바다 표면으로부터 잰 육지의 높이","mis":"SO6-2-u1-X09"},{"t":"지구의 남쪽과 북쪽을 나누는 선","mis":"SO6-2-u1-X10"}],"explanation":["기후는 오랜 기간의 평균 상태예요.","오늘 비가 오는 것은 날씨예요.","해발 고도·적도와는 다른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#2','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','세계의 기후를 구분하는 주된 기준 두 가지는 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계의 기후를 구분하는 주된 기준 두 가지는 어느 것인가요?","options":[{"t":"기온과 강수량","correct":true},{"t":"나라 이름과 인구","mis":"SO6-2-u1-X10"},{"t":"산의 높이와 강의 길이","mis":"SO6-2-u1-X10"},{"t":"바람의 색과 구름의 모양","mis":"SO6-2-u1-X10"}],"explanation":["기후는 주로 기온과 강수량으로 나눠요.","얼마나 덥고 추운지, 비가 얼마나 오는지 봐요.","나라 이름은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#3','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'sa','auto','매우 높은 산지에서 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"sa","stem":"매우 높은 산지에서 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["고산"],"explanation":["높이 올라갈수록 기온이 낮아져요.","매우 높은 산지에는 고산 기후가 나타나요.","위도의 차례와 다르게 놓여요."],"mis":"SO6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#4','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'ox','auto','우리나라에서 나타나는 기후는 온대 기후와 냉대 기후예요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"ox","stem":"우리나라에서 나타나는 기후는 온대 기후와 냉대 기후예요.","answer":"O","reason_options":[{"t":"우리나라는 중위도에 있어 사계절이 나타나는 온대 기후와 냉대 기후가 나타나기 때문에","correct":true},{"t":"우리나라는 적도 바로 위에 있기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["우리나라는 중위도에 있어요.","사계절이 뚜렷해요.","온대 기후와 냉대 기후가 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#5','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','적도에서 극지방으로 가면서 나타나는 기후의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도에서 극지방으로 가면서 나타나는 기후의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"열대 → 건조 → 온대 → 냉대 → 한대","correct":true},{"t":"한대 → 냉대 → 온대 → 건조 → 열대","mis":"SO6-2-u1-X10"},{"t":"열대 → 온대 → 건조 → 한대 → 냉대","mis":"SO6-2-u1-X10"},{"t":"건조 → 열대 → 냉대 → 온대 → 한대","mis":"SO6-2-u1-X10"}],"explanation":["적도 주변은 열대 기후예요.","극으로 갈수록 건조 → 온대 → 냉대 → 한대예요.","극지방에는 한대 기후가 나타나요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#6','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'ox','auto','세계의 기후는 위도만으로 정해져요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"세계의 기후는 위도만으로 정해져요.","answer":"X","reason_options":[{"t":"위도뿐 아니라 위치·지형·해발 고도에 따라서도 다르게 나타나기 때문에","correct":true},{"t":"같은 위도에서는 언제나 같은 기후가 나타나기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["위도는 기후에 큰 영향을 줘요.","하지만 위치·지형·해발 고도도 영향을 줘요.","적도 주변의 높은 산에는 고산 기후가 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#7','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','북쪽에 기후 띠를 쌓을 때 남쪽에도 같은 차례로 띠가 나타난 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"북쪽에 기후 띠를 쌓을 때 남쪽에도 같은 차례로 띠가 나타난 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 위도에 따라 달라지고 적도를 기준으로 남북이 비슷하게 나타나기 때문에","correct":true},{"t":"남쪽과 북쪽은 늘 반대 기후가 나타나기 때문에","mis":"SO6-2-u1-X10"},{"t":"남쪽에는 기후가 없기 때문에","mis":"SO6-2-u1-X10"},{"t":"기후는 나라마다 아무렇게나 정해지기 때문에","mis":"SO6-2-u1-X10"}],"explanation":["적도를 기준으로 남북을 견주어 봐요.","같은 위도에는 비슷한 기후가 나타나요.","다만 냉대 기후는 주로 북반구에 나타나요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#8','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'match','auto','「날씨」와 「기후」를 쓴 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"match","stem":"「날씨」와 「기후」를 쓴 문장을 알맞게 이으세요.","pairs":[{"l":"오늘은 비가 오고 바람이 세다.","r":"날씨 — 짧은 기간의 대기 상태"},{"l":"이 지역은 해마다 여름에 덥고 비가 많다.","r":"기후 — 여러 해의 평균 상태"}],"mis":"SO6-2-u1-X08","explanation":["날씨는 짧은 기간의 대기 상태예요.","기후는 여러 해의 평균 상태예요.","「해마다」는 기후를 알려 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#9','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','기후 분포에 영향을 주는 요인이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"기후 분포에 영향을 주는 요인이 아닌 것은 어느 것인가요?","options":[{"t":"그 나라의 국기 색깔","correct":true},{"t":"위도","mis":"SO6-2-u1-X09"},{"t":"해발 고도","mis":"SO6-2-u1-X09"},{"t":"지형","mis":"SO6-2-u1-X09"}],"explanation":["위도·위치·지형·해발 고도가 기후에 영향을 줘요.","국기 색깔은 기후와 관계가 없어요.","여러 요인을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_basic#10','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',3,'error','auto','세계의 기후 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"세계의 기후 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「적도 주변은 어디든 덥기만 하니까 서늘한 기후는 없어.」","correct":true,"mis_target":"SO6-2-u1-X09"},{"t":"지안 — 「적도 주변이라도 매우 높은 산지에는 고산 기후가 나타나.」","mis":"SO6-2-u1-X09"},{"t":"하율 — 「극지방에는 한대 기후가 주로 나타나.」","mis":"SO6-2-u1-X10"}],"explanation":["적도 주변이라도 해발 고도가 높으면 서늘해요.","그래서 고산 기후가 나타나요.","지안과 하율은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#1','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'sa','auto','세계의 기후는 열대·건조·온대·냉대·한대·고산 기후로 나눠요. 남극과 북극 주변에 주로 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"sa","stem":"세계의 기후는 열대·건조·온대·냉대·한대·고산 기후로 나눠요. 남극과 북극 주변에 주로 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["한대"],"explanation":["극지방은 기온이 매우 낮아요.","한대 기후가 나타나요.","적도 주변의 열대와 맞은편 끝이에요."],"mis":"SO6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#2','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'mc','auto','냉대 기후에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"냉대 기후에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"주로 북반구에 나타난다","correct":true},{"t":"적도 바로 위에 띠를 이룬다","mis":"SO6-2-u1-X10"},{"t":"남반구에만 나타난다","mis":"SO6-2-u1-X10"},{"t":"매우 높은 산지에만 나타난다","mis":"SO6-2-u1-X14"}],"explanation":["기후 띠는 적도를 기준으로 남북이 비슷해요.","그런데 냉대 기후는 주로 북반구에 나타나요.","그래서 남쪽 띠는 대략적인 모습이에요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#3','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','적도에서 북쪽으로 온대 기후 띠까지 쌓았어요. 그다음에 나타나는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"적도에서 북쪽으로 온대 기후 띠까지 쌓았어요. 그다음에 나타나는 기후는 어느 것인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X10"},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["차례는 열대 → 건조 → 온대 → 냉대 → 한대예요.","온대 다음은 냉대예요.","고산은 위도의 차례에 들지 않아요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#4','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'ox','auto','「고산 기후」 카드가 위도의 차례에 들지 않은 까닭은 고산 기후가 위도가 아니라 해발 고도에 따라 나타나기 때문이에요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"ox","stem":"「고산 기후」 카드가 위도의 차례에 들지 않은 까닭은 고산 기후가 위도가 아니라 해발 고도에 따라 나타나기 때문이에요.","answer":"O","reason_options":[{"t":"매우 높은 산지에서는 위도와 상관없이 고산 기후가 나타나기 때문에","correct":true},{"t":"고산 기후는 극지방에서만 나타나기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["기후 띠는 위도의 차례예요.","고산 기후는 높이가 만든 기후예요.","그래서 높은 산지에 따로 놓여요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#5','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','「어제 이 마을에는 비가 많이 왔다.」만 보고 이 마을의 기후를 정할 수 없는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"「어제 이 마을에는 비가 많이 왔다.」만 보고 이 마을의 기후를 정할 수 없는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하루의 날씨만 보았을 뿐 여러 해의 평균 상태를 보지 않았기 때문에","correct":true},{"t":"비는 기후를 구분하는 기준이 아니기 때문에","mis":"SO6-2-u1-X10"},{"t":"어제는 공휴일이었기 때문에","mis":"SO6-2-u1-X08"},{"t":"마을에는 기후가 없기 때문에","mis":"SO6-2-u1-X08"}],"explanation":["기후는 여러 해에 걸친 평균 상태예요.","하루의 비는 날씨예요.","기후를 알려면 여러 해의 기온과 강수량을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#6','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'error','auto','기후를 구분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"기후를 구분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「기후는 나라마다 하나씩 정해져서 나라 이름으로 구분해.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"이서 — 「기후는 주로 기온과 강수량을 기준으로 구분해.」","mis":"SO6-2-u1-X10"},{"t":"라온 — 「한 나라 안에서도 여러 기후가 나타날 수 있어.」","mis":"SO6-2-u1-X10"}],"explanation":["기후는 나라 이름으로 구분하지 않아요.","기온과 강수량이 기준이에요.","이서와 라온은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#7','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'match','auto','기후와 그 기후가 주로 나타나는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"match","stem":"기후와 그 기후가 주로 나타나는 곳을 알맞게 이으세요.","pairs":[{"l":"열대 기후","r":"적도 주변의 저위도"},{"l":"온대 기후","r":"중위도"},{"l":"한대 기후","r":"남극과 북극 주변의 고위도"},{"l":"고산 기후","r":"해발 고도가 매우 높은 곳"}],"mis":"SO6-2-u1-X10","explanation":["위도에 따라 기후가 달라요.","저위도 — 열대, 중위도 — 온대, 고위도 — 한대예요.","고산 기후는 높이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#8','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'mc','auto','세계의 기후 분포를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"세계의 기후 분포를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"주로 기온과 강수량으로 구분하며, 적도에서 극으로 열대·건조·온대·냉대·한대가 차례로 나타나고 매우 높은 산지에는 고산 기후가 나타난다","correct":true},{"t":"나라 이름으로 구분하며, 어느 위도에서나 같은 기후가 나타난다","mis":"SO6-2-u1-X10"},{"t":"기후는 위도와 상관없이 아무렇게나 흩어져 나타난다","mis":"SO6-2-u1-X10"},{"t":"적도에서 극으로 한대·냉대·온대·건조·열대가 차례로 나타난다","mis":"SO6-2-u1-X10"}],"explanation":["기준은 기온과 강수량이에요.","적도에서 극으로 열대부터 한대까지 차례가 있어요.","높은 산지는 고산 기후예요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#9','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','날씨와 기후의 차이를 예를 들어 쓰고, 세계의 기후가 지역마다 다르게 나타나는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"날씨와 기후의 차이를 예를 들어 쓰고, 세계의 기후가 지역마다 다르게 나타나는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「오늘은 맑고 덥다」처럼 짧은 기간의 대기 상태는 날씨이고, 「이 지역은 해마다 여름에 덥고 비가 많다」처럼 여러 해에 걸쳐 되풀이되는 평균 상태는 기후이다. 기후가 지역마다 다른 까닭은 위도가 달라 받는 햇볕의 양이 다르고, 해발 고도나 지형·위치가 다르기 때문이다.","scoring_points":["날씨와 기후의 차이를 예와 함께 썼는가","기후에 영향을 주는 요인을 두 가지 썼는가","위도만이 아니라 다른 요인도 들었는가"]},"explanation":["날씨 — 짧은 기간, 기후 — 여러 해의 평균이에요.","위도·위치·지형·해발 고도가 영향을 줘요.","둘 이상 들어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L06_challenge#10','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','적도 주변에 있는 두 도시 가운데 한 곳은 일 년 내내 덥고, 다른 한 곳은 일 년 내내 서늘해요. 같은 적도 주변인데 기후가 다른 까닭을 쓰고, 각 도시의 기후 이름을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"적도 주변에 있는 두 도시 가운데 한 곳은 일 년 내내 덥고, 다른 한 곳은 일 년 내내 서늘해요. 같은 적도 주변인데 기후가 다른 까닭을 쓰고, 각 도시의 기후 이름을 쓰세요.","answer_guide":{"answer":"예: 두 도시는 위도가 비슷하지만 해발 고도가 다르다. 낮은 곳에 있는 도시는 일 년 내내 기온이 높은 열대 기후이고, 높은 산지에 있는 도시는 높이 올라갈수록 기온이 낮아져 일 년 내내 서늘한 고산 기후이다. 기후는 위도뿐 아니라 해발 고도에 따라서도 달라진다.","scoring_points":["해발 고도의 차이를 까닭으로 썼는가","두 도시의 기후 이름(열대·고산)을 바르게 썼는가","위도만으로 기후가 정해지지 않음이 드러나는가"]},"explanation":["위도가 같아도 높이가 다를 수 있어요.","높이 오르면 서늘해져요.","열대와 고산으로 갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#1','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'mc','auto','열대 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"mc","stem":"열대 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"일 년 내내 기온이 높고 기온의 변화가 거의 없다","correct":true},{"t":"겨울이 여름보다 길고 몹시 춥다","mis":"SO6-2-u1-X11"},{"t":"강수량이 매우 적고 낮과 밤의 기온 차이가 크다","mis":"SO6-2-u1-X11"},{"t":"일 년 내내 눈과 얼음으로 덮여 있다","mis":"SO6-2-u1-X11"}],"explanation":["열대 기후는 적도 주변에 나타나요.","일 년 내내 덥고 기온 변화가 거의 없어요.","비가 적고 낮밤 차이가 큰 것은 건조 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#2','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'mc','auto','건조 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"mc","stem":"건조 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"강수량이 적고 낮과 밤의 기온 차이가 크다","correct":true},{"t":"일 년 내내 비가 많이 내린다","mis":"SO6-2-u1-X11"},{"t":"사계절의 변화가 뚜렷하다","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 서늘하다","mis":"SO6-2-u1-X14"}],"explanation":["건조 기후는 비가 아주 적은 곳에 나타나요.","낮에는 뜨겁고 밤에는 쌀쌀해요.","사막이나 초원이 펼쳐져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#3','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'sa','auto','나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식을 무엇이라고 하나요? 「○○ 농업」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"sa","stem":"나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식을 무엇이라고 하나요? 「○○ 농업」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["화전"],"explanation":["열대 기후 지역의 전통적인 농사 방식이에요.","카사바·얌·옥수수 등을 길렀어요.","재가 거름이 돼요."],"mis":"SO6-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#4','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'ox','auto','건조 기후 사막 지역의 사람들은 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요.',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"ox","stem":"건조 기후 사막 지역의 사람들은 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요.","answer":"O","reason_options":[{"t":"강한 햇볕과 모래바람으로부터 몸을 보호해야 하기 때문에","correct":true},{"t":"사막은 일 년 내내 추워서 두꺼운 옷이 필요하기 때문에","mis":"SO6-2-u1-X11"}],"mis":"SO6-2-u1-X11","explanation":["사막은 햇볕이 강해요.","모래바람도 불어요.","그래서 온몸을 감싸는 옷을 입어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#5','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'match','auto','기후 지역과 그곳의 집 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"match","stem":"기후 지역과 그곳의 집 모습을 알맞게 이으세요.","pairs":[{"l":"열대 기후 지역","r":"큰 창과 땅에서 띄운 바닥"},{"l":"건조 기후 사막 지역","r":"두꺼운 벽과 작은 창의 흙벽돌 집"},{"l":"건조 기후 초원 지역","r":"옮겨 다닐 수 있는 이동식 가옥"}],"mis":"SO6-2-u1-X12","explanation":["집은 기후에 맞추어 지어요.","열대 — 바람이 통하게, 사막 — 햇볕을 막게 해요.","초원 — 물과 풀을 찾아 옮겨 다녀요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#6','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역에서 오늘날 대규모로 재배하는 작물이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역에서 오늘날 대규모로 재배하는 작물이 아닌 것은 어느 것인가요?","options":[{"t":"올리브","correct":true},{"t":"천연고무","mis":"SO6-2-u1-X15"},{"t":"카카오","mis":"SO6-2-u1-X15"},{"t":"바나나","mis":"SO6-2-u1-X15"}],"explanation":["열대 기후 지역에서는 천연고무·카카오·바나나·커피를 대규모로 길러요.","올리브는 지중해 주변에서 많이 길러요.","기후마다 잘 자라는 작물이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#7','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역의 집이 창을 크게 하고 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역의 집이 창을 크게 하고 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"덥고 습해서 바람이 잘 통하게 하고 땅의 습기와 물을 피하려고","correct":true},{"t":"모래바람이 집 안에 들어오게 하려고","mis":"SO6-2-u1-X12"},{"t":"추운 겨울에 햇볕을 많이 받으려고","mis":"SO6-2-u1-X12"},{"t":"물과 풀을 찾아 옮겨 다니려고","mis":"SO6-2-u1-X12"}],"explanation":["열대 기후는 덥고 비가 많아요.","큰 창으로 바람이 통하게 해요.","바닥을 띄워 습기와 물을 피해요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#8','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',2,'mc','auto','건조 기후의 초원 지역 사람들이 이동식 가옥에서 사는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X02','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"건조 기후의 초원 지역 사람들이 이동식 가옥에서 사는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물과 풀을 찾아 가축과 함께 옮겨 다니기 때문에","correct":true},{"t":"비가 너무 많이 와서 집이 잠기기 때문에","mis":"SO6-2-u1-X11"},{"t":"땅속에 구리가 많기 때문에","mis":"SO6-2-u1-X02"},{"t":"바닷물이 자주 들어오기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["초원은 비가 조금 와서 풀이 자라요.","사람들은 가축을 기르며 물과 풀을 찾아 옮겨 다녀요.","그래서 옮기기 쉬운 집에서 살아요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#9','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역에는 비가 일 년 내내 많이 와 열대 우림을 이루는 곳도 있고, 건기와 우기가 번갈아 와 초원이 펼쳐진 곳도 있어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역에는 비가 일 년 내내 많이 와 열대 우림을 이루는 곳도 있고, 건기와 우기가 번갈아 와 초원이 펼쳐진 곳도 있어요.","answer":"O","reason_options":[{"t":"같은 열대 기후라도 비가 오는 모양에 따라 경관이 다르기 때문에","correct":true},{"t":"열대 기후 지역은 모두 사막이기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["우기는 비가 많은 때, 건기는 비가 적은 때예요.","비가 늘 많으면 열대 우림이 돼요.","건기·우기가 번갈아 오면 초원이 펼쳐져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_basic#10','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',3,'error','auto','두 기후 지역의 집을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"두 기후 지역의 집을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「사막 지역의 집도 바람이 잘 통하게 창을 크게 만들어.」","correct":true,"mis_target":"SO6-2-u1-X12"},{"t":"승우 — 「사막 지역의 집은 햇볕과 모래바람을 막으려고 창이 작아.」","mis":"SO6-2-u1-X12"},{"t":"보람 — 「열대 지역의 집은 바닥을 땅에서 띄우기도 해.」","mis":"SO6-2-u1-X12"}],"explanation":["사막은 햇볕과 모래바람을 막아야 해요.","그래서 벽이 두껍고 창이 작아요.","승우와 보람은 바르게 말했어요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#1','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',2,'sa','auto','일 년 가운데 비가 많이 내리는 시기를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"sa","stem":"일 년 가운데 비가 많이 내리는 시기를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["우기"],"explanation":["비가 많은 때는 우기예요.","비가 적은 때는 건기예요.","열대 초원은 우기·건기가 번갈아 와요."],"mis":"SO6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#2','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',2,'mc','auto','사막 지역에서 농사를 지을 수 있는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"사막 지역에서 농사를 지을 수 있는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"물이 솟아나는 오아시스 주변","correct":true},{"t":"모래 언덕 꼭대기","mis":"SO6-2-u1-X11"},{"t":"눈과 얼음으로 덮인 곳","mis":"SO6-2-u1-X14"},{"t":"비가 늘 많은 열대 우림","mis":"SO6-2-u1-X11"}],"explanation":["사막은 비가 아주 적어요.","물이 있는 오아시스 주변에서는 농사를 지어요.","물이 생활을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#3','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',3,'mc','auto','「한 채의 집으로는 열대 기후 지역과 사막 지역에 다 맞출 수 없었다.」 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"mc","stem":"「한 채의 집으로는 열대 기후 지역과 사막 지역에 다 맞출 수 없었다.」 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 지역은 기후가 달라 막아야 하는 것과 들여야 하는 것이 다르기 때문에","correct":true},{"t":"두 지역 모두 비가 많이 오기 때문에","mis":"SO6-2-u1-X11"},{"t":"집을 지을 때마다 알맞은 모양이 아무렇게나 바뀌기 때문에","mis":"SO6-2-u1-X12"},{"t":"두 지역의 기온과 강수량이 똑같기 때문에","mis":"SO6-2-u1-X11"}],"explanation":["열대 지역은 바람을 들여야 해요.","사막 지역은 햇볕과 모래바람을 막아야 해요.","그래서 창의 크기부터 달라요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#4','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'error','auto','열대 기후 지역의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"error","stem":"열대 기후 지역의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「열대 기후 지역 사람들은 모두 화전 농업만 하며 살아.」","correct":true,"mis_target":"SO6-2-u1-X15"},{"t":"지호 — 「오늘날에는 커피·카카오 같은 작물을 대규모로 재배하기도 해.」","mis":"SO6-2-u1-X15"},{"t":"나은 — 「사파리 관광 같은 생태 관광도 이루어져.」","mis":"SO6-2-u1-X15"}],"explanation":["화전 농업은 전통적인 방식이에요.","오늘날에는 대규모 재배와 생태 관광도 해요.","한 가지 모습을 열대 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#5','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',3,'ox','auto','카이로(이집트)처럼 건조 기후가 나타나는 곳은 낮에는 뜨겁지만 밤에는 쌀쌀해질 수 있어요.',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"ox","stem":"카이로(이집트)처럼 건조 기후가 나타나는 곳은 낮에는 뜨겁지만 밤에는 쌀쌀해질 수 있어요.","answer":"O","reason_options":[{"t":"건조 기후는 낮과 밤의 기온 차이가 크기 때문에","correct":true},{"t":"건조 기후는 하루 내내 기온이 같기 때문에","mis":"SO6-2-u1-X11"}],"mis":"SO6-2-u1-X11","explanation":["건조 기후는 비가 적어요.","낮과 밤의 기온 차이가 커요.","그래서 밤에는 쌀쌀할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#6','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'mc','auto','열대 기후와 건조 기후를 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"열대 기후와 건조 기후를 바르게 견준 것은 어느 것인가요?","options":[{"t":"열대는 일 년 내내 덥고 기온 변화가 거의 없으며, 건조는 비가 적고 낮과 밤의 기온 차이가 크다","correct":true},{"t":"열대는 비가 적고 일교차가 크며, 건조는 일 년 내내 비가 많다","mis":"SO6-2-u1-X11"},{"t":"두 기후는 기온과 강수량이 같아 생활도 똑같다","mis":"SO6-2-u1-X11"},{"t":"열대는 겨울이 길고, 건조는 눈이 많이 온다","mis":"SO6-2-u1-X13"}],"explanation":["열대 — 늘 덥고 비가 많은 곳이 많아요.","건조 — 비가 적고 낮밤 차이가 커요.","기후가 달라 생활도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#7','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',3,'match','auto','기후와 그 기후 지역의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"match","stem":"기후와 그 기후 지역의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"열대 기후","r":"천연고무·카카오를 대규모로 재배한다"},{"l":"건조 기후 사막","r":"오아시스 주변에서 농사짓는다"},{"l":"건조 기후 초원","r":"가축을 데리고 옮겨 다니는 유목을 한다"}],"mis":"SO6-2-u1-X12","explanation":["기후마다 생활 모습이 달라요.","열대 — 대규모 재배·생태 관광이에요.","건조 — 오아시스 농사·유목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#8','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',4,'mc','auto','사막 지역의 흙벽돌 집이 벽은 두껍고 창은 작은 까닭을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X12']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"mc","stem":"사막 지역의 흙벽돌 집이 벽은 두껍고 창은 작은 까닭을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"낮의 강한 햇볕과 모래바람을 막고 밤의 쌀쌀함도 견디려고","correct":true},{"t":"비가 많이 와 빗물이 들어오지 않게 하려고","mis":"SO6-2-u1-X11"},{"t":"바람이 잘 통해 시원하게 하려고","mis":"SO6-2-u1-X12"},{"t":"물과 풀을 찾아 쉽게 옮기려고","mis":"SO6-2-u1-X12"}],"explanation":["사막은 햇볕이 강하고 모래바람이 불어요.","낮과 밤의 기온 차이도 커요.","두꺼운 벽과 작은 창이 이것을 막아 줘요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#9','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C6',4,'essay','teacher','열대 기후 지역과 건조 기후 사막 지역의 집 모습을 견주어 쓰고, 그렇게 다른 까닭을 두 지역의 기후 특징을 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"essay","stem":"열대 기후 지역과 건조 기후 사막 지역의 집 모습을 견주어 쓰고, 그렇게 다른 까닭을 두 지역의 기후 특징을 들어 쓰세요.","answer_guide":{"answer":"예: 열대 기후 지역의 집은 창이 크고 바닥을 땅에서 띄우지만, 사막 지역의 흙벽돌 집은 벽이 두껍고 창이 작다. 열대 기후는 일 년 내내 덥고 비가 많아 바람을 잘 통하게 하고 습기를 피해야 하고, 건조 기후 사막은 비가 적고 햇볕이 강하며 모래바람이 불어 이를 막아야 하기 때문이다.","scoring_points":["두 지역의 집 모습을 견주어 썼는가","두 기후의 특징을 바르게 썼는가","기후 특징과 집 모습을 까닭으로 이었는가"]},"explanation":["집 모습을 먼저 견주어요.","기후 특징을 떠올려요.","막을 것과 들일 것을 이어요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L07_challenge#10','soc',6,2,'u1','L07','g6_2_soc_u1_L07_challenge','lesson_challenge','SO6-2-u1-C7',4,'essay','teacher','「건조 기후 지역 사람들은 모두 사막의 흙벽돌 집에서 산다.」라는 말이 왜 알맞지 않은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C7","difficulty":4,"kind":"essay","stem":"「건조 기후 지역 사람들은 모두 사막의 흙벽돌 집에서 산다.」라는 말이 왜 알맞지 않은지 쓰세요.","answer_guide":{"answer":"예: 건조 기후 지역에는 사막만 있는 것이 아니라 약간의 비나 눈이 내려 초원이 펼쳐진 곳도 있다. 초원에서는 가축을 데리고 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활한다. 같은 기후 지역이라도 생활 모습은 여러 가지이므로 한 곳의 모습을 그 기후 전체의 모습으로 여기면 안 된다.","scoring_points":["건조 기후에 초원도 있음을 썼는가","초원의 유목 생활과 이동식 가옥을 썼는가","한 곳의 모습을 기후 전체로 여기면 안 된다는 점을 썼는가"]},"explanation":["건조 기후에는 사막과 초원이 있어요.","초원은 유목과 이동식 가옥이에요.","같은 기후도 생활은 여러 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#1','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'mc','auto','온대 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"온대 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"중위도 지역에 주로 나타나며 사계절의 변화가 비교적 뚜렷하다","correct":true},{"t":"적도 주변에 나타나며 일 년 내내 덥다","mis":"SO6-2-u1-X11"},{"t":"남극과 북극 주변에 나타나며 매우 춥다","mis":"SO6-2-u1-X14"},{"t":"비가 아주 적어 사막이 넓다","mis":"SO6-2-u1-X11"}],"explanation":["온대 기후는 중위도에 나타나요.","봄·여름·가을·겨울이 비교적 뚜렷해요.","온화한 기후로 여러 농업이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#2','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'mc','auto','냉대 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"냉대 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다","correct":true},{"t":"일 년 내내 기온 변화가 거의 없다","mis":"SO6-2-u1-X11"},{"t":"여름이 덥고 건조하며 겨울에 비가 많다","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 서늘한 날씨가 이어진다","mis":"SO6-2-u1-X14"}],"explanation":["냉대 기후는 북반구 중·고위도에 나타나요.","겨울이 길고 몹시 추워요.","눈이 많이 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#3','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'sa','auto','젖소나 염소를 길러 우유·치즈 등을 만드는 농업을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"sa","stem":"젖소나 염소를 길러 우유·치즈 등을 만드는 농업을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["낙농업"],"explanation":["서부 유럽에서 발달했어요.","젖소·염소의 젖으로 우유·치즈를 만들어요.","서부 유럽은 밀도 많이 길러요."],"mis":"SO6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#4','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',1,'ox','auto','냉대 기후 지역에는 침엽수림이 넓게 발달해 목재와 펄프 생산이 활발해요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"ox","stem":"냉대 기후 지역에는 침엽수림이 넓게 발달해 목재와 펄프 생산이 활발해요.","answer":"O","reason_options":[{"t":"추위에 강한 바늘잎나무 숲이 넓게 자라기 때문에","correct":true},{"t":"냉대 기후 지역에는 나무가 자라지 않기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["침엽수는 바늘처럼 뾰족한 잎을 가진 나무예요.","냉대 기후 지역에 넓은 숲을 이뤄요.","펄프는 종이의 원료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#5','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'match','auto','온대 기후 지역과 그곳에서 많이 하는 농업을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"match","stem":"온대 기후 지역과 그곳에서 많이 하는 농업을 알맞게 이으세요.","pairs":[{"l":"서부 유럽","r":"밀 재배와 낙농업"},{"l":"지중해 주변","r":"올리브와 포도 재배"},{"l":"우리나라를 비롯한 아시아","r":"벼농사"}],"mis":"SO6-2-u1-X13","explanation":["같은 온대 기후라도 지역마다 농업이 달라요.","서부 유럽 — 밀·낙농업이에요.","지중해 — 올리브·포도, 아시아 — 벼농사예요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#6','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','지중해 주변 지역의 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"지중해 주변 지역의 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","correct":true},{"t":"여름이 서늘하고 겨울이 따뜻하며 비가 고르게 온다","mis":"SO6-2-u1-X13"},{"t":"여름에 덥고 비가 많으며 겨울은 춥고 건조하다","mis":"SO6-2-u1-X13"},{"t":"겨울이 여름보다 길고 몹시 춥다","mis":"SO6-2-u1-X13"}],"explanation":["지중해 주변은 여름이 덥고 건조해요.","겨울은 따뜻하고 비가 많아요.","그래서 올리브·포도가 잘 자라요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#7','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','냉대 기후 지역에서 여름에 기르는 작물로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"냉대 기후 지역에서 여름에 기르는 작물로 알맞은 것은 어느 것인가요?","options":[{"t":"밀·옥수수·감자","correct":true},{"t":"카카오·바나나","mis":"SO6-2-u1-X12"},{"t":"올리브·포도","mis":"SO6-2-u1-X13"},{"t":"천연고무·커피","mis":"SO6-2-u1-X12"}],"explanation":["냉대 기후 지역은 겨울에 농사짓기 어려워요.","짧은 여름에 밀·옥수수·감자를 길러요.","카카오·바나나는 열대 작물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#8','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'ox','auto','우리나라는 여름에 덥고 비가 많이 내리며 겨울은 춥고 건조한 온대 기후가 나타나요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"우리나라는 여름에 덥고 비가 많이 내리며 겨울은 춥고 건조한 온대 기후가 나타나요.","answer":"O","reason_options":[{"t":"우리나라는 중위도에 있어 이런 특징의 온대 기후가 나타나기 때문에","correct":true},{"t":"우리나라는 일 년 내내 기온 변화가 거의 없기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["우리나라는 사계절이 뚜렷해요.","여름은 덥고 비가 많아요.","겨울은 춥고 건조해요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#9','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',2,'mc','auto','서부 유럽의 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"서부 유럽의 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","correct":true},{"t":"여름이 덥고 건조하다","mis":"SO6-2-u1-X13"},{"t":"겨울이 길고 몹시 추우며 눈이 많다","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 덥고 비가 많다","mis":"SO6-2-u1-X11"}],"explanation":["서부 유럽은 바다의 영향을 받아요.","여름은 서늘하고 겨울은 따뜻해요.","비가 고르게 와요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_basic#10','soc',6,2,'u1','L08','g6_2_soc_u1_L08_basic','lesson_basic','SO6-2-u1-C8',3,'error','auto','온대 기후와 냉대 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"error","stem":"온대 기후와 냉대 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「냉대 기후는 사계절이 없고 일 년 내내 겨울이야.」","correct":true,"mis_target":"SO6-2-u1-X13"},{"t":"시온 — 「냉대 기후도 사계절이 있지만 겨울이 여름보다 길어.」","mis":"SO6-2-u1-X13"},{"t":"다율 — 「온대 기후는 사계절의 변화가 비교적 뚜렷해.」","mis":"SO6-2-u1-X13"}],"explanation":["냉대 기후에도 사계절이 있어요.","다만 겨울이 길고 몹시 추워요.","시온과 다율은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#1','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',2,'sa','auto','나무에서 뽑아낸 것으로 종이의 원료로 쓰는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"sa","stem":"나무에서 뽑아낸 것으로 종이의 원료로 쓰는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["펄프"],"explanation":["냉대 기후 지역의 침엽수림에서 많이 얻어요.","나무에서 뽑아내요.","종이를 만드는 원료예요."],"mis":"SO6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#2','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',2,'mc','auto','오슬로(노르웨이)처럼 냉대 기후가 나타나는 곳의 겨울 생활로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"오슬로(노르웨이)처럼 냉대 기후가 나타나는 곳의 겨울 생활로 알맞은 것은 어느 것인가요?","options":[{"t":"눈이 많고 몹시 추워 농사를 짓기 어렵다","correct":true},{"t":"일 년 내내 덥고 비가 많아 화전 농업을 한다","mis":"SO6-2-u1-X11"},{"t":"여름보다 겨울이 짧아 겨울에도 농사가 잘된다","mis":"SO6-2-u1-X13"},{"t":"비가 거의 오지 않아 오아시스에서 농사짓는다","mis":"SO6-2-u1-X11"}],"explanation":["냉대 기후는 겨울이 길고 몹시 추워요.","눈이 많이 내려요.","겨울에는 농사를 짓기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#3','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'mc','auto','같은 온대 기후인데도 서부 유럽·지중해 주변·우리나라의 농업이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"같은 온대 기후인데도 서부 유럽·지중해 주변·우리나라의 농업이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 온대 기후 안에서도 여름과 겨울에 비가 오는 모양과 기온이 서로 달라서","correct":true},{"t":"온대 기후는 지역마다 이름만 다를 뿐 기후는 같아서","mis":"SO6-2-u1-X15"},{"t":"세 지역 모두 겨울이 여름보다 길어서","mis":"SO6-2-u1-X13"},{"t":"세 지역 모두 비가 전혀 오지 않아서","mis":"SO6-2-u1-X11"}],"explanation":["서부 유럽은 비가 고르게 와요.","지중해 주변은 여름이 건조하고 겨울에 비가 와요.","우리나라는 여름에 비가 많아요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#4','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'error','auto','온대 기후 지역의 농업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"error","stem":"온대 기후 지역의 농업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「지중해 주변에서는 여름에 비가 많아 벼농사를 많이 지어.」","correct":true,"mis_target":"SO6-2-u1-X13"},{"t":"준서 — 「지중해 주변에서는 올리브와 포도를 많이 길러.」","mis":"SO6-2-u1-X13"},{"t":"예린 — 「우리나라를 비롯한 아시아에서는 벼농사를 많이 지어.」","mis":"SO6-2-u1-X13"}],"explanation":["지중해 주변은 여름이 덥고 건조해요.","올리브와 포도가 잘 자라요.","벼농사는 여름에 비가 많은 아시아에서 많이 지어요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#5','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'ox','auto','여름 한 철만 보아서는 그 도시에 비가 내리는 모양을 알 수 없고, 한 도시 안에서 여름과 겨울을 견주어야 알 수 있어요.',ARRAY['SO6-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"ox","stem":"여름 한 철만 보아서는 그 도시에 비가 내리는 모양을 알 수 없고, 한 도시 안에서 여름과 겨울을 견주어야 알 수 있어요.","answer":"O","reason_options":[{"t":"여름에 비가 많은지 겨울에 비가 많은지를 견주어야 기후의 모양이 보이기 때문에","correct":true},{"t":"기후는 여름 날씨 하루만 보면 다 알 수 있기 때문에","mis":"SO6-2-u1-X08"}],"mis":"SO6-2-u1-X08","explanation":["기후는 일 년 전체를 보아야 해요.","여름과 겨울의 비를 견주어요.","그래야 지중해·서부 유럽·우리나라가 갈려요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#6','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'mc','auto','「겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다」는 어느 기후의 특징인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"「겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다」는 어느 기후의 특징인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"열대 기후","mis":"SO6-2-u1-X11"},{"t":"건조 기후","mis":"SO6-2-u1-X11"}],"explanation":["겨울이 여름보다 길다는 것이 실마리예요.","냉대 기후의 특징이에요.","온대 기후는 사계절이 비교적 고르게 뚜렷해요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#7','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',3,'match','auto','기후와 그곳의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"match","stem":"기후와 그곳의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"서부 유럽의 온대 기후","r":"밀을 기르고 우유·치즈를 만든다"},{"l":"지중해 주변의 온대 기후","r":"올리브와 포도를 기른다"},{"l":"냉대 기후","r":"침엽수림에서 목재와 펄프를 얻는다"}],"mis":"SO6-2-u1-X13","explanation":["기후가 생활을 정해요.","온대 안에서도 지역마다 달라요.","냉대는 숲에서 목재를 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#8','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'mc','auto','온대 기후와 냉대 기후 지역의 생활을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"mc","stem":"온대 기후와 냉대 기후 지역의 생활을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"온대는 온화한 기후로 밀·낙농업·올리브·포도·벼농사 등 다양한 농업이 발달했고, 냉대는 여름에 밀·옥수수·감자를 기르며 침엽수림으로 목재·펄프 산업이 발달했다","correct":true},{"t":"온대와 냉대 모두 일 년 내내 덥고 화전 농업을 한다","mis":"SO6-2-u1-X11"},{"t":"온대는 겨울이 길어 농사를 못 짓고, 냉대는 사계절 내내 농사가 잘된다","mis":"SO6-2-u1-X13"},{"t":"온대 기후 지역은 어디나 벼농사만 짓는다","mis":"SO6-2-u1-X15"}],"explanation":["온대 — 다양한 농업이에요.","냉대 — 여름 농사와 숲의 산업이에요.","한 지역 모습을 기후 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#9','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'essay','teacher','서부 유럽과 지중해 주변은 둘 다 온대 기후인데 많이 기르는 작물이 달라요. 두 지역의 기후 특징과 농업을 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"essay","stem":"서부 유럽과 지중해 주변은 둘 다 온대 기후인데 많이 기르는 작물이 달라요. 두 지역의 기후 특징과 농업을 견주어 쓰세요.","answer_guide":{"answer":"예: 서부 유럽은 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 와서 밀을 많이 기르고 낙농업이 발달했다. 지중해 주변은 여름이 덥고 건조하며 겨울은 따뜻하고 비가 많아서, 건조한 여름을 잘 견디는 올리브와 포도를 많이 기른다.","scoring_points":["서부 유럽의 기후와 농업을 썼는가","지중해 주변의 기후와 농업을 썼는가","기후 차이가 농업 차이로 이어짐을 썼는가"]},"explanation":["같은 온대도 기후 모양이 달라요.","비가 오는 때를 견주어요.","기후가 작물을 정해요."],"asset":{"type":"passage","lines":["서부 유럽 — 여름이 서늘하고 겨울이 따뜻하며 일 년 내내 비가 고르게 온다","지중해 주변 — 여름은 덥고 건조하며 겨울은 따뜻하고 비가 많다","우리나라 — 여름은 덥고 비가 많으며 겨울은 춥고 건조하다","냉대 기후 지역 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다"],"title":"온대 기후 셋과 냉대 기후"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L08_challenge#10','soc',6,2,'u1','L08','g6_2_soc_u1_L08_challenge','lesson_challenge','SO6-2-u1-C8',4,'essay','teacher','냉대 기후 지역 사람들이 기후에 맞추어 살아가는 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"essay","stem":"냉대 기후 지역 사람들이 기후에 맞추어 살아가는 모습을 두 가지 쓰세요.","answer_guide":{"answer":"예: 겨울이 길고 몹시 추워 겨울에는 농사를 짓기 어려우므로 짧은 여름에 밀·옥수수·감자를 기른다. 또 추위에 강한 침엽수림이 넓게 발달해 나무를 베어 목재와 종이의 원료인 펄프를 만든다.","scoring_points":["냉대 기후의 특징을 썼는가","기후에 맞춘 생활을 두 가지 썼는가","기후와 생활을 까닭으로 이었는가"]},"explanation":["겨울이 길고 몹시 추워요.","여름 농사를 해요.","숲에서 목재와 펄프를 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#1','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'mc','auto','한대 기후가 주로 나타나는 곳은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"한대 기후가 주로 나타나는 곳은 어느 것인가요?","options":[{"t":"남극과 북극 주변의 고위도 지역","correct":true},{"t":"적도 주변의 저위도 지역","mis":"SO6-2-u1-X10"},{"t":"중위도의 바닷가","mis":"SO6-2-u1-X10"},{"t":"사막 한가운데","mis":"SO6-2-u1-X11"}],"explanation":["한대 기후는 극지방에 나타나요.","겨울이 길고 기온이 매우 낮아요.","눈과 얼음에 덮인 곳이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#2','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'mc','auto','고산 기후가 나타나는 곳은 어느 것인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"고산 기후가 나타나는 곳은 어느 것인가요?","options":[{"t":"해발 고도가 높은 지역","correct":true},{"t":"남극과 북극 주변","mis":"SO6-2-u1-X14"},{"t":"넓은 평야","mis":"SO6-2-u1-X14"},{"t":"바다와 육지가 만나는 곳","mis":"SO6-2-u1-X14"}],"explanation":["고산 기후는 높은 산지에 나타나요.","위도가 아니라 높이가 정해요.","적도 주변에도 고산 기후가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#3','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'sa','auto','극지방의 하늘에 여러 가지 색깔의 빛이 나타나는 현상을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"sa","stem":"극지방의 하늘에 여러 가지 색깔의 빛이 나타나는 현상을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["오로라"],"explanation":["극지방의 밤하늘에 나타나요.","여러 색의 빛이 춤추듯 보여요.","오로라를 보는 관광이 발달하고 있어요."],"mis":"SO6-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#4','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',1,'ox','auto','고산 기후 지역 사람들은 챙이 넓고 둥근 모자를 써서 강한 햇빛을 막아요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"ox","stem":"고산 기후 지역 사람들은 챙이 넓고 둥근 모자를 써서 강한 햇빛을 막아요.","answer":"O","reason_options":[{"t":"높은 곳은 햇빛이 강하기 때문에","correct":true},{"t":"고산 기후 지역에는 햇빛이 비치지 않기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["높은 산지는 햇빛이 강해요.","챙이 넓은 모자로 햇빛을 막아요.","옷을 여러 겹 입고 망토도 둘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#5','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'match','auto','한대 기후와 고산 기후를 그곳의 생활 모습과 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"match","stem":"한대 기후와 고산 기후를 그곳의 생활 모습과 알맞게 이으세요.","pairs":[{"l":"한대 기후","r":"이끼가 자라는 곳에서 순록을 기르며 옮겨 다닌다"},{"l":"고산 기후","r":"알파카와 라마를 기르고 감자를 재배한다"}],"mis":"SO6-2-u1-X14","explanation":["한대 기후 — 순록 유목·사냥이에요.","고산 기후 — 알파카·라마, 감자·옥수수예요.","둘 다 춥지만 생활이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#6','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','한대 기후 지역 사람들이 주로 먹는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"한대 기후 지역 사람들이 주로 먹는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"사냥하여 얻은 생선과 고기","correct":true},{"t":"오아시스에서 기른 대추야자","mis":"SO6-2-u1-X12"},{"t":"화전 농업으로 기른 카사바","mis":"SO6-2-u1-X12"},{"t":"지중해 주변에서 기른 올리브","mis":"SO6-2-u1-X13"}],"explanation":["한대 기후 지역은 농사짓기 어려워요.","사냥해 얻은 생선과 고기를 주로 먹어요.","기후가 먹을거리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#7','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','고산 기후 지역 사람들이 옷을 여러 겹 입고 망토를 두르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X11','SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"고산 기후 지역 사람들이 옷을 여러 겹 입고 망토를 두르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"낮과 밤의 기온 차이가 커서 입고 벗으며 맞추려고","correct":true},{"t":"일 년 내내 몹시 더워서","mis":"SO6-2-u1-X14"},{"t":"비가 전혀 오지 않아서","mis":"SO6-2-u1-X11"},{"t":"바다에서 물고기를 잡으려고","mis":"SO6-2-u1-X03"}],"explanation":["고산 기후는 낮과 밤의 기온 차이가 커요.","옷을 여러 겹 입으면 입고 벗기 쉬워요.","망토도 둘러 추위를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#8','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'ox','auto','적도 주변의 일부 고산 기후 지역은 일 년 내내 서늘해 사람이 많이 모여 살아요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"ox","stem":"적도 주변의 일부 고산 기후 지역은 일 년 내내 서늘해 사람이 많이 모여 살아요.","answer":"O","reason_options":[{"t":"적도 주변의 낮은 곳은 덥지만 높은 산지는 일 년 내내 서늘해 살기 좋기 때문에","correct":true},{"t":"고산 기후 지역에는 사람이 살 수 없기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["키토(에콰도르)가 그런 곳이에요.","적도 주변이라도 높은 곳은 서늘해요.","그래서 사람이 많이 모여 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#9','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',2,'mc','auto','최근 한대 기후 지역에서 활발해진 일이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"최근 한대 기후 지역에서 활발해진 일이 아닌 것은 어느 것인가요?","options":[{"t":"넓은 평야에서의 벼농사","correct":true},{"t":"지하자원 개발","mis":"SO6-2-u1-X14"},{"t":"극지방 기후 환경 연구","mis":"SO6-2-u1-X14"},{"t":"오로라와 빙하를 이용한 관광","mis":"SO6-2-u1-X14"}],"explanation":["한대 기후 지역은 농사짓기 어려워요.","지하자원 개발·극지 연구·관광이 활발해요.","벼농사는 여름에 비가 많은 아시아에서 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_basic#10','soc',6,2,'u1','L09','g6_2_soc_u1_L09_basic','lesson_basic','SO6-2-u1-C9',3,'error','auto','추운 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"추운 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「추운 기후는 극지방에만 있어. 적도 주변은 다 더워.」","correct":true,"mis_target":"SO6-2-u1-X14"},{"t":"여울 — 「적도 주변이라도 높은 산 위로 오르면 서늘한 고산 기후가 나타나.」","mis":"SO6-2-u1-X14"},{"t":"이준 — 「북쪽으로 아주 멀리 가면 한대 기후가 나타나.」","mis":"SO6-2-u1-X14"}],"explanation":["추운 기후로 가는 길은 둘이에요.","고위도로 멀리 가거나, 높이 오르거나예요.","여울과 이준은 바르게 말했어요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#1','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',2,'sa','auto','한대 기후 지역에서 짧은 여름에 이끼가 자라는 곳을 찾아 옮겨 다니며 기르는 동물은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한대 기후 지역에서 짧은 여름에 이끼가 자라는 곳을 찾아 옮겨 다니며 기르는 동물은 무엇인가요? 두 글자로 쓰세요.","answer":["순록"],"explanation":["짧은 여름에 땅이 녹아 이끼가 자라요.","순록이 이끼를 먹어요.","사람들은 순록을 기르며 옮겨 다녀요."],"mis":"SO6-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#2','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',2,'mc','auto','고산 기후 지역에서 주로 재배하는 작물로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"고산 기후 지역에서 주로 재배하는 작물로 알맞은 것은 어느 것인가요?","options":[{"t":"감자와 옥수수","correct":true},{"t":"카카오와 바나나","mis":"SO6-2-u1-X12"},{"t":"올리브와 포도","mis":"SO6-2-u1-X13"},{"t":"밀과 낙농업","mis":"SO6-2-u1-X13"}],"explanation":["고산 기후 지역은 서늘해요.","감자와 옥수수를 주로 길러요.","알파카·라마도 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#3','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','「추운 기후로 가는 두 길」을 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"「추운 기후로 가는 두 길」을 바르게 정리한 것은 어느 것인가요?","options":[{"t":"고위도로 멀리 가면 한대 기후, 적도 주변이라도 높이 오르면 고산 기후","correct":true},{"t":"고위도로 가면 고산 기후, 높이 오르면 한대 기후","mis":"SO6-2-u1-X14"},{"t":"추운 기후로 가는 길은 북쪽으로 가는 하나뿐","mis":"SO6-2-u1-X09"},{"t":"적도로 가면 한대 기후, 바다로 가면 고산 기후","mis":"SO6-2-u1-X10"}],"explanation":["위도가 높아지면 추워져요.","해발 고도가 높아져도 추워져요.","한대와 고산은 서로 다른 길이에요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#4','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'error','auto','한대·고산 기후 지역의 생활을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"한대·고산 기후 지역의 생활을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?","options":[{"t":"소율 — 「고산 기후 — 순록 유목과 오로라 관광」","correct":true,"mis_target":"SO6-2-u1-X14"},{"t":"건우 — 「한대 기후 — 사냥으로 얻은 생선과 고기」","mis":"SO6-2-u1-X14"},{"t":"지아 — 「고산 기후 — 알파카와 라마 기르기」","mis":"SO6-2-u1-X14"}],"explanation":["순록 유목과 오로라 관광은 한대 기후 지역이에요.","고산 기후는 알파카·라마, 감자·옥수수예요.","건우와 지아는 바르게 짝지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#5','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'ox','auto','고산 기후는 극지방처럼 일 년 내내 눈과 얼음으로 덮여 있는 기후예요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"ox","stem":"고산 기후는 극지방처럼 일 년 내내 눈과 얼음으로 덮여 있는 기후예요.","answer":"X","reason_options":[{"t":"적도 주변의 일부 고산 기후 지역은 일 년 내내 서늘해 사람이 많이 모여 살기 때문에","correct":true},{"t":"높은 곳은 모두 극지방과 같기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["눈과 얼음에 덮인 곳이 많은 것은 한대 기후예요.","고산 기후는 서늘한 날씨가 이어지는 곳이 있어요.","두 기후를 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#6','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','키토(에콰도르)는 적도 가까이 있는데도 일 년 내내 서늘해요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X08']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"키토(에콰도르)는 적도 가까이 있는데도 일 년 내내 서늘해요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"해발 고도가 높은 곳에 있기 때문에","correct":true},{"t":"남극과 가까이 있기 때문에","mis":"SO6-2-u1-X09"},{"t":"바닷물이 차갑기 때문에","mis":"SO6-2-u1-X09"},{"t":"하루 내내 비가 오기 때문에","mis":"SO6-2-u1-X08"}],"explanation":["적도 주변의 낮은 곳은 일 년 내내 더워요.","키토는 높은 산지에 있어요.","그래서 고산 기후가 나타나요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#7','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'match','auto','기후와 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"match","stem":"기후와 그 특징을 알맞게 이으세요.","pairs":[{"l":"한대 기후","r":"겨울이 길고 기온이 매우 낮다"},{"l":"고산 기후","r":"일 년 내내 서늘하고 낮과 밤의 기온 차이가 크다"},{"l":"냉대 기후","r":"사계절이 있지만 겨울이 여름보다 길고 몹시 춥다"}],"mis":"SO6-2-u1-X14","explanation":["세 기후 모두 추운 쪽이에요.","한대는 매우 춥고, 고산은 서늘해요.","냉대는 사계절이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#8','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'mc','auto','한대 기후 지역에서 최근 생활 모습이 바뀌고 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X15','SO6-2-u1-X11']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"mc","stem":"한대 기후 지역에서 최근 생활 모습이 바뀌고 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지하자원 개발·극지방 기후 연구·오로라와 빙하 관광처럼 새로운 일이 늘고 있기 때문에","correct":true},{"t":"한대 기후가 갑자기 열대 기후로 바뀌었기 때문에","mis":"SO6-2-u1-X10"},{"t":"사람들이 모두 벼농사를 짓기 시작했기 때문에","mis":"SO6-2-u1-X15"},{"t":"한대 기후 지역에 사막이 생겼기 때문에","mis":"SO6-2-u1-X11"}],"explanation":["예전에는 사냥과 순록 유목이 중심이었어요.","최근에는 자원 개발·연구·관광이 활발해요.","사람들은 기후를 극복하며 새 일을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#9','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','한대 기후와 고산 기후는 둘 다 추운 쪽의 기후예요. 두 기후가 나타나는 곳과 생활 모습을 하나씩 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한대 기후와 고산 기후는 둘 다 추운 쪽의 기후예요. 두 기후가 나타나는 곳과 생활 모습을 하나씩 견주어 쓰세요.","answer_guide":{"answer":"예: 한대 기후는 남극과 북극 주변의 고위도 지역에 나타나며, 사람들은 사냥해 얻은 생선과 고기를 먹고 이끼가 자라는 곳에서 순록을 기른다. 고산 기후는 해발 고도가 높은 곳에 나타나며, 사람들은 감자와 옥수수를 기르고 알파카와 라마를 키우며 챙 넓은 모자와 여러 겹의 옷으로 기후에 적응한다.","scoring_points":["두 기후가 나타나는 곳을 바르게 썼는가","두 기후의 생활 모습을 하나씩 바르게 썼는가","고위도와 고산의 차이가 드러나는가"]},"explanation":["한대 — 고위도예요.","고산 — 높은 곳이에요.","생활 모습도 달라요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L09_challenge#10','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','고산 기후 지역 사람들이 기후에 적응하는 옷차림을 두 가지 쓰고, 각각 어떤 기후 특징에 맞춘 것인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"고산 기후 지역 사람들이 기후에 적응하는 옷차림을 두 가지 쓰고, 각각 어떤 기후 특징에 맞춘 것인지 쓰세요.","answer_guide":{"answer":"예: 챙이 넓고 둥근 모자를 쓰는데, 높은 곳이라 햇빛이 강하기 때문이다. 옷을 여러 겹 입고 망토를 두르는데, 낮과 밤의 기온 차이가 커서 입고 벗으며 맞추기 위해서이다.","scoring_points":["옷차림을 두 가지 썼는가","각각 맞춘 기후 특징을 썼는가","기후에 적응한다는 점이 드러나는가"]},"explanation":["강한 햇빛 → 챙 넓은 모자예요.","큰 일교차 → 여러 겹 옷과 망토예요.","기후에 맞춘 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#1','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'mc','auto','기후와 사람들의 생활에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"기후와 사람들의 생활에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"사람들은 기후에 적응하고 이를 극복하면서 다양한 모습으로 살아간다","correct":true},{"t":"기후는 사람들의 생활과 관계가 없다","mis":"SO6-2-u1-X02"},{"t":"같은 기후 지역의 생활은 모두 똑같다","mis":"SO6-2-u1-X15"},{"t":"사람들은 기후를 전혀 바꾸거나 이겨 내지 못한다","mis":"SO6-2-u1-X02"}],"explanation":["기후는 생활에 큰 영향을 줘요.","사람들은 기후에 맞추어 살아요.","기후를 극복하는 방법도 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#2','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'mc','auto','기후와 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"기후와 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 인터넷으로 조사하기 → 디지털 영상 지도에 표시하기 → 공유하기","correct":true},{"t":"공유하기 → 주제 정하기 → 지도에 표시하기 → 조사하기","mis":"SO6-2-u1-X17"},{"t":"지도에 표시하기 → 공유하기 → 조사하기 → 주제 정하기","mis":"SO6-2-u1-X17"},{"t":"조사하기 → 공유하기 → 주제 정하기 → 지도에 표시하기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 주제를 정해요.","조사한 것을 지도에 표시해요.","그다음 친구들과 공유해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#3','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'ox','auto','상품 판매 계획을 세울 때는 판매할 나라의 지형과 기후를 조사해야 해요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"ox","stem":"상품 판매 계획을 세울 때는 판매할 나라의 지형과 기후를 조사해야 해요.","answer":"O","reason_options":[{"t":"그곳 사람들에게 필요한 상품은 그곳의 자연환경에 따라 달라지기 때문에","correct":true},{"t":"상품은 어느 나라에서나 똑같이 쓰이기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["자연환경은 생활의 불편과 필요를 만들어요.","지형과 기후를 조사해요.","그 특징을 상품에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#4','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'sa','auto','자연환경을 고려한 상품 판매 계획에서 가장 먼저 하는 일은 판매할 무엇을 정하는 것인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"sa","stem":"자연환경을 고려한 상품 판매 계획에서 가장 먼저 하는 일은 판매할 무엇을 정하는 것인가요? 두 글자로 쓰세요.","answer":["나라"],"explanation":["먼저 판매할 나라를 정해요.","그다음 그 나라의 지형과 기후를 조사해요.","아이디어를 이야기하고 계획을 세워요."],"mis":"SO6-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#5','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','노르웨이의 냉대 기후 지역에 팔 방한용 안전 신발에 스파이크를 단 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"노르웨이의 냉대 기후 지역에 팔 방한용 안전 신발에 스파이크를 단 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"겨울이 길고 눈과 얼음이 많아 미끄러지지 않게 하려고","correct":true},{"t":"일 년 내내 덥고 비가 많아서","mis":"SO6-2-u1-X11"},{"t":"모래바람이 심해서","mis":"SO6-2-u1-X11"},{"t":"바닷가 모래사장에서 걷기 좋게 하려고","mis":"SO6-2-u1-X16"}],"explanation":["냉대 기후는 겨울이 길고 몹시 추워요.","눈과 얼음 위에서 미끄러지기 쉬워요.","스파이크가 그 불편을 덜어 줘요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","기후의 특징 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다","판매 동기 — 겨울에 밖에서 이동하기가 불편하다","상품 — 방한용 안전 신발","상품 특징 — 바닥 스파이크 · 스키 부착 · 열선"],"title":"자연환경을 고려한 상품 판매 계획서(예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#6','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'match','auto','자연환경의 특징과 그곳에 맞는 상품 아이디어를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"match","stem":"자연환경의 특징과 그곳에 맞는 상품 아이디어를 알맞게 이으세요.","pairs":[{"l":"브라질의 열대 우림","r":"해충 퇴치기"},{"l":"콩고강","r":"튼튼한 어망"},{"l":"네팔 히말라야산맥","r":"만능 등산 장비"},{"l":"노르웨이의 냉대 기후","r":"방한용 안전 신발"}],"mis":"SO6-2-u1-X16","explanation":["상품은 그곳의 자연환경에 맞춰요.","열대 우림 — 벌레, 강 — 고기잡이예요.","높은 산 — 등산, 추위 — 방한이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#7','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','자연환경을 고려한 상품 판매 계획의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"나라 정하기 → 지형과 기후 조사하기 → 아이디어 이야기하기 → 판매 계획 세우기 → 글과 그림으로 나타내기","correct":true},{"t":"글과 그림으로 나타내기 → 나라 정하기 → 판매 계획 세우기 → 조사하기","mis":"SO6-2-u1-X17"},{"t":"판매 계획 세우기 → 조사하기 → 나라 정하기 → 아이디어 이야기하기","mis":"SO6-2-u1-X17"},{"t":"아이디어 이야기하기 → 글과 그림 → 나라 정하기 → 조사하기","mis":"SO6-2-u1-X17"}],"explanation":["나라를 먼저 정해요.","지형과 기후를 조사하고 아이디어를 나눠요.","계획을 세워 글과 그림으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#8','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'ox','auto','같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타날 수 있어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타날 수 있어요.","answer":"O","reason_options":[{"t":"같은 온대 기후에서도 밀·올리브·벼처럼 지역마다 생활이 다르기 때문에","correct":true},{"t":"같은 기후면 생활도 꼭 같기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 기후 칸에도 여러 핀이 설 수 있어요.","온대 기후에서도 지역마다 농업이 달라요.","생활은 여러 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#9','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','상품 아이디어를 고를 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"상품 아이디어를 고를 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"아이디어를 실제로 만들 수 있을지(실현 가능성)","correct":true},{"t":"이름이 가장 긴 상품인지","mis":"SO6-2-u1-X16"},{"t":"어느 나라에서나 똑같이 쓸 수 있는지","mis":"SO6-2-u1-X16"},{"t":"그림을 그리기 쉬운지","mis":"SO6-2-u1-X16"}],"explanation":["좋은 아이디어도 만들 수 있어야 해요.","실현 가능성을 함께 따져요.","자연환경에 맞는지도 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_basic#10','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',3,'error','auto','상품 판매 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"상품 판매 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 가지 상품을 만들면 세계 어느 곳에서나 똑같이 잘 팔릴 거야.」","correct":true,"mis_target":"SO6-2-u1-X16"},{"t":"주원 — 「판매할 곳의 지형이나 기후에 맞춘 기능을 넣어야 해.」","mis":"SO6-2-u1-X16"},{"t":"하린 — 「곳이 바뀌면 맞는 기능도 바뀌어.」","mis":"SO6-2-u1-X16"}],"explanation":["자연환경이 다르면 필요한 것도 달라요.","곳마다 맞는 기능이 있어요.","주원과 하린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#1','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'sa','auto','사람들이 기후에 맞추어 살아가는 것을 「적응」이라고 해요. 기후의 어려움을 이겨 내는 것은 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"sa","stem":"사람들이 기후에 맞추어 살아가는 것을 「적응」이라고 해요. 기후의 어려움을 이겨 내는 것은 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["극복"],"explanation":["사람들은 기후에 적응해요.","기후의 어려움을 극복하기도 해요.","두 가지가 함께 생활을 만들어요."],"mis":"SO6-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#2','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'mc','auto','네팔 히말라야산맥을 오르는 셰르파를 위한 상품 아이디어로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"네팔 히말라야산맥을 오르는 셰르파를 위한 상품 아이디어로 알맞은 것은 어느 것인가요?","options":[{"t":"만능 등산 장비","correct":true},{"t":"해충 퇴치기","mis":"SO6-2-u1-X16"},{"t":"수상 시장용 배","mis":"SO6-2-u1-X16"},{"t":"사막용 물주머니","mis":"SO6-2-u1-X16"}],"explanation":["히말라야산맥은 높고 험한 산지예요.","셰르파는 산을 오르는 사람들이에요.","그래서 등산 장비가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#3','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','추위가 심한 냉대 기후 지역과 한대 기후 지역에 같은 기능(열선)을 넣은 상품을 팔 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X16','SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"추위가 심한 냉대 기후 지역과 한대 기후 지역에 같은 기능(열선)을 넣은 상품을 팔 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 곳 모두 추위라는 같은 특징이 있기 때문에","correct":true},{"t":"두 곳 모두 열대 기후이기 때문에","mis":"SO6-2-u1-X10"},{"t":"상품은 어디서나 똑같이 쓰이기 때문에","mis":"SO6-2-u1-X16"},{"t":"두 곳 모두 비가 거의 오지 않기 때문에","mis":"SO6-2-u1-X11"}],"explanation":["곳이 바뀌면 맞는 기능도 바뀌어요.","하지만 같은 특징이 있는 곳에는 같은 기능이 쓰여요.","추위 → 열선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#4','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'error','auto','기후와 생활 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"기후와 생활 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「한 나라의 생활 모습을 조사하면 그 기후 전체의 생활을 다 안 거야.」","correct":true,"mis_target":"SO6-2-u1-X15"},{"t":"채원 — 「같은 온대 기후 칸에도 여러 생활 모습이 있었어.」","mis":"SO6-2-u1-X15"},{"t":"지민 — 「조사한 곳을 디지털 영상 지도에 표시해 공유하자.」","mis":"SO6-2-u1-X17"}],"explanation":["한 곳의 모습이 그 기후 전체는 아니에요.","같은 기후에도 생활은 여러 가지예요.","채원과 지민은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#5','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'ox','auto','브라질의 열대 우림 지역에 해충 퇴치기를 파는 계획은 그곳의 자연환경을 고려한 계획이에요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"ox","stem":"브라질의 열대 우림 지역에 해충 퇴치기를 파는 계획은 그곳의 자연환경을 고려한 계획이에요.","answer":"O","reason_options":[{"t":"일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림의 특징에 맞추었기 때문에","correct":true},{"t":"해충 퇴치기는 어느 나라에서나 똑같이 필요하기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["브라질은 열대 기후가 나타나요.","아마존강 주변에 열대 우림이 넓어요.","덥고 습해 벌레가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#6','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','상품 판매 계획서에서 「판매 동기」에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"상품 판매 계획서에서 「판매 동기」에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"그곳의 자연환경 때문에 사람들이 겪는 불편","correct":true},{"t":"상품의 값","mis":"SO6-2-u1-X16"},{"t":"만든 사람의 이름","mis":"SO6-2-u1-X16"},{"t":"상품 포장지의 색깔","mis":"SO6-2-u1-X16"}],"explanation":["판매 동기는 왜 이 상품이 필요한지예요.","자연환경에서 오는 불편을 써요.","노르웨이 예 — 겨울에 이동하기 불편해요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","기후의 특징 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다","판매 동기 — 겨울에 밖에서 이동하기가 불편하다","상품 — 방한용 안전 신발","상품 특징 — 바닥 스파이크 · 스키 부착 · 열선"],"title":"자연환경을 고려한 상품 판매 계획서(예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#7','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'match','auto','판매 계획서의 칸과 노르웨이 예시의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"match","stem":"판매 계획서의 칸과 노르웨이 예시의 내용을 알맞게 이으세요.","pairs":[{"l":"기후의 특징","r":"겨울이 길고 몹시 추우며 눈이 많다"},{"l":"판매 동기","r":"겨울에 밖에서 이동하기 불편하다"},{"l":"상품","r":"방한용 안전 신발"},{"l":"상품 특징","r":"스파이크 · 스키 부착 · 열선"}],"mis":"SO6-2-u1-X16","explanation":["기후 특징에서 불편이 나와요.","불편을 덜어 줄 상품을 정해요.","상품 특징에 기후가 담겨요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","기후의 특징 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다","판매 동기 — 겨울에 밖에서 이동하기가 불편하다","상품 — 방한용 안전 신발","상품 특징 — 바닥 스파이크 · 스키 부착 · 열선"],"title":"자연환경을 고려한 상품 판매 계획서(예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#8','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'mc','auto','자연환경을 고려한 상품 판매 계획의 핵심을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16','SO6-2-u1-X17']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획의 핵심을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"그곳의 지형과 기후를 분석해 사람들의 불편을 찾고, 그 특징을 상품의 기능에 담으며 실현 가능성도 따진다","correct":true},{"t":"가장 비싼 상품을 골라 어느 나라에나 똑같이 판다","mis":"SO6-2-u1-X16"},{"t":"지형과 기후는 보지 않고 그림만 예쁘게 그린다","mis":"SO6-2-u1-X16"},{"t":"친구가 정한 상품을 그대로 따라 한다","mis":"SO6-2-u1-X17"}],"explanation":["자연환경 분석이 먼저예요.","불편 → 기능으로 이어요.","실제로 만들 수 있는지도 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#9','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'essay','teacher','건조 기후의 사막 지역에 팔 상품을 하나 구상해 보세요. 판매할 곳의 기후 특징, 판매 동기, 상품의 특징을 차례로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"건조 기후의 사막 지역에 팔 상품을 하나 구상해 보세요. 판매할 곳의 기후 특징, 판매 동기, 상품의 특징을 차례로 쓰세요.","answer_guide":{"answer":"예: 기후 특징 — 비가 아주 적고 햇볕이 강하며 모래바람이 불고 낮과 밤의 기온 차이가 크다. 판매 동기 — 낮에는 햇볕과 모래바람에 눈과 피부가 상하고 밤에는 쌀쌀하다. 상품 — 햇볕과 모래를 막는 두건이 달린 겉옷. 특징 — 얼굴을 가리는 그물 가리개, 햇볕을 반사하는 옅은 색 천, 밤에 덧입을 수 있는 안감.","scoring_points":["사막의 기후 특징을 바르게 썼는가","기후에서 오는 불편을 판매 동기로 썼는가","기후 특징을 상품 기능에 담았는가"]},"explanation":["기후 특징 → 불편 → 기능으로 이어요.","사막은 햇볕·모래바람·큰 일교차예요.","실현 가능한 기능으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_L10_challenge#10','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',4,'essay','teacher','같은 기후 지역에서도 생활 모습이 여러 가지인 까닭을 예를 들어 쓰고, 기후와 생활을 조사할 때 주의할 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"같은 기후 지역에서도 생활 모습이 여러 가지인 까닭을 예를 들어 쓰고, 기후와 생활을 조사할 때 주의할 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 같은 온대 기후라도 서부 유럽은 비가 고르게 와서 밀과 낙농업, 지중해 주변은 여름이 건조해 올리브와 포도, 우리나라는 여름에 비가 많아 벼농사가 발달했다. 같은 기후 안에서도 기온과 비가 오는 모양, 지형이 조금씩 다르기 때문이다. 조사할 때는 한 곳의 모습을 그 기후 전체의 모습으로 여기지 않고 믿을 만한 자료에서 찾는다.","scoring_points":["같은 기후에서 생활이 다른 예를 들었는가","그 까닭을 썼는가","조사할 때 주의할 점을 썼는가"]},"explanation":["같은 기후도 생활은 여러 가지예요.","기온·비·지형의 차이가 있어요.","한 곳을 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#1','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C1',1,'mc','auto','바다와 육지가 만나는 곳에 나타나는 지형의 갈래는 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"바다와 육지가 만나는 곳에 나타나는 지형의 갈래는 어느 것인가요?","options":[{"t":"해안","correct":true},{"t":"산지","mis":"SO6-2-u1-X03"},{"t":"하천","mis":"SO6-2-u1-X03"},{"t":"사막","mis":"SO6-2-u1-X03"}],"explanation":["바다와 육지가 만나는 곳은 해안이에요.","갯벌·모래사장·절벽이 나타나요.","피오르도 해안 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#2','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',1,'mc','auto','하천 지역에서 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X04','SO6-2-u1-X11']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C3","difficulty":1,"kind":"mc","stem":"하천 지역에서 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"흐르는 물로 전기를 만드는 수력 발전","correct":true},{"t":"갯벌에서 소금을 만드는 염전","mis":"SO6-2-u1-X06"},{"t":"산비탈의 계단식 농사","mis":"SO6-2-u1-X04"},{"t":"오아시스 주변 농사","mis":"SO6-2-u1-X11"}],"explanation":["하천의 물은 힘을 줘요.","그 힘으로 전기를 만들어요.","염전은 해안, 계단식 농사는 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#3','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',1,'mc','auto','「한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태」를 무엇이라고 하나요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X09','SO6-2-u1-X01']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"「한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태」를 무엇이라고 하나요?","options":[{"t":"기후","correct":true},{"t":"날씨","mis":"SO6-2-u1-X08"},{"t":"해발 고도","mis":"SO6-2-u1-X09"},{"t":"지형","mis":"SO6-2-u1-X01"}],"explanation":["여러 해의 평균 상태는 기후예요.","하루하루의 상태는 날씨예요.","기후는 기온과 강수량으로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#4','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',1,'mc','auto','적도 주변의 저위도에 주로 나타나는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"적도 주변의 저위도에 주로 나타나는 기후는 어느 것인가요?","options":[{"t":"열대 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X10"},{"t":"냉대 기후","mis":"SO6-2-u1-X10"},{"t":"온대 기후","mis":"SO6-2-u1-X10"}],"explanation":["적도 주변은 햇볕을 많이 받아요.","일 년 내내 더운 열대 기후가 나타나요.","극으로 갈수록 추운 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#5','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',1,'mc','auto','일 년 내내 비가 많이 내려 열대 우림이 펼쳐지는 곳의 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"mc","stem":"일 년 내내 비가 많이 내려 열대 우림이 펼쳐지는 곳의 기후는 어느 것인가요?","options":[{"t":"열대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X11"},{"t":"냉대 기후","mis":"SO6-2-u1-X13"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["열대 우림은 열대 기후에 나타나요.","일 년 내내 덥고 비가 많아요.","아마존강 주변이 대표적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#6','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C8',1,'mc','auto','사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 오는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"사계절이 있지만 겨울이 여름보다 길고 몹시 추우며 눈이 많이 오는 기후는 어느 것인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"열대 기후","mis":"SO6-2-u1-X11"},{"t":"건조 기후","mis":"SO6-2-u1-X11"}],"explanation":["겨울이 길다는 것이 실마리예요.","냉대 기후의 특징이에요.","북반구 중·고위도에 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#7','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',1,'mc','auto','일 년 내내 눈과 얼음으로 덮인 곳이 많은 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"일 년 내내 눈과 얼음으로 덮인 곳이 많은 기후는 어느 것인가요?","options":[{"t":"한대 기후","correct":true},{"t":"고산 기후","mis":"SO6-2-u1-X14"},{"t":"냉대 기후","mis":"SO6-2-u1-X14"},{"t":"온대 기후","mis":"SO6-2-u1-X14"}],"explanation":["한대 기후는 극지방에 나타나요.","겨울이 길고 기온이 매우 낮아요.","눈과 얼음에 덮인 곳이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#8','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',1,'mc','auto','자연환경을 고려한 상품 판매 계획을 세울 때 그 나라에서 조사할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획을 세울 때 그 나라에서 조사할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"지형과 기후","correct":true},{"t":"그 나라 국기의 모양","mis":"SO6-2-u1-X16"},{"t":"그 나라 사람들의 이름","mis":"SO6-2-u1-X16"},{"t":"그 나라의 인기 노래","mis":"SO6-2-u1-X16"}],"explanation":["자연환경은 지형과 기후예요.","사람들의 불편과 필요가 여기서 나와요.","그 특징을 상품에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#9','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'mc','auto','여행 엽서 ㉮의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉮의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"열대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X11"},{"t":"냉대 기후","mis":"SO6-2-u1-X13"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["일 년 내내 덥고 비가 자주 와요.","바닥을 띄운 집과 카카오 농장이 있어요.","열대 기후의 생활이에요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#10','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',2,'mc','auto','여행 엽서 ㉱에서 사람들이 하고 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉱에서 사람들이 하고 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌을 이용해 소금을 만드는 일","correct":true},{"t":"배가 드나드는 항구를 짓는 일","mis":"SO6-2-u1-X06"},{"t":"구리를 캐는 일","mis":"SO6-2-u1-X03"},{"t":"양을 기르는 일","mis":"SO6-2-u1-X03"}],"explanation":["바다와 땅이 만나는 해안이에요.","넓은 갯벌에 바닷물을 가두어 말려요.","하얀 알갱이는 소금이에요."],"asset":{"type":"passage","lines":["바다와 땅이 만나는 곳이야. 물이 빠지면 넓은 갯벌이 드러나.","네모난 칸마다 바닷물을 가두어 햇볕에 말려.","하얀 알갱이를 긁어모으는 사람들이 보여."],"title":"여행 엽서 ㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#11','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',2,'ox','auto','관광객이 늘어난 해안에서는 일자리와 소득뿐 아니라 쓰레기와 오염도 함께 늘 수 있어요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"관광객이 늘어난 해안에서는 일자리와 소득뿐 아니라 쓰레기와 오염도 함께 늘 수 있어요.","answer":"O","reason_options":[{"t":"관광에는 긍정적인 영향과 부정적인 영향이 함께 있기 때문에","correct":true},{"t":"관광은 좋은 점만 가져오기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광은 일자리와 소득을 늘려요.","쓰레기와 오염도 늘어요.","두 쪽을 함께 봐요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#12','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',2,'mc','auto','같은 적도 주변인데도 한 곳은 덥고 다른 곳은 서늘한 까닭이 되는 요인은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"같은 적도 주변인데도 한 곳은 덥고 다른 곳은 서늘한 까닭이 되는 요인은 어느 것인가요?","options":[{"t":"해발 고도","correct":true},{"t":"나라 이름","mis":"SO6-2-u1-X10"},{"t":"인구","mis":"SO6-2-u1-X10"},{"t":"요일","mis":"SO6-2-u1-X08"}],"explanation":["위도가 같아도 높이가 다를 수 있어요.","높이 오르면 서늘해져요.","해발 고도도 기후에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#13','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'match','auto','기후와 그곳의 집이나 옷을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"match","stem":"기후와 그곳의 집이나 옷을 알맞게 이으세요.","pairs":[{"l":"열대 기후","r":"바닥을 띄운 집과 얇은 옷"},{"l":"건조 기후 사막","r":"두꺼운 벽의 흙벽돌 집과 온몸을 감싸는 옷"},{"l":"고산 기후","r":"챙 넓은 모자와 여러 겹의 옷"}],"mis":"SO6-2-u1-X12","explanation":["집과 옷은 기후에 맞춰요.","열대 — 바람, 사막 — 햇볕과 모래를 생각해요.","고산 — 강한 햇빛과 큰 일교차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#14','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C8',2,'ox','auto','같은 온대 기후 지역이면 어디서나 벼농사를 지어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"같은 온대 기후 지역이면 어디서나 벼농사를 지어요.","answer":"X","reason_options":[{"t":"서부 유럽은 밀·낙농업, 지중해 주변은 올리브·포도처럼 지역마다 농업이 다르기 때문에","correct":true},{"t":"온대 기후는 벼만 자라는 기후이기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 온대 기후도 지역마다 달라요.","비가 오는 모양과 기온이 조금씩 달라요.","그래서 농업도 여러 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#15','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C2',2,'mc','auto','산지 가운데 넓고 평평하며 풀이 잘 자라는 고원에서 사람들이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"산지 가운데 넓고 평평하며 풀이 잘 자라는 고원에서 사람들이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"양 같은 가축을 기른다","correct":true},{"t":"계단식 논을 만든다","mis":"SO6-2-u1-X04"},{"t":"수상 시장을 연다","mis":"SO6-2-u1-X03"},{"t":"염전을 만든다","mis":"SO6-2-u1-X03"}],"explanation":["고원은 높지만 평평해요.","풀이 잘 자라 가축을 길러요.","파미르고원이 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#16','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',2,'mc','auto','일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림 지역에 알맞은 상품은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림 지역에 알맞은 상품은 어느 것인가요?","options":[{"t":"해충 퇴치기","correct":true},{"t":"스파이크가 달린 방한 신발","mis":"SO6-2-u1-X16"},{"t":"눈썰매","mis":"SO6-2-u1-X16"},{"t":"모래바람 가리개","mis":"SO6-2-u1-X16"}],"explanation":["열대 우림은 덥고 습해요.","벌레가 많아요.","해충 퇴치기가 쓸모 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#17','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',3,'error','auto','하천 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"하천 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「강가의 넓은 평야는 바닷물이 들어와서 생긴 거야.」","correct":true,"mis_target":"SO6-2-u1-X05"},{"t":"지호 — 「강물이 날라 온 흙이 쌓여 평야가 생겨.」","mis":"SO6-2-u1-X05"},{"t":"나은 — 「강은 배가 물건을 실어 나르는 길이 되기도 해.」","mis":"SO6-2-u1-X05"}],"explanation":["평야는 강물이 날라 온 흙이 쌓여 생겨요.","바닷물이 들어오는 것은 피오르 같은 해안이에요.","지호와 나은은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#18','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',3,'error','auto','적도에서 극으로 가는 기후의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X09']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"적도에서 극으로 가는 기후의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「적도에서 극으로 가면 한대·냉대·온대·건조·열대 차례로 나타나.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"이서 — 「적도에서 극으로 가면 열대부터 한대까지 차례로 나타나.」","mis":"SO6-2-u1-X10"},{"t":"라온 — 「매우 높은 산지에는 고산 기후가 나타나.」","mis":"SO6-2-u1-X09"}],"explanation":["적도는 열대에서 시작해요.","열대 → 건조 → 온대 → 냉대 → 한대예요.","도하는 차례를 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#19','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'mc','auto','여행 엽서 ㉯의 곳을 「한대 기후가 아니라 고산 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X08']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉯의 곳을 「한대 기후가 아니라 고산 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「적도 가까운 나라인데 높은 산 위라 서늘해」","correct":true},{"t":"「사람들은 망토를 둘렀어」","mis":"SO6-2-u1-X14"},{"t":"「알파카가 풀을 뜯고 있어」","mis":"SO6-2-u1-X14"},{"t":"「한낮」이라는 말이 있어서","mis":"SO6-2-u1-X08"}],"explanation":["추운 기후로 가는 길은 둘이에요.","적도 가까운 곳의 높은 산이면 고산 기후예요.","망토·알파카만으로는 위도를 알 수 없어요."],"asset":{"type":"passage","lines":["적도 가까운 나라인데 높은 산 위라 한낮에도 서늘해.","사람들은 챙 넓은 둥근 모자를 쓰고 망토를 둘렀어.","언덕에서 털이 복슬복슬한 알파카가 풀을 뜯고 있어."],"title":"여행 엽서 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#20','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'mc','auto','한대 기후와 고산 기후를 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X11']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"한대 기후와 고산 기후를 바르게 견준 것은 어느 것인가요?","options":[{"t":"한대는 극지방 주변의 고위도에, 고산은 해발 고도가 높은 곳에 나타난다","correct":true},{"t":"한대는 높은 산에, 고산은 극지방에 나타난다","mis":"SO6-2-u1-X14"},{"t":"둘 다 적도 주변의 낮은 곳에 나타난다","mis":"SO6-2-u1-X09"},{"t":"둘 다 일 년 내내 덥다","mis":"SO6-2-u1-X11"}],"explanation":["추운 기후로 가는 길은 둘이에요.","고위도로 가면 한대예요.","높이 오르면 고산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#21','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',3,'mc','auto','자연환경을 고려한 상품 판매 계획에서 「아이디어 이야기하기」 바로 앞에 할 일은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획에서 「아이디어 이야기하기」 바로 앞에 할 일은 어느 것인가요?","options":[{"t":"지형과 기후 조사하기","correct":true},{"t":"글과 그림으로 나타내기","mis":"SO6-2-u1-X17"},{"t":"판매 계획 세우기","mis":"SO6-2-u1-X17"},{"t":"발표하기","mis":"SO6-2-u1-X17"}],"explanation":["나라를 정하고 지형과 기후를 조사해요.","그다음 아이디어를 이야기해요.","계획을 세워 글과 그림으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#22','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',3,'mc','auto','관광이 늘어난 섬이 「섬을 한동안 쉬게 하기로」 할 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"관광이 늘어난 섬이 「섬을 한동안 쉬게 하기로」 할 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"오염이 줄어드는 대신 섬 사람들의 일자리와 소득도 줄어든다는 점","correct":true},{"t":"섬을 쉬게 하면 좋은 점만 생긴다는 점","mis":"SO6-2-u1-X07"},{"t":"관광은 섬과 아무 관계가 없다는 점","mis":"SO6-2-u1-X02"},{"t":"쉬게 하면 관광객이 더 늘어난다는 점","mis":"SO6-2-u1-X07"}],"explanation":["관광의 영향은 함께 움직여요.","줄이면 오염도 일자리도 줄어요.","두 쪽을 함께 따져요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#23','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',4,'mc','auto','여행 엽서 ㉮·㉯·㉰·㉵의 곳을 기후 이름과 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X13']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"여행 엽서 ㉮·㉯·㉰·㉵의 곳을 기후 이름과 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 열대 · ㉯ 고산 · ㉰ 냉대 · ㉵ 한대","correct":true},{"t":"㉮ 건조 · ㉯ 한대 · ㉰ 온대 · ㉵ 고산","mis":"SO6-2-u1-X14"},{"t":"㉮ 열대 · ㉯ 한대 · ㉰ 냉대 · ㉵ 고산","mis":"SO6-2-u1-X14"},{"t":"㉮ 온대 · ㉯ 고산 · ㉰ 한대 · ㉵ 냉대","mis":"SO6-2-u1-X13"}],"explanation":["㉮ — 늘 덥고 비, 카카오 → 열대예요.","㉯ — 적도 가까운 높은 산 → 고산, ㉰ — 긴 겨울·침엽수 → 냉대예요.","㉵ — 오로라·순록 → 한대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#24','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',4,'essay','teacher','여행 엽서 ㉯의 곳은 적도 가까이 있는데도 서늘해요. 그 까닭을 쓰고, 이곳 사람들이 기후에 적응하는 생활 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉯의 곳은 적도 가까이 있는데도 서늘해요. 그 까닭을 쓰고, 이곳 사람들이 기후에 적응하는 생활 모습을 두 가지 쓰세요.","answer_guide":{"answer":"예: 위도는 적도 가까이에 있지만 해발 고도가 높은 산 위라서 높이 올라갈수록 기온이 낮아져 일 년 내내 서늘한 고산 기후가 나타난다. 이곳 사람들은 강한 햇빛을 막으려고 챙 넓은 둥근 모자를 쓰고, 낮과 밤의 기온 차이에 맞추려고 옷을 여러 겹 입고 망토를 두른다. 또 알파카와 라마를 기르고 감자와 옥수수를 재배한다.","scoring_points":["해발 고도가 높아 서늘하다는 까닭을 썼는가","고산 기후임을 밝혔는가","기후에 적응하는 생활 모습을 두 가지 썼는가"]},"explanation":["위도만으로 기후가 정해지지 않아요.","높이가 기후를 바꿔요.","모자·옷·알파카가 적응의 모습이에요."],"asset":{"type":"passage","lines":["적도 가까운 나라인데 높은 산 위라 한낮에도 서늘해.","사람들은 챙 넓은 둥근 모자를 쓰고 망토를 둘렀어.","언덕에서 털이 복슬복슬한 알파카가 풀을 뜯고 있어."],"title":"여행 엽서 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_a#25','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',4,'essay','teacher','관광객이 많이 찾아오는 해안 마을이 있어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 두 영향을 함께 고려한 해결 방법을 제안하세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"관광객이 많이 찾아오는 해안 마을이 있어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 두 영향을 함께 고려한 해결 방법을 제안하세요.","answer_guide":{"answer":"예: 긍정적인 영향 — 숙소·식당 일자리가 생겨 마을 사람들의 소득이 늘어난다. 부정적인 영향 — 바닷가에 쓰레기가 쌓이고 바닷물이 오염된다. 제안 — 하루에 받는 관광객 수를 정하고 쓰레기를 되가져가게 하며, 해마다 한 달은 바닷가를 쉬게 해서 소득을 지키면서 오염을 줄인다.","scoring_points":["긍정적인 영향을 썼는가","부정적인 영향을 썼는가","두 영향을 함께 고려한 제안을 했는가"]},"explanation":["관광에는 두 영향이 함께 있어요.","한쪽만 보지 않아요.","좋은 점은 살리고 걱정은 줄여요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#1','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',1,'mc','auto','해발 고도가 높고 대체로 경사가 급한 지형의 갈래는 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"해발 고도가 높고 대체로 경사가 급한 지형의 갈래는 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"해안","mis":"SO6-2-u1-X03"},{"t":"하천","mis":"SO6-2-u1-X03"},{"t":"평야","mis":"SO6-2-u1-X03"}],"explanation":["높이 솟은 땅은 산지예요.","고원과 화산도 산지에 들어요.","하천은 물이 흐르는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#2','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',1,'mc','auto','해안 지역에서 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안 지역에서 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"물고기나 조개를 기르는 양식업","correct":true},{"t":"구리를 캐는 광업","mis":"SO6-2-u1-X03"},{"t":"수상 시장","mis":"SO6-2-u1-X03"},{"t":"파미르고원의 양 기르기","mis":"SO6-2-u1-X03"}],"explanation":["해안 주민들은 어업과 양식업을 해요.","항구·관광지·염전도 있어요.","광업은 산지, 수상 시장은 하천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#3','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',1,'sa','auto','세계의 기후를 구분하는 주된 기준은 기온과 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"sa","stem":"세계의 기후를 구분하는 주된 기준은 기온과 무엇인가요? 세 글자로 쓰세요.","answer":["강수량"],"explanation":["기온은 덥고 추운 정도예요.","강수량은 비나 눈이 내린 양이에요.","이 둘로 기후를 나눠요."],"mis":"SO6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#4','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',1,'mc','auto','적도에서 극지방으로 갈 때 건조 기후 다음에 나타나는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"적도에서 극지방으로 갈 때 건조 기후 다음에 나타나는 기후는 어느 것인가요?","options":[{"t":"온대 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X10"},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["차례는 열대 → 건조 → 온대 → 냉대 → 한대예요.","건조 다음은 온대예요.","고산은 차례에 들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#5','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C7',1,'mc','auto','강수량이 매우 적어 사막이 넓게 나타나는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"mc","stem":"강수량이 매우 적어 사막이 넓게 나타나는 기후는 어느 것인가요?","options":[{"t":"건조 기후","correct":true},{"t":"열대 기후","mis":"SO6-2-u1-X11"},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"한대 기후","mis":"SO6-2-u1-X14"}],"explanation":["비가 아주 적으면 사막이 돼요.","건조 기후의 특징이에요.","낮과 밤의 기온 차이도 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#6','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',1,'mc','auto','지중해 주변 지역에서 많이 기르는 작물은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"mc","stem":"지중해 주변 지역에서 많이 기르는 작물은 어느 것인가요?","options":[{"t":"올리브와 포도","correct":true},{"t":"카카오와 바나나","mis":"SO6-2-u1-X12"},{"t":"카사바와 얌","mis":"SO6-2-u1-X12"},{"t":"벼","mis":"SO6-2-u1-X13"}],"explanation":["지중해 주변은 여름이 덥고 건조해요.","올리브와 포도가 잘 자라요.","벼는 아시아에서 많이 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#7','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C9',1,'mc','auto','알파카와 라마를 기르는 사람들이 사는 곳의 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"알파카와 라마를 기르는 사람들이 사는 곳의 기후는 어느 것인가요?","options":[{"t":"고산 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X14"},{"t":"열대 기후","mis":"SO6-2-u1-X14"},{"t":"건조 기후","mis":"SO6-2-u1-X14"}],"explanation":["알파카와 라마는 높은 산지에서 길러요.","고산 기후 지역의 생활이에요.","감자와 옥수수도 길러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#8','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C10',1,'ox','auto','사람들은 기후에 적응하기도 하고 이를 극복하면서 살아가기도 해요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"ox","stem":"사람들은 기후에 적응하기도 하고 이를 극복하면서 살아가기도 해요.","answer":"O","reason_options":[{"t":"기후에 맞는 집과 옷을 만들고, 어려움을 이겨 낼 방법도 찾기 때문에","correct":true},{"t":"사람들은 기후 앞에서 아무것도 하지 못하기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["기후는 생활에 큰 영향을 줘요.","사람들은 기후에 맞추어 살아요.","어려움을 극복하기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#9','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C9',2,'mc','auto','여행 엽서 ㉯의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉯의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"고산 기후","correct":true},{"t":"한대 기후","mis":"SO6-2-u1-X14"},{"t":"열대 기후","mis":"SO6-2-u1-X09"},{"t":"건조 기후","mis":"SO6-2-u1-X11"}],"explanation":["적도 가까운데 높은 산 위라 서늘해요.","챙 넓은 모자와 망토, 알파카가 보여요.","고산 기후의 생활이에요."],"asset":{"type":"passage","lines":["적도 가까운 나라인데 높은 산 위라 한낮에도 서늘해.","사람들은 챙 넓은 둥근 모자를 쓰고 망토를 둘렀어.","언덕에서 털이 복슬복슬한 알파카가 풀을 뜯고 있어."],"title":"여행 엽서 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#10','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C3',2,'mc','auto','여행 엽서 ㉴의 곳은 어느 지형이고, 사람들은 무엇을 하고 있나요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C3","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉴의 곳은 어느 지형이고, 사람들은 무엇을 하고 있나요?","options":[{"t":"하천 — 배 위에서 물건을 사고파는 수상 시장","correct":true},{"t":"해안 — 갯벌의 염전","mis":"SO6-2-u1-X03"},{"t":"산지 — 계단식 농사","mis":"SO6-2-u1-X03"},{"t":"사막 — 오아시스 농사","mis":"SO6-2-u1-X03"}],"explanation":["강을 따라 내려가는 곳이에요.","배 위에서 사고팔아요.","하천의 수상 시장이에요."],"asset":{"type":"passage","lines":["강을 따라 내려가니 배들이 물 위에 모여 있었어.","배 위에서 과일과 채소를 사고팔고 있었어.","강가에는 강물이 날라 온 흙으로 넓은 들이 펼쳐져."],"title":"여행 엽서 ㉴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#11','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',2,'mc','auto','관광의 부정적인 영향으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"관광의 부정적인 영향으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷가에 쓰레기가 쌓이고 바닷물이 더러워진다","correct":true},{"t":"숙소와 식당에 일자리가 생긴다","mis":"SO6-2-u1-X07"},{"t":"마을 사람들의 소득이 늘어난다","mis":"SO6-2-u1-X07"},{"t":"여행객이 마을의 경관을 즐긴다","mis":"SO6-2-u1-X07"}],"explanation":["관광에는 걱정되는 점도 있어요.","쓰레기와 오염이 대표적이에요.","일자리와 소득은 긍정적인 영향이에요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#12','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',2,'mc','auto','기후 분포에 영향을 주는 요인을 바르게 모은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"기후 분포에 영향을 주는 요인을 바르게 모은 것은 어느 것인가요?","options":[{"t":"위도 · 위치 · 지형 · 해발 고도","correct":true},{"t":"위도 하나뿐","mis":"SO6-2-u1-X09"},{"t":"국기 · 언어 · 화폐","mis":"SO6-2-u1-X10"},{"t":"요일 · 시각 · 달력","mis":"SO6-2-u1-X08"}],"explanation":["위도가 큰 영향을 줘요.","위치·지형·해발 고도도 영향을 줘요.","여러 요인을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#13','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',2,'match','auto','기후와 그곳에서 많이 기르는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"match","stem":"기후와 그곳에서 많이 기르는 것을 알맞게 이으세요.","pairs":[{"l":"지중해 주변","r":"올리브와 포도"},{"l":"서부 유럽","r":"밀과 젖소"},{"l":"냉대 기후","r":"여름의 밀·옥수수·감자"},{"l":"고산 기후","r":"감자와 알파카"}],"mis":"SO6-2-u1-X13","explanation":["기후마다 잘 자라는 것이 달라요.","온대 안에서도 지역마다 달라요.","추운 기후에서도 여름이나 서늘함을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#14','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C7',2,'ox','auto','건조 기후 지역 사람들은 모두 사막에서 흙벽돌 집을 짓고 살아요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"ox","stem":"건조 기후 지역 사람들은 모두 사막에서 흙벽돌 집을 짓고 살아요.","answer":"X","reason_options":[{"t":"건조 기후에는 초원도 있어 이동식 가옥에서 유목 생활을 하는 사람들도 있기 때문에","correct":true},{"t":"건조 기후는 사막으로만 이루어져 있기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["건조 기후에는 사막과 초원이 있어요.","초원에서는 유목 생활을 해요.","한 곳을 기후 전체로 여기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#15','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C2',2,'mc','auto','경사가 가파른 산비탈에서 농사를 짓는 방법은 어느 것인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X12']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"경사가 가파른 산비탈에서 농사를 짓는 방법은 어느 것인가요?","options":[{"t":"계단식 농사","correct":true},{"t":"비행기를 이용한 농사","mis":"SO6-2-u1-X05"},{"t":"화전 농업","mis":"SO6-2-u1-X12"},{"t":"오아시스 농사","mis":"SO6-2-u1-X12"}],"explanation":["비탈은 그대로 농사짓기 어려워요.","계단처럼 깎아 평평한 땅을 만들어요.","산지를 이용하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#16','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C10',2,'mc','auto','높고 험한 산지를 오르는 사람들에게 알맞은 상품은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"높고 험한 산지를 오르는 사람들에게 알맞은 상품은 어느 것인가요?","options":[{"t":"만능 등산 장비","correct":true},{"t":"튼튼한 어망","mis":"SO6-2-u1-X16"},{"t":"해충 퇴치기","mis":"SO6-2-u1-X16"},{"t":"수영복","mis":"SO6-2-u1-X16"}],"explanation":["높은 산지는 험하고 추워요.","오르는 데 도움이 되는 장비가 필요해요.","자연환경이 필요를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#17','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',3,'error','auto','해안 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X06']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"해안 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「모래사장이 아름다운 해안에는 염전이 발달해.」","correct":true,"mis_target":"SO6-2-u1-X06"},{"t":"건우 — 「배가 드나들기 좋은 해안에는 항구가 발달해.」","mis":"SO6-2-u1-X06"},{"t":"지아 — 「갯벌이 넓은 해안에는 염전이 발달해.」","mis":"SO6-2-u1-X06"}],"explanation":["아름다운 모래사장은 관광지가 돼요.","염전은 넓은 갯벌에 발달해요.","건우와 지아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#18','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',3,'error','auto','온대·냉대 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"error","stem":"온대·냉대 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「지중해 주변은 여름에 비가 많고 겨울이 건조해.」","correct":true,"mis_target":"SO6-2-u1-X13"},{"t":"주원 — 「지중해 주변은 여름이 덥고 건조해.」","mis":"SO6-2-u1-X13"},{"t":"하린 — 「냉대 기후는 겨울이 여름보다 길어.」","mis":"SO6-2-u1-X13"}],"explanation":["지중해 주변은 여름이 건조하고 겨울에 비가 와요.","민서는 거꾸로 말했어요.","여름에 비가 많은 곳은 우리나라 같은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#19','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',3,'mc','auto','여행 엽서 ㉰의 곳을 「온대 기후가 아니라 냉대 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉰의 곳을 「온대 기후가 아니라 냉대 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「겨울이 끝없이 길어. 눈이 허리까지 쌓였어.」","correct":true},{"t":"「트럭이 지나가」","mis":"SO6-2-u1-X13"},{"t":"「감자밭이 초록으로 물든대」","mis":"SO6-2-u1-X13"},{"t":"「짧은 여름」만 있어서 사계절이 없다","mis":"SO6-2-u1-X13"}],"explanation":["겨울이 여름보다 길고 몹시 추우면 냉대 기후예요.","눈이 많이 와요.","사계절은 있지만 여름이 짧아요."],"asset":{"type":"passage","lines":["겨울이 끝없이 길어. 눈이 허리까지 쌓였어.","바늘잎나무 숲에서 벤 나무를 실은 트럭이 지나가.","짧은 여름에는 감자밭이 초록으로 물든대."],"title":"여행 엽서 ㉰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#20','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C6',3,'mc','auto','열대 기후와 고산 기후가 둘 다 적도 주변에 나타날 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X14','SO6-2-u1-X09']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"열대 기후와 고산 기후가 둘 다 적도 주변에 나타날 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 적도 주변이라도 낮은 곳은 덥고 높은 곳은 서늘하기 때문에","correct":true},{"t":"적도 주변은 해마다 기후가 바뀌기 때문에","mis":"SO6-2-u1-X08"},{"t":"두 기후는 같은 기후이기 때문에","mis":"SO6-2-u1-X14"},{"t":"적도 주변에는 산이 없기 때문에","mis":"SO6-2-u1-X09"}],"explanation":["기후는 위도만으로 정해지지 않아요.","해발 고도가 높으면 서늘해요.","그래서 적도 주변에도 고산 기후가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#21','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C10',3,'mc','auto','기후와 생활 모습 조사에서 「디지털 영상 지도에 표시하기」 바로 다음에 할 일은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"기후와 생활 모습 조사에서 「디지털 영상 지도에 표시하기」 바로 다음에 할 일은 어느 것인가요?","options":[{"t":"디지털 영상 지도를 공유하기","correct":true},{"t":"주제 정하기","mis":"SO6-2-u1-X17"},{"t":"인터넷으로 조사하기","mis":"SO6-2-u1-X17"},{"t":"판매 계획 세우기","mis":"SO6-2-u1-X17"}],"explanation":["주제 → 조사 → 표시 → 공유예요.","표시한 뒤 친구들과 나눠요.","여러 곳의 생활을 한눈에 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#22','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',3,'mc','auto','경관이 아름다운 지형이 그곳 사람들의 생활에 주는 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"경관이 아름다운 지형이 그곳 사람들의 생활에 주는 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여행객이 찾아와 안내·숙소·가게 같은 일이 생긴다","correct":true},{"t":"사람들이 모두 그곳을 떠난다","mis":"SO6-2-u1-X02"},{"t":"지형 경관은 생활과 관계가 없다","mis":"SO6-2-u1-X02"},{"t":"농사를 전혀 지을 수 없게 된다","mis":"SO6-2-u1-X02"}],"explanation":["아름다운 경관은 관광지가 돼요.","관광과 관련된 일이 생겨요.","지형 경관은 생활에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#23','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',4,'mc','auto','단원 「세계의 자연환경」에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X02','SO6-2-u1-X15']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"mc","stem":"단원 「세계의 자연환경」에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"세계에는 다양한 지형과 기후가 있고, 사람들은 그 자연환경에 적응하고 이를 이용·극복하며 다양한 모습으로 살아간다","correct":true},{"t":"세계의 지형과 기후는 어디나 같아 생활 모습도 같다","mis":"SO6-2-u1-X01"},{"t":"자연환경은 사람들의 생활과 관계가 없다","mis":"SO6-2-u1-X02"},{"t":"사람들은 모두 같은 집에 살고 같은 일을 한다","mis":"SO6-2-u1-X15"}],"explanation":["지형 — 산지·하천·해안·사막이에요.","기후 — 열대·건조·온대·냉대·한대·고산이에요.","자연환경이 생활에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#24','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',4,'essay','teacher','여행 엽서 ㉱의 곳은 어느 지형이며 사람들이 무엇을 하고 있는지 쓰고, 이 지형에서 볼 수 있는 다른 생활 모습을 두 가지 더 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉱의 곳은 어느 지형이며 사람들이 무엇을 하고 있는지 쓰고, 이 지형에서 볼 수 있는 다른 생활 모습을 두 가지 더 쓰세요.","answer_guide":{"answer":"예: ㉱는 바다와 땅이 만나는 해안이다. 물이 빠지면 드러나는 넓은 갯벌에 바닷물을 가두어 햇볕에 말려 소금을 만드는 염전 일을 하고 있다. 해안에서는 이 밖에도 배가 드나들기 좋은 곳에 항구를 만들고, 물고기나 조개를 기르는 양식업을 한다.","scoring_points":["해안 지형임을 밝혔는가","염전에서 소금을 만드는 일임을 썼는가","다른 해안 생활을 두 가지 바르게 썼는가"]},"explanation":["바다와 땅이 만나면 해안이에요.","넓은 갯벌 → 염전이에요.","항구·양식업·관광지도 있어요."],"asset":{"type":"passage","lines":["바다와 땅이 만나는 곳이야. 물이 빠지면 넓은 갯벌이 드러나.","네모난 칸마다 바닷물을 가두어 햇볕에 말려.","하얀 알갱이를 긁어모으는 사람들이 보여."],"title":"여행 엽서 ㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_b#25','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C8',4,'essay','teacher','여행 엽서 ㉳의 곳과 우리나라는 둘 다 온대 기후인데 많이 기르는 작물이 달라요. 두 곳의 기후 특징과 작물을 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C8","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉳의 곳과 우리나라는 둘 다 온대 기후인데 많이 기르는 작물이 달라요. 두 곳의 기후 특징과 작물을 견주어 쓰세요.","answer_guide":{"answer":"예: ㉳의 곳은 지중해 주변처럼 여름이 덥고 건조하며 겨울이 따뜻하고 비가 많아, 건조한 여름을 잘 견디는 올리브와 포도를 많이 기른다. 우리나라는 여름에 덥고 비가 많이 내리며 겨울은 춥고 건조해서, 여름에 물이 많이 필요한 벼농사를 많이 짓는다.","scoring_points":["㉳의 기후 특징과 작물을 썼는가","우리나라의 기후 특징과 작물을 썼는가","비가 오는 때의 차이로 작물 차이를 설명했는가"]},"explanation":["같은 온대도 비가 오는 때가 달라요.","지중해 — 여름 건조, 우리나라 — 여름 비예요.","기후가 작물을 정해요."],"asset":{"type":"passage","lines":["여름은 햇볕이 쨍쨍하고 비가 거의 없었어.","언덕마다 올리브 나무와 포도밭이 펼쳐져 있어.","이곳은 겨울이 따뜻하고 비가 많이 온대."],"title":"여행 엽서 ㉳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#1','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C1',1,'mc','auto','강물이 흐르며 계곡·평야·폭포를 만드는 지형의 갈래는 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"강물이 흐르며 계곡·평야·폭포를 만드는 지형의 갈래는 어느 것인가요?","options":[{"t":"하천","correct":true},{"t":"사막","mis":"SO6-2-u1-X03"},{"t":"해안","mis":"SO6-2-u1-X03"},{"t":"산지","mis":"SO6-2-u1-X03"}],"explanation":["강이 흐르는 곳이 하천이에요.","계곡·평야·폭포가 나타나요.","나일강·아마존강이 유명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#2','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',1,'mc','auto','산지 지역에서 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X06','SO6-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지역에서 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"아름다운 경관을 이용한 스키장과 휴양림","correct":true},{"t":"배 위에서 물건을 사고파는 시장","mis":"SO6-2-u1-X03"},{"t":"갯벌의 염전","mis":"SO6-2-u1-X06"},{"t":"넓은 평야의 비행기 농사","mis":"SO6-2-u1-X05"}],"explanation":["산지의 경관은 관광지가 돼요.","스키장·휴양림이 그 예예요.","계단식 농사·광업도 산지의 생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#3','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',1,'ox','auto','「오늘 비가 와서 우산을 챙겼다.」는 기후에 대한 말이에요.',ARRAY['SO6-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"ox","stem":"「오늘 비가 와서 우산을 챙겼다.」는 기후에 대한 말이에요.","answer":"X","reason_options":[{"t":"하루의 대기 상태를 말한 것이므로 날씨에 대한 말이기 때문에","correct":true},{"t":"비는 언제나 기후를 뜻하기 때문에","mis":"SO6-2-u1-X08"}],"mis":"SO6-2-u1-X08","explanation":["「오늘」은 짧은 기간이에요.","짧은 기간의 대기 상태는 날씨예요.","기후는 여러 해의 평균이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#4','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',1,'mc','auto','우리나라에서 나타나는 기후를 바르게 고른 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"우리나라에서 나타나는 기후를 바르게 고른 것은 어느 것인가요?","options":[{"t":"온대 기후와 냉대 기후","correct":true},{"t":"열대 기후와 건조 기후","mis":"SO6-2-u1-X10"},{"t":"한대 기후와 고산 기후","mis":"SO6-2-u1-X10"},{"t":"건조 기후와 한대 기후","mis":"SO6-2-u1-X10"}],"explanation":["우리나라는 중위도에 있어요.","사계절이 뚜렷해요.","온대와 냉대 기후가 나타나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#5','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',1,'mc','auto','기둥을 세워 바닥을 땅에서 띄운 고상 가옥은 주로 어느 기후 지역의 집인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"mc","stem":"기둥을 세워 바닥을 땅에서 띄운 고상 가옥은 주로 어느 기후 지역의 집인가요?","options":[{"t":"열대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X12"},{"t":"냉대 기후","mis":"SO6-2-u1-X12"},{"t":"한대 기후","mis":"SO6-2-u1-X12"}],"explanation":["열대 기후 지역은 덥고 습해요.","바닥을 띄워 습기와 물을 피해요.","창을 크게 해 바람이 통하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#6','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',1,'ox','auto','서부 유럽에서는 밀을 많이 기르고 낙농업이 발달했어요.',ARRAY['SO6-2-u1-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"ox","stem":"서부 유럽에서는 밀을 많이 기르고 낙농업이 발달했어요.","answer":"O","reason_options":[{"t":"여름이 서늘하고 비가 고르게 오는 온대 기후가 밀과 목초 기르기에 알맞기 때문에","correct":true},{"t":"서부 유럽은 사막이 넓기 때문에","mis":"SO6-2-u1-X13"}],"mis":"SO6-2-u1-X13","explanation":["서부 유럽은 온대 기후예요.","비가 고르게 와요.","밀과 낙농업이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#7','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',1,'mc','auto','한대 기후 지역 사람들이 기르며 옮겨 다니는 동물은 어느 것인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"mc","stem":"한대 기후 지역 사람들이 기르며 옮겨 다니는 동물은 어느 것인가요?","options":[{"t":"순록","correct":true},{"t":"알파카","mis":"SO6-2-u1-X14"},{"t":"낙타","mis":"SO6-2-u1-X14"},{"t":"젖소","mis":"SO6-2-u1-X14"}],"explanation":["짧은 여름에 이끼가 자라요.","순록이 이끼를 먹어요.","사람들은 순록과 함께 옮겨 다녀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#8','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C10',1,'mc','auto','기후와 생활 모습을 조사한 뒤 조사한 곳을 표시하고 친구들과 나누는 데 쓰는 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"기후와 생활 모습을 조사한 뒤 조사한 곳을 표시하고 친구들과 나누는 데 쓰는 것은 어느 것인가요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"기후 그래프만 그린 공책","mis":"SO6-2-u1-X17"},{"t":"국어사전","mis":"SO6-2-u1-X17"},{"t":"달력","mis":"SO6-2-u1-X17"}],"explanation":["조사한 곳을 지도에 표시해요.","디지털 영상 지도로 공유해요.","여러 기후의 생활을 한눈에 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#9','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',2,'mc','auto','여행 엽서 ㉰의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X14','SO6-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉰의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"한대 기후","mis":"SO6-2-u1-X14"},{"t":"열대 기후","mis":"SO6-2-u1-X11"}],"explanation":["겨울이 길고 눈이 많이 와요.","침엽수림의 목재, 여름의 감자밭이 있어요.","냉대 기후의 생활이에요."],"asset":{"type":"passage","lines":["겨울이 끝없이 길어. 눈이 허리까지 쌓였어.","바늘잎나무 숲에서 벤 나무를 실은 트럭이 지나가.","짧은 여름에는 감자밭이 초록으로 물든대."],"title":"여행 엽서 ㉰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#10','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',2,'mc','auto','여행 엽서 ㉵의 곳에 나타나는 기후와 생활을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X11','SO6-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉵의 곳에 나타나는 기후와 생활을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"한대 기후 — 순록 유목과 오로라 관광","correct":true},{"t":"고산 기후 — 알파카 기르기","mis":"SO6-2-u1-X14"},{"t":"열대 기후 — 생태 관광","mis":"SO6-2-u1-X11"},{"t":"냉대 기후 — 올리브 재배","mis":"SO6-2-u1-X13"}],"explanation":["극지방 가까운 곳이에요.","오로라와 순록이 보여요.","한대 기후의 생활이에요."],"asset":{"type":"passage","lines":["극지방 가까운 곳이야. 밤하늘에 초록빛 오로라가 춤을 춰.","사람들은 이끼가 자라는 땅을 따라 순록 떼를 몰고 다녀.","오로라를 보러 온 여행객도 많아."],"title":"여행 엽서 ㉵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#11','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',2,'mc','auto','관광의 긍정적인 영향으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"관광의 긍정적인 영향으로 알맞은 것은 어느 것인가요?","options":[{"t":"관광객을 맞는 일자리가 생겨 소득이 늘어난다","correct":true},{"t":"바닷물이 오염된다","mis":"SO6-2-u1-X07"},{"t":"쓰레기가 쌓인다","mis":"SO6-2-u1-X07"},{"t":"마을이 시끄러워진다","mis":"SO6-2-u1-X07"}],"explanation":["관광은 좋은 점도 있어요.","일자리와 소득이 늘어요.","오염·쓰레기는 부정적인 영향이에요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#12','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',2,'ox','auto','적도 주변은 어디든 일 년 내내 더운 기후만 나타나요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"적도 주변은 어디든 일 년 내내 더운 기후만 나타나요.","answer":"X","reason_options":[{"t":"적도 주변이라도 해발 고도가 높은 곳에는 서늘한 고산 기후가 나타나기 때문에","correct":true},{"t":"적도 주변은 모두 바닷가이기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["적도 주변의 낮은 곳은 더워요.","높은 산지는 서늘한 고산 기후예요.","키토(에콰도르)가 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#13','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',2,'match','auto','기후와 그곳의 산업이나 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"match","stem":"기후와 그곳의 산업이나 일을 알맞게 이으세요.","pairs":[{"l":"한대 기후","r":"오로라·빙하 관광과 극지 연구"},{"l":"냉대 기후","r":"목재와 펄프 생산"},{"l":"열대 기후","r":"사파리 같은 생태 관광"}],"mis":"SO6-2-u1-X15","explanation":["기후마다 발달한 일이 달라요.","한대 — 관광·연구·자원 개발이에요.","냉대 — 숲, 열대 — 생태 관광이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#14','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역에는 열대 우림만 있고 초원은 없어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역에는 열대 우림만 있고 초원은 없어요.","answer":"X","reason_options":[{"t":"건기와 우기가 번갈아 나타나는 곳에는 초원이 넓게 펼쳐지기 때문에","correct":true},{"t":"열대 기후는 일 년 내내 비가 똑같이 오기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["열대 기후에도 경관이 여러 가지예요.","비가 늘 많으면 열대 우림이에요.","건기·우기가 번갈아 오면 초원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#15','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',2,'mc','auto','화산 지역 사람들이 화산을 이용해 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03','SO6-2-u1-X06','SO6-2-u1-X04']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"화산 지역 사람들이 화산을 이용해 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"화산을 보러 온 관광객에게 여행을 안내한다","correct":true},{"t":"화산에서 물고기를 잡는다","mis":"SO6-2-u1-X03"},{"t":"화산 꼭대기에 항구를 짓는다","mis":"SO6-2-u1-X06"},{"t":"화산 위에서 벼농사를 짓는다","mis":"SO6-2-u1-X04"}],"explanation":["화산은 볼거리가 되는 경관이에요.","관광객이 찾아와요.","사람들은 여행 안내와 물건 팔기를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#16','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C10',2,'mc','auto','겨울이 길고 눈과 얼음이 많은 곳에 팔 신발에 넣으면 좋은 기능은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"겨울이 길고 눈과 얼음이 많은 곳에 팔 신발에 넣으면 좋은 기능은 어느 것인가요?","options":[{"t":"미끄러지지 않는 스파이크와 발을 데우는 열선","correct":true},{"t":"바람이 잘 통하는 그물 구멍","mis":"SO6-2-u1-X16"},{"t":"물에 뜨는 고무 바닥","mis":"SO6-2-u1-X16"},{"t":"모래를 털어 내는 솔","mis":"SO6-2-u1-X16"}],"explanation":["냉대·한대는 몹시 추워요.","눈과 얼음 위는 미끄러워요.","스파이크와 열선이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#17','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',3,'error','auto','산지 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C2","difficulty":3,"kind":"error","stem":"산지 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「산지는 모두 뾰족하고 가팔라서 평평한 곳은 하나도 없어.」","correct":true,"mis_target":"SO6-2-u1-X04"},{"t":"수빈 — 「고원처럼 넓고 평평한 산지도 있어.」","mis":"SO6-2-u1-X04"},{"t":"지후 — 「화산은 정상이 움푹 파이기도 해.」","mis":"SO6-2-u1-X04"}],"explanation":["산지는 대체로 경사가 급해요.","하지만 고원처럼 평평한 곳도 있어요.","수빈과 지후는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#18','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',3,'error','auto','한대·고산 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"한대·고산 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「고산 기후 지역 사람들은 순록을 기르며 오로라 관광을 해.」","correct":true,"mis_target":"SO6-2-u1-X14"},{"t":"민호 — 「고산 기후 지역 사람들은 알파카와 라마를 길러.」","mis":"SO6-2-u1-X14"},{"t":"지안 — 「한대 기후 지역에서는 극지방 연구가 활발해.」","mis":"SO6-2-u1-X14"}],"explanation":["순록과 오로라는 한대 기후 지역이에요.","고산 기후는 알파카·라마예요.","민호와 지안은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#19','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C7',3,'mc','auto','여행 엽서 ㉲의 곳 사람들이 둥근 천막집에서 사는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X14','SO6-2-u1-X03']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉲의 곳 사람들이 둥근 천막집에서 사는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 조금 오는 초원에서 물과 풀을 찾아 가축과 함께 옮겨 다니기 때문에","correct":true},{"t":"비가 많아 집이 자주 잠기기 때문에","mis":"SO6-2-u1-X11"},{"t":"눈과 얼음 위에 집을 지어야 하기 때문에","mis":"SO6-2-u1-X14"},{"t":"바닷가라 배를 타고 다니기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["건조 기후의 초원이에요.","물과 풀을 찾아 옮겨 다녀요.","접고 펴기 쉬운 이동식 가옥이 알맞아요."],"asset":{"type":"passage","lines":["비가 아주 조금 와서 풀이 낮게 자란 넓은 땅이야.","사람들은 양 떼를 몰고 물과 풀을 찾아 옮겨 다녀.","둥근 천막집을 하루 만에 접었다 폈다 한대."],"title":"여행 엽서 ㉲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#20','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',3,'mc','auto','온대 기후와 냉대 기후를 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C8","difficulty":3,"kind":"mc","stem":"온대 기후와 냉대 기후를 바르게 견준 것은 어느 것인가요?","options":[{"t":"둘 다 사계절이 있지만, 냉대는 겨울이 여름보다 길고 몹시 춥다","correct":true},{"t":"온대는 사계절이 없고, 냉대는 사계절이 있다","mis":"SO6-2-u1-X13"},{"t":"온대는 겨울이 길고, 냉대는 여름이 길다","mis":"SO6-2-u1-X13"},{"t":"둘 다 일 년 내내 기온 변화가 거의 없다","mis":"SO6-2-u1-X11"}],"explanation":["둘 다 사계절이 있어요.","냉대는 겨울이 길고 몹시 추워요.","온대는 사계절이 비교적 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#21','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C1',3,'mc','auto','지형 경관 소개 자료를 만드는 차례에서 「소개 자료 만들기」 바로 앞에 할 일은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"mc","stem":"지형 경관 소개 자료를 만드는 차례에서 「소개 자료 만들기」 바로 앞에 할 일은 어느 것인가요?","options":[{"t":"조사 내용 정리하기","correct":true},{"t":"발표하기","mis":"SO6-2-u1-X17"},{"t":"기후 띠 쌓기","mis":"SO6-2-u1-X17"},{"t":"상품 그리기","mis":"SO6-2-u1-X17"}],"explanation":["조사 → 정리 → 소개 자료 → 발표예요.","정리한 것이 소개 자료가 돼요.","그다음 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#22','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',3,'ox','auto','해안 마을 사람들이 관광객에게 쓰레기를 되가져가게 하는 것은 관광의 부정적인 영향을 줄이려는 노력이에요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"ox","stem":"해안 마을 사람들이 관광객에게 쓰레기를 되가져가게 하는 것은 관광의 부정적인 영향을 줄이려는 노력이에요.","answer":"O","reason_options":[{"t":"관광의 좋은 점은 살리면서 쓰레기와 오염을 줄이려는 방법이기 때문에","correct":true},{"t":"관광객을 모두 쫓아내려는 방법이기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광의 부정적인 영향도 줄일 수 있어요.","쓰레기를 되가져가게 해요.","좋은 점과 걱정을 함께 다뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#23','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C10',4,'mc','auto','여행 엽서 ㉲의 곳에 팔 상품으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"mc","stem":"여행 엽서 ㉲의 곳에 팔 상품으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가볍게 접어 옮길 수 있는 물통과 천막 고정 장비","correct":true},{"t":"바닥에 스파이크가 달린 방한 신발","mis":"SO6-2-u1-X16"},{"t":"열대 우림용 해충 퇴치기","mis":"SO6-2-u1-X16"},{"t":"수상 시장용 작은 배","mis":"SO6-2-u1-X16"}],"explanation":["㉲는 건조 기후의 초원이에요.","사람들은 물과 풀을 찾아 옮겨 다녀요.","옮기기 쉽고 물을 담는 상품이 알맞아요."],"asset":{"type":"passage","lines":["비가 아주 조금 와서 풀이 낮게 자란 넓은 땅이야.","사람들은 양 떼를 몰고 물과 풀을 찾아 옮겨 다녀.","둥근 천막집을 하루 만에 접었다 폈다 한대."],"title":"여행 엽서 ㉲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#24','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C10',4,'essay','teacher','여행 엽서 ㉰의 곳에 팔 상품을 하나 구상해 보세요. 기후의 특징, 판매 동기, 상품의 특징을 차례로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C10","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉰의 곳에 팔 상품을 하나 구상해 보세요. 기후의 특징, 판매 동기, 상품의 특징을 차례로 쓰세요.","answer_guide":{"answer":"예: 기후의 특징 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다(냉대 기후). 판매 동기 — 눈이 허리까지 쌓여 겨울에 밖에서 다니기 힘들다. 상품 — 눈길용 전동 썰매 수레. 특징 — 눈 위를 미끄러지는 넓은 날, 손잡이 열선, 짐을 실을 수 있는 바구니.","scoring_points":["냉대 기후의 특징을 바르게 썼는가","기후에서 오는 불편을 판매 동기로 썼는가","기후 특징을 상품 기능에 담았는가"]},"explanation":["기후 특징 → 불편 → 기능이에요.","㉰는 냉대 기후예요.","실제로 만들 수 있는지도 생각해요."],"asset":{"type":"passage","lines":["겨울이 끝없이 길어. 눈이 허리까지 쌓였어.","바늘잎나무 숲에서 벤 나무를 실은 트럭이 지나가.","짧은 여름에는 감자밭이 초록으로 물든대."],"title":"여행 엽서 ㉰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_c#25','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C2',4,'essay','teacher','산지·하천·해안 가운데 두 지형을 골라, 각 지형에서 사람들이 지형을 이용해 살아가는 모습을 하나씩 세계의 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C2","difficulty":4,"kind":"essay","stem":"산지·하천·해안 가운데 두 지형을 골라, 각 지형에서 사람들이 지형을 이용해 살아가는 모습을 하나씩 세계의 예와 함께 쓰세요.","answer_guide":{"answer":"예: 산지 — 스위스의 알프스산맥에서는 아름다운 지형 경관을 이용해 관광지가 발달했다. 하천 — 타이의 짜오프라야강에서는 배 위에서 물건을 사고파는 수상 시장이 열린다.","scoring_points":["두 지형을 골랐는가","지형마다 이용하는 생활 모습을 썼는가","세계의 알맞은 예를 들었는가"]},"explanation":["지형마다 이용 방법이 달라요.","세계의 예와 이어요.","지형이 생활에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#1','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C1',1,'ox','auto','세계의 다양한 지형은 저마다 독특한 경관 특징을 가지고 있어요.',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"ox","stem":"세계의 다양한 지형은 저마다 독특한 경관 특징을 가지고 있어요.","answer":"O","reason_options":[{"t":"산지·하천·해안·사막마다, 같은 갈래 안에서도 경관이 서로 다르기 때문에","correct":true},{"t":"세계의 지형은 모두 같은 모습이기 때문에","mis":"SO6-2-u1-X01"}],"mis":"SO6-2-u1-X01","explanation":["지형마다 경관이 달라요.","같은 갈래 안에서도 특징이 갈려요.","피오르·폭포·화산이 모두 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#2','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',1,'mc','auto','지하자원이 풍부한 산지에서 발달하기 쉬운 산업은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"지하자원이 풍부한 산지에서 발달하기 쉬운 산업은 어느 것인가요?","options":[{"t":"광업","correct":true},{"t":"양식업","mis":"SO6-2-u1-X06"},{"t":"수력 발전","mis":"SO6-2-u1-X05"},{"t":"수상 시장","mis":"SO6-2-u1-X05"}],"explanation":["땅속에 자원이 많으면 캐내요.","그 산업이 광업이에요.","칠레 추키카마타는 구리 광업이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#3','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',1,'mc','auto','세계의 기후 구분에 들지 않는 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계의 기후 구분에 들지 않는 것은 어느 것인가요?","options":[{"t":"바다 기후","correct":true},{"t":"냉대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X10"},{"t":"건조 기후","mis":"SO6-2-u1-X10"}],"explanation":["기후는 열대·건조·온대·냉대·한대·고산으로 나눠요.","「바다 기후」는 이 구분에 없어요.","여섯 기후를 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#4','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',1,'ox','auto','냉대 기후는 주로 북반구에 나타나요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"ox","stem":"냉대 기후는 주로 북반구에 나타나요.","answer":"O","reason_options":[{"t":"남반구에는 냉대 기후가 나타날 만한 중·고위도의 넓은 땅이 적기 때문에","correct":true},{"t":"냉대 기후는 적도에서만 나타나기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["기후 띠는 적도를 기준으로 남북이 비슷해요.","하지만 냉대 기후는 주로 북반구에 나타나요.","그래서 남쪽 띠는 대략적인 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#5','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',1,'mc','auto','벽이 두껍고 창이 작은 흙벽돌 집은 주로 어느 기후 지역의 집인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"mc","stem":"벽이 두껍고 창이 작은 흙벽돌 집은 주로 어느 기후 지역의 집인가요?","options":[{"t":"건조 기후의 사막","correct":true},{"t":"열대 기후의 우림","mis":"SO6-2-u1-X12"},{"t":"온대 기후의 서부 유럽","mis":"SO6-2-u1-X12"},{"t":"고산 기후의 높은 산지","mis":"SO6-2-u1-X12"}],"explanation":["사막은 햇볕이 강하고 모래바람이 불어요.","두꺼운 벽과 작은 창이 이를 막아요.","흙벽돌로 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#6','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C8',1,'sa','auto','냉대 기후 지역에 넓게 발달한, 바늘처럼 뾰족한 잎을 가진 나무의 숲을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u1-C8","difficulty":1,"kind":"sa","stem":"냉대 기후 지역에 넓게 발달한, 바늘처럼 뾰족한 잎을 가진 나무의 숲을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["침엽수림"],"explanation":["냉대 기후 지역에 넓게 자라요.","추위에 강한 바늘잎나무 숲이에요.","목재와 펄프를 얻어요."],"mis":"SO6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#7','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C9',1,'ox','auto','고산 기후는 해발 고도가 높은 지역에 나타나요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":1,"kind":"ox","stem":"고산 기후는 해발 고도가 높은 지역에 나타나요.","answer":"O","reason_options":[{"t":"높이 올라갈수록 기온이 낮아져 서늘한 기후가 나타나기 때문에","correct":true},{"t":"고산 기후는 극지방에만 나타나기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["높이 오르면 서늘해져요.","해발 고도가 높은 곳에 고산 기후가 나타나요.","적도 주변에도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#8','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',1,'mc','auto','콩고강 주변 사람들에게 알맞은 상품 아이디어는 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"콩고강 주변 사람들에게 알맞은 상품 아이디어는 어느 것인가요?","options":[{"t":"튼튼한 어망","correct":true},{"t":"방한용 안전 신발","mis":"SO6-2-u1-X16"},{"t":"만능 등산 장비","mis":"SO6-2-u1-X16"},{"t":"모래바람 가리개","mis":"SO6-2-u1-X16"}],"explanation":["콩고강에서는 물고기를 잡아요.","튼튼한 어망이 쓸모 있어요.","상품은 그곳의 자연환경에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#9','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',2,'mc','auto','여행 엽서 ㉲의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉲의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"건조 기후","correct":true},{"t":"열대 기후","mis":"SO6-2-u1-X11"},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"한대 기후","mis":"SO6-2-u1-X14"}],"explanation":["비가 아주 조금 와 풀이 낮게 자라요.","양 떼를 몰고 옮겨 다니며 천막집에서 살아요.","건조 기후 초원의 유목 생활이에요."],"asset":{"type":"passage","lines":["비가 아주 조금 와서 풀이 낮게 자란 넓은 땅이야.","사람들은 양 떼를 몰고 물과 풀을 찾아 옮겨 다녀.","둥근 천막집을 하루 만에 접었다 폈다 한대."],"title":"여행 엽서 ㉲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#10','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C8',2,'mc','auto','여행 엽서 ㉳의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X11']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉳의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"지중해 주변의 온대 기후","correct":true},{"t":"서부 유럽의 온대 기후","mis":"SO6-2-u1-X13"},{"t":"냉대 기후","mis":"SO6-2-u1-X13"},{"t":"건조 기후의 사막","mis":"SO6-2-u1-X11"}],"explanation":["여름이 덥고 건조해요.","겨울은 따뜻하고 비가 많아요.","올리브와 포도 — 지중해 주변이에요."],"asset":{"type":"passage","lines":["여름은 햇볕이 쨍쨍하고 비가 거의 없었어.","언덕마다 올리브 나무와 포도밭이 펼쳐져 있어.","이곳은 겨울이 따뜻하고 비가 많이 온대."],"title":"여행 엽서 ㉳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#11','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',2,'ox','auto','섬을 쉬게 하면 오염만 줄고 일자리와 소득은 그대로예요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"섬을 쉬게 하면 오염만 줄고 일자리와 소득은 그대로예요.","answer":"X","reason_options":[{"t":"관광객이 줄면 오염과 함께 일자리와 소득도 줄기 때문에","correct":true},{"t":"섬을 쉬게 하면 관광객이 더 늘기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광의 두 영향은 함께 움직여요.","관광객이 줄면 둘 다 줄어요.","그래서 신중하게 결정해요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#12','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',2,'mc','auto','적도를 기준으로 남반구와 북반구의 기후 분포가 비슷하게 나타나는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X10']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도를 기준으로 남반구와 북반구의 기후 분포가 비슷하게 나타나는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 위도에 따라 달라지기 때문에","correct":true},{"t":"남반구와 북반구는 언제나 같은 날씨이기 때문에","mis":"SO6-2-u1-X08"},{"t":"기후가 나라 이름으로 정해지기 때문에","mis":"SO6-2-u1-X10"},{"t":"남반구에는 기후가 없기 때문에","mis":"SO6-2-u1-X10"}],"explanation":["같은 위도는 비슷한 햇볕을 받아요.","그래서 비슷한 기후가 나타나요.","적도를 기준으로 거울처럼 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#13','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',2,'match','auto','건조 기후의 두 곳과 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"match","stem":"건조 기후의 두 곳과 생활 모습을 알맞게 이으세요.","pairs":[{"l":"사막","r":"오아시스 주변에서 농사짓는다"},{"l":"초원","r":"가축을 데리고 옮겨 다닌다"}],"mis":"SO6-2-u1-X12","explanation":["건조 기후에는 사막과 초원이 있어요.","사막 — 오아시스 농사예요.","초원 — 유목과 이동식 가옥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#14','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',2,'ox','auto','같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타나요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타나요.","answer":"O","reason_options":[{"t":"같은 기후 안에서도 지형과 비가 오는 모양, 사람들의 선택이 다르기 때문에","correct":true},{"t":"같은 기후면 생활도 모두 같기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 기후 칸에 여러 핀이 설 수 있어요.","온대 칸에는 핀이 셋 모였어요.","생활은 여러 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#15','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',2,'ox','auto','산지는 해발 고도가 높고 경사가 급해 사람들이 전혀 이용하지 못해요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"ox","stem":"산지는 해발 고도가 높고 경사가 급해 사람들이 전혀 이용하지 못해요.","answer":"X","reason_options":[{"t":"사람들은 산지에서 농사·목축·광업·관광을 하며 지형을 이용하기 때문에","correct":true},{"t":"산지에는 사람이 갈 수 없기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["산지에서도 사람들은 살아가요.","지형을 이용하는 방법이 여러 가지예요.","계단식 농사·가축·광업·관광이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#16','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',2,'ox','auto','판매할 곳이 바뀌면 상품에 넣을 알맞은 기능도 바뀔 수 있어요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"판매할 곳이 바뀌면 상품에 넣을 알맞은 기능도 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"곳마다 지형과 기후가 달라 사람들이 겪는 불편이 다르기 때문에","correct":true},{"t":"상품은 어느 곳에서나 같은 기능이면 충분하기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["자연환경이 다르면 불편도 달라요.","그래서 맞는 기능도 달라요.","같은 특징이 있으면 같은 기능을 쓰기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#17','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C1',3,'error','auto','같은 갈래의 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X02']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"같은 갈래의 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「같은 갈래의 지형이면 경관 특징도 모두 같아.」","correct":true,"mis_target":"SO6-2-u1-X01"},{"t":"채원 — 「같은 산지라도 화산과 평평한 산은 모습이 달라.」","mis":"SO6-2-u1-X01"},{"t":"지민 — 「지형 경관은 그곳 사람들의 생활에 영향을 줘.」","mis":"SO6-2-u1-X02"}],"explanation":["같은 갈래 안에서도 특징이 갈려요.","마우나로아와 호라이마산은 둘 다 산지지만 달라요.","채원과 지민은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#18','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',3,'error','auto','열대·건조 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"열대·건조 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「건조 기후는 일 년 내내 기온 변화가 거의 없어.」","correct":true,"mis_target":"SO6-2-u1-X11"},{"t":"여울 — 「건조 기후는 낮과 밤의 기온 차이가 커.」","mis":"SO6-2-u1-X11"},{"t":"이준 — 「열대 기후는 일 년 내내 기온이 높아.」","mis":"SO6-2-u1-X11"}],"explanation":["기온 변화가 거의 없는 것은 열대 기후예요.","건조 기후는 낮밤의 기온 차이가 커요.","여울과 이준은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#19','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',3,'mc','auto','여행 엽서 ㉮의 집이 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉮의 집이 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"덥고 비가 자주 와 땅의 습기와 물을 피하려고","correct":true},{"t":"모래바람을 막으려고","mis":"SO6-2-u1-X12"},{"t":"추운 겨울에 땅의 냉기를 막으려고","mis":"SO6-2-u1-X12"},{"t":"물과 풀을 찾아 옮기기 쉽게 하려고","mis":"SO6-2-u1-X12"}],"explanation":["일 년 내내 덥고 소나기가 와요.","땅이 늘 축축해요.","바닥을 띄운 고상 가옥으로 피해요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#20','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',3,'mc','auto','열대 기후와 건조 기후의 집이 다른 까닭을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X11']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"mc","stem":"열대 기후와 건조 기후의 집이 다른 까닭을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"열대는 바람을 들이고 습기를 피해야 하고, 사막은 햇볕과 모래바람을 막아야 하기 때문에","correct":true},{"t":"두 지역 사람들의 좋아하는 색이 달라서","mis":"SO6-2-u1-X12"},{"t":"두 지역의 기온과 강수량이 같아서","mis":"SO6-2-u1-X11"},{"t":"집을 아무렇게나 지어서","mis":"SO6-2-u1-X12"}],"explanation":["기후가 다르면 막을 것과 들일 것이 달라요.","열대 — 큰 창, 띄운 바닥이에요.","사막 — 두꺼운 벽, 작은 창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#21','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',3,'ox','auto','상품 판매 계획은 나라를 정한 뒤 지형과 기후를 조사하고, 아이디어를 이야기해 계획을 세워요.',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"ox","stem":"상품 판매 계획은 나라를 정한 뒤 지형과 기후를 조사하고, 아이디어를 이야기해 계획을 세워요.","answer":"O","reason_options":[{"t":"자연환경을 먼저 알아야 그곳에 필요한 상품을 떠올릴 수 있기 때문에","correct":true},{"t":"상품부터 정하고 나라는 마지막에 정하기 때문에","mis":"SO6-2-u1-X17"}],"mis":"SO6-2-u1-X17","explanation":["나라를 먼저 정해요.","자연환경을 조사해요.","그 위에서 아이디어를 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#22','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',3,'error','auto','관광이 늘어난 섬을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"관광이 늘어난 섬을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「일자리가 늘었으니 바다가 더러워져도 괜찮아.」","correct":true,"mis_target":"SO6-2-u1-X07"},{"t":"예나 — 「일자리도 늘었지만 쓰레기도 늘었어.」","mis":"SO6-2-u1-X07"},{"t":"도현 — 「두 영향을 함께 따져 정해야 해.」","mis":"SO6-2-u1-X07"}],"explanation":["한쪽 영향만 보면 다른 쪽 문제가 커져요.","관광에는 두 영향이 함께 있어요.","예나와 도현은 바르게 말했어요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#23','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C3',4,'mc','auto','여행 엽서 ㉴의 곳과 같은 지형에서 볼 수 있는 생활 모습을 모두 바르게 고른 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"mc","stem":"여행 엽서 ㉴의 곳과 같은 지형에서 볼 수 있는 생활 모습을 모두 바르게 고른 것은 어느 것인가요?","options":[{"t":"수상 시장 · 평야의 큰 규모 농사 · 수력 발전 · 어업","correct":true},{"t":"수상 시장 · 염전 · 항구","mis":"SO6-2-u1-X06"},{"t":"계단식 농사 · 광업 · 스키장","mis":"SO6-2-u1-X03"},{"t":"오아시스 농사 · 유목","mis":"SO6-2-u1-X03"}],"explanation":["㉴는 하천 지형이에요.","하천은 물길·평야·물의 힘·물고기를 줘요.","염전·항구는 해안, 계단식 농사는 산지예요."],"asset":{"type":"passage","lines":["강을 따라 내려가니 배들이 물 위에 모여 있었어.","배 위에서 과일과 채소를 사고팔고 있었어.","강가에는 강물이 날라 온 흙으로 넓은 들이 펼쳐져."],"title":"여행 엽서 ㉴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#24','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',4,'essay','teacher','여행 엽서 ㉮와 ㉲의 곳은 기후가 서로 달라요. 두 곳의 기후 이름과 특징을 쓰고, 그 기후에 맞춘 집 모습을 견주어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉮와 ㉲의 곳은 기후가 서로 달라요. 두 곳의 기후 이름과 특징을 쓰고, 그 기후에 맞춘 집 모습을 견주어 쓰세요.","answer_guide":{"answer":"예: ㉮는 일 년 내내 덥고 비가 자주 오는 열대 기후이고, ㉲는 비가 아주 조금 와서 풀이 낮게 자라는 건조 기후의 초원이다. ㉮에서는 땅의 습기를 피하고 바람이 통하게 바닥을 땅에서 띄운 집을 짓고, ㉲에서는 물과 풀을 찾아 옮겨 다니기 때문에 접었다 폈다 할 수 있는 천막집에서 산다.","scoring_points":["두 곳의 기후 이름을 바르게 썼는가","두 기후의 특징을 썼는가","기후에 맞춘 집 모습을 견주어 썼는가"]},"explanation":["㉮ — 열대, ㉲ — 건조 초원이에요.","기후가 집 모습을 정해요.","띄운 바닥 vs 이동식 천막이에요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u1_review_d#25','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C9',4,'essay','teacher','추운 기후로 가는 두 길을 설명하고, 각 길에서 만나는 기후 지역의 생활 모습을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"추운 기후로 가는 두 길을 설명하고, 각 길에서 만나는 기후 지역의 생활 모습을 하나씩 쓰세요.","answer_guide":{"answer":"예: 첫째 길은 적도에서 북쪽이나 남쪽으로 아주 멀리 고위도로 가는 것으로, 남극과 북극 주변의 한대 기후 지역에 닿는다. 이곳 사람들은 이끼가 자라는 곳에서 순록을 기르며 옮겨 다닌다. 둘째 길은 적도 주변이라도 높은 산 위로 오르는 것으로, 일 년 내내 서늘한 고산 기후 지역에 닿는다. 이곳 사람들은 알파카와 라마를 기르고 감자를 재배한다.","scoring_points":["고위도로 가는 길과 높이 오르는 길을 설명했는가","한대·고산 기후를 바르게 짝지었는가","각 기후의 생활 모습을 하나씩 썼는가"]},"explanation":["길 하나 — 고위도 → 한대예요.","길 둘 — 높은 산 → 고산이에요.","생활 모습도 달라요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
